k = '1' then Q <= D;		end if;	end process;		end Behavioral;Testbench - Verilogmodule t_Reg_4_bit ();  wire A3_beh, A2_beh, A1_beh, A0_beh;  wire A3_str, A2_str, A1_str, A0_str;  reg I3, I2, I1, I0, Clock, Clear_b;  wire [3: 0] I_data = {I3, I2, I1, I0};  wire [3: 0] A_beh = {A3_beh, A2_beh, A1_beh, A0_beh};  wire [3: 0] A_str = {A3_str, A2_str, A1_str, A0_str};  Reg_4_bit_beh M_beh (A3_beh, A2_beh, A1_beh, A0_beh, I3, I2, I1, I0, Clock, Clear_b);  Reg_4_bit_Str M_str (A3_str, A2_str, A1_str, A0_str, I3, I2, I1, I0, Clock, Clear_b);  initial #100 $finish;  initial begin Clock = 0; forever #5 Clock = ~Clock; end  initial begin Clear_b = 0; #2 Clear_b = 1; end  integer K;  initial begin    for (K = 0; K < 16; K = K + 1) begin {I3, I2, I1, I0} = K; #10 ; end  endendmodule	VHDLentity Reg_4_bit_vhdl is		port(A3, A2, A1, A0 : out bit; I3, I2, I1, I0, Clock, Clear: in bit); isend  always @ (posedge Clock, negedge Clear)    if (Clear == 0) {A3, A2, A1, A0} <= 4'b0;    else {A3, A2, A1, A0} <= {I3, I2, I1, I0};endmodulemodule Reg_4_bit_Str (output A3, A2, A1, A0, input I3, I2, I1, I0, Clock, Clear);  DFF M3DFF (A3, I3, Clock, Clear);  DFF M2DFF (A2, I2, Clock, Clear);  DFF M1DFF (A1, I1, Clock, Clear);  DFF M0DFF (A0, I0, Clock, Clear);endmodulemodule DFF(output reg Q, input D, clk, clear);  always @ (posedge clk, posedge clear)     if (clear == 0) Q <= 0; else Q <= D;endmodule6.32 (a) Verilogmodule Reg_4_bit_Load (output reg A3, A2, A1, A0, input I3, I2, I1, I0, Load, Clock, Clear);  always @ (posedge Clock, negedge Clear)    if (Clear == 0) {A3, A2, A1, A0} <= 4'b0;    else if (Load) {A3, A2, A1, A0} <= {I3, I2, I1, I0};endmodulemodule t_Reg_4_Load ();  wire A3_beh, A2_beh, A1_beh, A0_beh;   reg I3, I2, I1, I0, Load, Clock, Clear;  wire [3: 0] I_data = {I3, I2, I1, I0};  wire [3: 0] A_beh = {A3_beh, A2_beh, A1_beh, A0_beh};   Reg_4_bit_Load M0 (A3_beh, A2_beh, A1_beh, A0_beh, I3, I2, I1, I0, Load, Clock, Clear);  initial #100 $finish;  initial begin Clock = 0; forever #5 Clock = ~Clock; end  initial begin Clear = 0; #2 Clear = 1; end  integer K;  initial fork    #20 Load = 1;    #30 Load = 0;    #50 Load = 1;  join  initial begin    for (K = 0; K < 16; K = K + 1) begin {I3, I2, I1, I0} = K; #10 ; end  endendmodule		(a) VHDLentity Prob_6_32a_vhdl is		port (A3, A2, A1, A0: out bit; I3, I2, I1, I0, Load, Clock, Clear: in bit);end Prob_6_32a_vhdl;architecture Behavioral of Prob_6_32a_vhdl is		signal A_word: bit_vector (3 downto 0);begin		A3 <= A_word(3);		A2 <= A_word(2);		A1 <= A_word(1);		A0 <= A_word(0);		process  (Clock, Clear) begin 		if (Clear = '0')  then A_word <= "0000"; 			elsif (Load = '1') then A_word <= I3 & I2 & I1 & I0; 			end if;	end process;end Behavioral;			(b) Verilogmodule Reg_4_bit_Load_str (output A3, A2, A1, A0, input I3, I2, I1, I0, Load, Clock, Clear);  wire y3, y2, y1, y0;  mux_2 M3 (y3, A3, I3, Load);  mux_2 M2 (y2, A2, I2, Load);  mux_2 M1 (y1, A1, I1, Load);  mux_2 M0 (y0, A0, I0, Load);  DFF M3DFF (A3, y3, Clock, Clear);  DFF M2DFF (A2, y2, Clock, Clear);  DFF M1DFF (A1, y1, Clock, Clear);  DFF M0DFF (A0, y0, Clock, Clear);endmodulemodule DFF(output reg Q, input D, clk, clear);  always @ (posedge clk, posedge clear)     if (clear == 0) Q <= 0; else Q <= D;endmodulemodule mux_2 (output y, input a, b, sel);  assign y = sel ? a: b;endmodulemodule t_Reg_4_Load_str ();  wire A3, A2, A1, A0;  reg I3, I2, I1, I0, Load, Clock, Clear;  wire [3: 0] I_data = {I3, I2, I1, I0};  wire [3: 0] A = {A3, A2, A1, A0};   Reg_4_bit_Load_str M0 (A3, A2, A1, A0, I3, I2, I1, I0, Load, Clock, Clear);initial #100 $finish;  initial begin Clock = 0; forever #5 Clock = ~Clock; end  initial begin Clear = 0; #2 Clear = 1; end  integer K;  initial fork    #20 Load = 1;    #30 Load = 0    #50 Load = 1;    #80 Load = 0;  join  initial begin    for (K = 0; K < 16; K = K + 1) begin {I3, I2, I1, I0} = K;