 == 4'b1111);  always @ (posedge CLK, negedge Clear)  if (~Clear) 		A_count <= 4'b0000;  else if (Load)	A_count <= Data_in;  else if (Count) 	A_count <= A_count + 1'b1;  else 				A_count <= A_count;	// redundant statementendmodule// Note: a preferred description of the clock is given by:// initial begin CLK = 0; forever #5 CLK = ~CLK; end
6.34	Verilogmodule Shiftreg (SI, SO, CLK);  input		S	I, CLK;  output		SO;  reg	[3: 0] 	Q;  assign 		SO = Q[0];		// Output from LSB  always @ (posedge CLK)    Q = {SI, Q[3: 1]};			// Loads from MSBendmodule// Test plan// // Verify that data shift through the register// Set SI =1 at startup// Hold SI =1 for 8 clock cycles then set to 0// Verify that data shifts out of the register correctlymodule t_Shiftreg;  reg	SI, CLK;  wire	SO;  Shiftreg M0 (SI, SO, CLK);  initial #130 $finish;  initial begin CLK = 0; forever #5 CLK = ~CLK; end  initial fork    SI = 1'b1;    #80 SI = 0;  joinendmodule			VHDLentity Shiftreg is   port (SI, CLK: in bit; SO: out bit);end Shiftreg;architecture Behavioral of Shiftreg is   signal Q: Std_Bit_Vector (3 down to 0);   begin      SO <= Q(0);      process (CLK) begin         if CLK'event and CLK = '1' then Q <= SI & Q(3: 1);      end process;end Behavioral;  	entity t_Shiftreg is	end t_Shiftreg;	architecture Testbench of t_Shiftreg is	   component Shiftreg port (SI, CLK: in Std_Logic; SO: out Std_Logic);	   signal t_CLK, t_SI, t_SO: Std_Logic;	begin	   UUT Shiftreg port map (SI => t_SI, CLK => t_CLK: SO => t_SO);	   t_SI <= '1';	   t_SI <= 0 after 80 ns	   process begin      	      t_CLK <= '0';	      wait for 5 ns;	      t_CLK <= '1';	      wait for 5 ns;	   end process;	end Testbench;
