VHDLThe datapath into each flip-flop will be modified to include a 2-input mux. One input of the mux is connneced to the output of the flip-flop. The other input is connected to the data path that was previously connected to the flip-flop. A control signal is supplied to the mux so that the flip-flop appears to have a gated clock signal. When the machine is to be  idle (i.e., not shifting and not loading), the output of the flip-flop recirculates through the mux and back to the D-input of the flip-flop. The cells of register A have and additional mux to accomodate parallel load as well as ordinary operation.  The modified registers cells are shown below. Additionally, the output of the least significant bit of Register A connects to the input mux of the left-most cell of the register.entity Prob_6_43_Str_vhdl is	port (SO: out bit; data_A: in bit_vector (7 downto 0); D_in, load, shift, Clock, reset_b: in bit);end Prob_6_43_Str_vhdl;architecture Structural of Prob_6_43_Str_vhdl is	signal SO_A: bit;	-- Register A	component SReg8_with_Load port (SO: out bit; D_in: in bit; data: in bit_vector (7 downto 0); load, shift, Clock, reset_b: in bit); end component;	-- Register B	component SReg8 port (SO: out bit; D_in: in bit; shift, Clock, reset_b: in bit); end component;begin	-- Register A 	M_A: Sreg8_with_Load port map (SO => SO_A, D_in => D_in, data => data_A, load => load, shift => shift, Clock => clock, reset_b => reset_b);	-- Register B  	M_B: Sreg8 port map (SO => SO, D_in => SO_A, shift => shift, Clock => Clock, reset_b => reset_b);end structural;entity Sreg8_with_Load is	-- Register A	port (SO: out bit; D_in: in bit; data: in bit_vector (7 downto 0); load, shift, Clock, reset_b: in bit);end Sreg8_with_Load;architecture Structural of Sreg8_with_Load is  signal Q: bit_vector (7 downto 0);    component SR_A_cell port (Q: out bit; D, data, load, shift, Clock, reset_b: in bit); end component;begin  SO <= Q(0);  M7: SR_A_cell port map (Q(7), D_in, data(7), load, shift, Clock, reset_b);  M6: SR_A_cell port map (Q(6), Q(7), data(6), load, shift, Clock, reset_b);  M5: SR_A_cell port map (Q(5), Q(6), data(5), load, shift, Clock, reset_b);  M4: SR_A_cell port map (Q(4), Q(5), data(4), load, shift, Clock, reset_b);  M3: SR_A_cell port map (Q(3), Q(4), data(3), load, shift, Clock, reset_b);  M2: SR_A_cell port map (Q(2), Q(3), data(2), load, shift, Clock, reset_b);  M1: SR_A_cell port map (Q(1), Q(2), data(1), load, shift, Clock, reset_b);  M0: SR_A_cell port map (Q(0), Q(1), data(0), load, shift, Clock, reset_b);end Structural;entity Sreg8 is	-- Register B		port (SO: out bit; D_in: in bit; shift, Clock, reset_b: in bit);end Sreg8;architecture Structural of Sreg8 is  signal Q: bit_vector (7 downto 0);    component SR_B_cell port (Q: out bit; D_in, shift, Clock, reset_b: in bit); end component;begin  SO <= Q(0);  M7: SR_B_cell port map (Q => Q(7), D_in => D_in, shift => shift, Clock => Clock, reset_b => reset_b);  M6: SR_B_cell port map (Q => Q(6), D_in => Q(7), shift => shift, Clock => Clock, reset_b => reset_b);  M5: SR_B_cell port map (Q => Q(5), D_in => Q(6), shift => shift, Clock => Clock, reset_b => reset_b);  M4: SR_B_cell port map (Q => Q(4), D_in => Q(5), shift => shift, Clock => Clock, reset_b => reset_b);  M3: SR_B_cell port map (Q => Q(3), D_in => Q(4), shift => shift, Clock => Clock, reset_b => reset_b);  M2: SR_B_cell port map (Q => Q(2), D_in => Q(3), shift => shift, Clock => Clock, reset_b => reset_b);  M1: SR_B_cell port map (Q => Q(1), D_in => Q(2), shift => shift, Clock => Clock, reset_b => reset_b);  M0: SR_B_cell port map (Q => Q(0),   D_in => Q(1), shift => shift, Clock => Clock, reset_b => reset_b);end Structural;entity SR_A_cell is	port (Q: buffer bit; D_in, data, load, shift, Clock, reset_b: in bit);end SR_A_cell;architecture Structural of SR_A_cell is  signal y: bit;  component D_FF_with_load port (Q: buffer bit; data_S, data_P, load, shift, Clock, reset_b: in bit); end component;  component Mux_2 port (y : out bit; a, b, sel: in bit); end component;begin  M0: D_FF_with_load port map (Q => Q, data_S => y, data_P => data, load => load, shift => shift, Clock => Clock, reset_b => reset_b);  M1: Mux_2 port map (y, Q,  D_in, shift);end  Structural;entity D_FF_with_load is 	port (Q: out bit ; data_S, data_P, load, shift, Clock, reset_b: in bit);end D_FF_with_load;architecture Behavioral of D_FF_with_load isbegin  process (Clock, reset_b) begin    if (reset_b = '0') then Q <= '0';     elsif Clock'event and Clock = '1' then	if (load = '1') then Q <= data_P; else Q <= data_S; end if;    end if;  end process;end Behavioral;entity Mux_2 is	port (y: out bit; a, b, sel: in bit);end Mux_2;architecture behavioral of Mux_2 isbegin	 process (a, b, sel) begin 			if (sel = '1') then y <= b; else y <= a; end if;	end process;end Behavioral;entity SR_B_cell is	port (Q: buffer bit; D_in, shift, Clock, reset_b: in bit);end SR_B_cell;architecture Structural of SR_B_cell is  signal y: bit;  component D_FF port (Q: buffer bit; D, Clock, reset_b: in bit); end component;  component Mux_2 port (y : out bit; a, b, sel: in bit); end component;begin  M0: D_FF port map (Q => Q, D => y, Clock => Clock, reset_b => reset_b);  M1: Mux_2 port map (y, Q,  D_in, shift);end  Structural;entity D_FF is 	port (Q: out bit ; D, Clock, reset_b: in bit);end D_FF;architecture Behavioral of D_FF isbegin  process (Clock, reset_b) begin    if (reset_b = '0') then Q <= '0';     elsif Clock'event and Clock = '1' then	Q <= D;    end if;  end process;end Behavioral;6.44   // See Figure 6.5 // Note: Sum is stored in shift register A; carry is stored in Q // Note: Clear is active-low.Verilogmodule Prob_6_44_Str (output SO, input [7: 0] data_A, data_B, input S_in, load, Shift_control, CLK, Clear);  supply0 gnd;  wire sum, carry;  assign SO = sum;  wire SO_A, SO_B;  Shift_Reg_gated_clock M_A (SO_A, sum, data_A, load, Shift_control, CLK, Clear);  Shift_Reg_gated_clock M_B (SO_B,  S_in, data_B, load, Shift_control, CLK, Clear);  FA M_FA (carry, sum, SO_A, SO_B, Q);  DFF_gated M_FF (Q, carry, Shift_control, CLK, Clear);endmodulemodule Shift_Reg_gated_clock (output SO, input S_in, input [7: 0] data, input load, Shift_control, Clock, reset_b);  reg [7: 0] SReg;  assign SO = SReg[0];    always @ (posedge Clock, negedge reset_b)    if (reset_b == 0) SReg <= 0;     else if (load) SReg <= data;     else if (Shift_control) SReg <= {S_in, SReg[7: 1]};endmodulemodule DFF_gated (output Q, input D, Shift_control, Clock, reset_b);  DFF M_DFF (Q,   D_internal, Clock, reset_b);  Mux_2 M_Mux (D_internal, Q, D, Shift_control);endmodulemodule DFF (output reg Q, input D, Clock, reset_b);  always @ (posedge Clock, negedge reset_b)    if (reset_b == 0) Q <= 0; else Q <= D;endmodulemodule Mux_2 (output reg y, input a, b, sel);  always @ (a, b, sel) if (sel ==1) y = b; else y = a; endmodule module FA (output reg carry, sum, input a, b, C_in);  always @ (a, b, C_in) {carry, sum} = a + b + C_in;endmodulemodule t_Prob_6_44_Str ();  wire SO;  reg SI, load, Shift_control, Clock, Clear;    reg [7: 0] data_A, data_B;  Prob_6_44_Str M0 (SO, data_A, data_B, SI, load, Shift_control, Clock, Clear);  initial #200 $finish;  initial begin Clock = 0; forever #5 Clock = ~Clock; end  initial begin #2 Clear = 0; #4 Clear = 1; end   initial fork    data_A =  8'hAA;	//8'h ff;     data_B = 8'h55;	//8'h01;     SI = 0;    #20 load = 1;    #30 load = 0;    #50 Shift_control = 1;    #50 begin repeat (8) @ (posedge Clock) ;         #5 Shift_control = 0;    end  joinendmodule
VHDLentity Prob_6_44_Str_VHDL is	port (SO: out bit; data_A, data_B: in bit_vector (7 downto 0); S_in, load, Shift_control, CLK, Clear: in bit);end Prob_6_44_Str_VHDL;architecture Structural of Prob_6_44_Str_VHDL is  signal gnd: bit;  signal sum, carry: bit;signal SO_A, SO_B, Q: bit;component  Shift_Reg_gated_clock port (SO: out bit; S_in: in bit; data: in bit_vector (7 downto 0); load, Shift_control, Clock, reset_b: in bit); end component;component D_FF_gated port (Q: out bit; D, Shift_control, Clock, reset_b:in bit); end component;component FA port (carry, sum: out bit; a, b, C_in: in bit); end component;component Mux_2 port (y: out bit; a, b, sel: in bit); end component;begin  SO <= sum;  M_A: Shift_Reg_gated_clock port map (SO_A, sum, data_A, load, Shift_control, CLK, Clear);  M_B: Shift_Reg_gated_clock port map (SO_B,  S_in, data_B, load, Shift_control, CLK, Clear);  M_FA: FA port map (carry, sum, SO_A, SO_B, Q);  M_DFF: D_FF_gated port map (Q, carry, Shift_control, CLK, Clear);end Structural;entity Shift_Reg_gated_clock is	port (SO: out bit; S_in: in bit; data: in bit_vector (7 downto 0); load, Shift_control, Clock, reset_b: in bit);end Shift_Reg_gated_clock;architecture Behavioral of Shift_Reg_gated_clock is  signal Sreg: bit_vector (7 downto 0);begin   SO <= Sreg(0);    process (Clock, reset_b) begin    	if (reset_b = '0') then SReg <= "00000000";     	elsif Clock'event and Clock = '1' then			if (load = '1') then SReg <= data;     			elsif (Shift_control = '1') then SReg <= S_in & Sreg(7 downto 1);			end if;	end if;    end process;end Behavioral;entity D_FF_gated is	port (Q: buffer bit ; D, Shift_control, Clock, reset_b: in bit);end D_FF_gated;architecture Structural of D_FF_gated is   signal D_internal: bit;   component D_FF port (Q: buffer bit;   D: in bit; Clock, reset_b: in bit); end component;   component Mux_2 port (y: out bit; a, b, sel: in bit); end component;begin   M_D_FF: D_FF port map (Q,   D_internal, Clock, reset_b);   M_Mux:  Mux_2 port map (D_internal, Q, D, Shift_control);end Structural;entity D_FF is	port (Q: out bit; D: in bit; Clock, reset_b: in bit);end D_FF;architecture Behavioral of D_FF isbegin	process (Clock, reset_b) begin    if (reset_b = '0') then Q <= '0'; 	elsif Clock'event and Clock = '1' then Q <= D; end if;    end process;end  Behavioral;entity Mux_2 is	port (y: out bit; a, b, sel: in bit);end Mux_2;architecture Behavioral of Mux_2 isbegin  process (a, b, sel) begin	if (sel = '1') then y <= b; 	else y <= a;	end if; end process;end  Behavioral; entity FA is	port (carry, sum: out bit; a, b, C_in: in bit);end FA;architecture Behavioral of FA isbegin	process (a, b, C_in) begin  			sum <= a xor b xor C_in;			carry <= ((a xor b) and C_in) or ( a and b);	end process;end Behavioral;6.45		Verilogmodule Prob_6_45 (output reg y_out, input start, clock, reset_bar);  parameter 			s0 = 4'b0000,		s1 = 4'b0001,		s2 = 4'b0010,		s3 = 4'b0011,		s4 = 4'b0100,		s5 = 4'b0101,		s6 = 4'b0110,		s7 = 4'b0111,		s8 = 4'b1000;  reg [3: 0] 	state, next_state;  always @ (posedge clock, negedge reset_bar)     if (!reset_bar) state <= s0; else state <= next_state;  always @ (state, start) begin    y_out = 1'b0;    case (state)      s0:	if (start) next_state = s1; else next_state = s0;      s1:	begin next_state = s2; y_out = 1; end      s2:	begin next_state = s3; y_out = 1; end      s3:	begin next_state = s4; y_out = 1; end      s4:	begin next_state = s5; y_out = 1; end      s5:	begin next_state = s6; y_out = 1; end      s6:	begin next_state = s7; y_out = 1; end      s7:	begin next_state = s8; y_out = 1; end      s8:	begin next_state = s0; y_out = 1; end      default: next_state = s0;    endcase  endendmodule// Test plan// Verify the following:// Power-up reset// Response to start in initial state// Reset on-the-fly// Response to re-assertion of start after reset on-the-fly// 8-cycle counting sequence// Ignore start during counting sequence// Return to initial state after 8 cycles and await start// Remain in initial state for one clock if start is asserted when the state is enteredmodule t_Prob_6_45;  wire 	y_out;  reg 	start, clock, reset_bar;    Prob_6_45 M0 (y_out, start, clock, reset_bar);  initial #300 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork    reset_bar = 0;    #2 reset_bar = 1;    #10 start = 1;    #20 start = 0;    #30 reset_bar = 0;    #50 reset_bar = 1;    #80 start = 1;    #90 start = 0;    #130 start = 1;    #140 start = 0;    #180 start = 1;  joinendmodule		vhdllibrary IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;entity Prob_6_45_vhdl is   port (y_out: out std_Logic; start, clock, reset_bar: in bit);end Prob_6_45_;architecture Behavioral of Prob_6_45_vhdl is  constant 			s0: Std_Logic_vector (3 downto 0)  = "0000",		s1: Std_Logic_vector (3 downto 0)   = "0001",		s2: Std_Logic_vector (3 downto 0)   = "0010",		s3: Std_Logic_vector (3 downto 0)   = "0011",		s4: Std_Logic_vector (3 downto 0)   = "0100",		s5: Std_Logic_vector (3 downto 0)   = "0101",		s6: Std_Logic_vector (3 downto 0)   = "0110",		s7: Std_Logic_vector (3 downto 0)   = "0111",		s8: Std_Logic_vector (3 downto 0)   = "1000";  signal state, next_state: Std_Logic_Vector (3 downto 0);begin  process (clock, reset_bar) begin    if reset_bar = 0 then state <= s0; elsif clock'event and clock = 1 then       state <= next_state; end if;   end process;  process (state, start) begin    	     		 next_state <= s0;			 y_out <= '0';    case state is      when s0 =>	if (start = '1') next_state <= s1; else next_state <= s0; end if;      when s1 =>	next_state <= s2; y_out <= '1';       when s2 =>	next_state <= s3; y_out <= '1';       when s3 =>	next_state <= s4; y_out <= '1';       when s4 =>	next_state <= s5; y_out <= '1';       when s5 =>	next_state <= s6; y_out <= '1';   