, reset_b);  initial #200 $finish;  initial begin clk = 0; forever #5 clk = ~clk; end  initial fork    // test reset action load    #3 reset_b = 1;    #4 reset_b = 0;    #9 reset_b = 1;    // test parallel load    #10 I_par = 4'hA;    #10 {s1, s0} = 2'b11;    // test shift right    #30 MSB_in = 1'b0;    #30 {s1, s0} = 2'b01;    // test shift left    #80 LSB_in = 1'b1;    #80 {s1, s0} = 2'b10;    // test circulation of data   #130 {s1, s0} = 2'b11;    #140 {s1, s0} = 2'b00;   // test reset on the fly    #150 reset_b = 1'b0;    #160 reset_b = 1'b1;    #160 {s1, s0} = 2'b11;  joinendmodule			VHDL-- Behavioral description of a 4-bit universal shift register -- Fig. 6.7 and Table 6.3entity Prob_6_49_vhdl is -- Shift_Register_4_beh_vhdl  	port (A_par: buffer bit_vector (3 downto 0); I_par: in bit_vector (3 downto 0); 			s1, s0, MSB_in, LSB_in, CLK, Clear: in bit);end Shift_Register_4_beh_vhdl;architecture Behavioral of Prob_6_49_Shift_Register_4_beh_vhdl isbegin  process (CLK, Clear) begin    if (Clear = '0') then A_par <= "0000";    elsif CLK'event and CLK = '1' then      case (s1 & s0) is        when "00" => A_par <= A_par;									-- No change        when "01" =>  A_par <= MSB_in & A_par(3 downto 1);		-- Shift right        when "10" =>  A_par <= A_par(2 downto 0) & LSB_in;		-- Shift left        when "11" =>  A_par <= I_par;									-- Parallel load        end case;   end if;end process;end  Behavioral;6.50  (a) See problem 6.27.module Prob_6_50a (output reg [2: 0] count, input clk, reset_b);  always @ (posedge clk, negedge reset_b)    if (!reset_b) count <= 0;    else case (count)      3'd0:	count <= 3'd1;      3'd1:	count <= 3'd2;      3'd2:	count <= 3'd3;      3'd3:	count <= 3'd4;      3'd4:	count <= 3'd5;      3'd5:	count <= 3'd6;		3'd6:	count <= 3'd0;      default:	count <= 3'd0;    endcaseendmodulemodule t_Prob_6_50a;  wire [2: 0] count;  reg clock, reset_b  ;  Prob_6_50a M0 (count,