>	y <= in2;			when "11" =>	y <= in3;		end case;	end process;end Behavioral;entity D_FF is	port (q: out bit;   d, clk, clr_b: in bit);end D_FF;architecture Behavioral of D_FF isbegin  process   (  clk,   clr_b) begin    if (clr_b = '0') then q <= '0'; else q <= d; end if;  end process;endmodule6.53	 		Verilogmodule Prob_6_53 (output reg [3:0] SR_A, input Shift_control, SI, CLK, Clear_b);  reg (3: 0] SR_B;  wire Sum, Carry;  wire SO_A = SR_A[3];  wire SO_B = SR_B[3];  wire SI_A = Sum;  wire SI_B = SI;  wire Q;  always @ (posedge CLK)    if (Clear_b == 1'b0) SR_A<= 4'b0; else if (Shift_control) SR_A <= {Sum, SR_A[3:1]};  always @ (posedge CLK)    if (Clear_b == 1'b0) SR_B <= 4'b0; else if (Shift_control) SR_B <= {SI, SR_B[3:1]};  FA M0 (Sum, Carry, SO_A, SO_B, Q);  and (clk_to_DFF, CLK, Shift_control);		// Caution: gated clock  DFF M1 (Q, Carry, clk_to_DFF, Clear_b);endmodulemodule FA (output S, C, input x, y, z);  assign {C, S} = x + y + z;endmodulemodule DFF (output reg Q, input D, C, Clear_b);  always @ (posedge C) if (Clear_b == 1'b0) Q <= 1'b0; else Q <= D;endmodulemodule t_Prob_6_53 ();  wire [3:0] SR_A;  reg Shift_control, SI, CLK, Clear_b;  Prob_6_53 M0 (SR_A, Shift_control, SI, CLK, Clear_b);  initial #300 $finish;  initial begin CLK = 0; forever #5 CLK = ~CLK; end  initial fork     Clear_b = 0;			    #20 Clear_b = 1;		        #40 Shift_control = 1;    SI = 0;  // Sequence of 1s    /*      #60 SI = 1;    #70 SI = 0;    #100 SI = 1;    #110 SI = 0;    #140 SI = 1;    #150 SI = 0;    #180 SI = 1;    #190 SI = 0;  */  // Sequence of threes    #60 SI = 1;    #80 SI = 0;    #100 SI = 1;    #120 SI = 0;    #140 SI = 1;    #160 SI = 0;    #180 SI = 1;    #200 SI = 0;  joinendmoduleSimulation results for accumulating a sequence of four 1s.Simulation results for accumulating a sequence of four 3s.Additional test patterns are left as an exercise.VHDLentity Prob_6_53_vhdl is	port (SR_A: buffer bit_vector (3 downto 0); Shift_control, SI, CLK, Clear_b: in bit);end Prob_6_53_vhdl;architecture Behavioral of Prob_6_53_vhdl is  signal SR_B: bit_vector (3 downto 0);   signal  Sum, Carry: bit;  signal SO_A, SO_B: bit;  signal SI_A, SI_B: bit;  signal Q: bit;  signal clk_to_DFF;  component FA port (carry, sum: out bit; a, b, C_in: in bit); end component;component D_FF port (Q: out bit; D, C, Clear_b: in bit);	end component;component and2_gate   port (y: out bit; xin1, xin2: in bit); end component;begin   	SO_A <= SR_A(3);	SO_B <= SR_B(3); 	SI_A <= Sum;	SI_B <= SI;  process   (CLK) begin 	if CLK'event and CLK = '1' then		if (Clear_b = '0') then SR_A <= "0000"; 		elsif (Shift_control = '1') then SR_A <= Sum & SR_A(3 downto 1);		end if;	end if;  end process;  process (CLK) begin    if CLK'event and CLK = '1' then	if (Clear_b = '0') then SR_B <= "0000"; 	else if (Shift_control = '1') then SR_B <= SI & SR_B(3 downto 1);	end if;   end if;end if; end process;  M0: FA  port map (Carry, Sum, SO_A, SO_B, Q);  M1: and2_gate port map (clk_to_DFF, CLK, Shift_control);		-- Caution: gated clock  M2: D_FF port map (Q, Carry, clk_to_DFF, Clear_b);end Behavioral;entity FA is	port (carry, sum: out bit; a, b, C_in: in bit);end FA;architecture Behavioral of FA isbegin	process (a, b, C_in) begin  			sum <= a xor b xor C_in;			carry <= ((a xor b) and C_in) or (  a and b);	end process;end Behavioral;entity D_FF is	port (Q: out bit; D, C, Clear_b: in bit);end D_FF;architecture Behavioral of D_FF isbegin  process (C) begin 	if C'event and C = '1' then		if (Clear_b = '0') then Q <= '0';		else Q <= D;		end if;	end if;end process;end Behavioral;entity and2_gate is  port (y: out bit; xin1, xin2: in bit);end and2_gate;architecture Behavioral of and2_gate isbegin	y <= xin1 and xin2;end Behavioral;
6.54--	 	Verilogmodule Prob_6_54 (output reg [3:0] SR_A, input Shift_control, SI, CLK, Clear_b);  reg [3:0] SR_B;  wire S;  wire Q;  wire SI_A = S;  wire SO_A = SR_A[0];  wire SO_B = SR_B[0];  wire SI_B = SI;  wire J_in, K_in;  and (J_in, SO_A, SO_B);  nor (K_in, SO_A, SO_B);  xor (S, SO_A, SO_B, Q);  and (clk_to_JKFF, Shift_control, CLK);  always @ (posedge CLK)    if (Clear_b == 1'b0) SR_A<= 4'b0; else if (Shift_control) SR_A <= {SI_A, SR_A[3:1]};  always @ (posedge CLK)    if (Clear_b == 1'b0) SR_B <= 4'b0; else if (Shift_control) SR_B <= {SI_B, SR_B[3:1]};  and (clk_to_JKFF, CLK, Shift_control);		// Caution: gated clock  JKFF M1 (Q, J_in, K_in, clk_to_JKFF, Clear_b);endmodulemodule FA (output S, C, input x, y, z);  assign {C, S} = x + y + z;endmodulemodule JKFF (buffer reg Q, input J_in, K_in, C, Clear_b);  always @ (posedge C) if (Clear_b == 1'b0) Q <= 1'b0; else    case ({J_in, K_in})      2'b00:		Q <= Q;      2'b01:		Q <= 1'b0;      2'b10:		Q <= 1'b1;      2'b11:		Q <= ~Q;    endcaseendmodulemodule t_Prob_6_54 ();  wire [3:0] SR_A;  reg Shift_control, SI, CLK, Clear_b;  Prob_6_54 M0 (SR_A, Shift_control, SI, CLK, Clear_b);  //initial #200 $finish;		// sequence of 1s  initial #400 $finish;			// sequence of 3s  initial begin CLK = 0; forever #5 CLK = ~CLK; end  initial fork     Clear_b = 0;			    #20 Clear_b = 1;		        #40 Shift_control = 1;    SI = 0;  // Sequence of 1s    /*      #60 SI = 1;    #70 SI = 0;    #100 SI = 1;    #110 SI = 0;    #140 SI = 1;    #150 SI = 0;    #180 SI = 1;    #190 SI = 0;  */  // Sequence of threes    #60 SI = 1;    #80 SI = 0;    #100 SI = 1;    #120 SI = 0;    #140 SI = 1;    #160 SI = 0;    #180 SI = 1;    #200 SI = 0;  joinendmoduleSimulation results:  Accumulation of a sequence of four 1s.
