2, CLK, Clear_b);  M2: JK_FF port map(A2, w13, w14, CLK, Clear_b);  M3: JK_FF port map(A3, w15, w16, CLK, Clear_b);end Structural;entity JK_FF is	port (Q: buffer bit; J_in, K_in, C, Clear_b: in bit);end JK_FF;architecture Behavioral of JK_FF isbegin  	process (C) begin			if C'event and C = '1' then				if (Clear_b = '0' ) then Q <= '0'; 		else    					case (J_in & K_in) is      						when "00" =>		Q <= Q;      						when "01" =>		Q <= '0';      						when "10" =>		Q <= '1';      						when "11" =>		Q <= not Q;						end case;		 end if;		end if;	end process;end Behavioral;entity and2_gate is  port (y: out bit; xin1, xin2: in bit);end and2_gate;architecture Behavioral of and2_gate isbegin	y <= xin1 and xin2;end Behavioral;entity and3_gate is  port (y: out bit; xin1, xin2, xin3: in bit);end and3_gate;architecture Behavioral of and3_gate isbegin	y <= xin1 and xin2 and xin3;end Behavioral;entity and4_gate is  port (y: out bit; xin1, xin2, xin3, xin4: in bit);end and4_gate;architecture Behavioral of and4_gate isbegin	y <= xin1 and xin2 and xin3 and xin4;end Behavioral;entity and5_gate is  port (y: out bit; xin1, xin2, xin3, xin4, xin5: in bit);end and5_gate;architecture Behavioral of and5_gate isbegin	y <= xin1 and xin2 and xin3 and xin4 and xin5;end Behavioral;entity or2_gate is  port (y: out bit; xin1, xin2: in bit);end or2_gate;architecture Behavioral of or2_gate isbegin	y <= xin1 or xin2;end Behavioral;entity not_gate is  port (y: out bit; xin1: in bit);end not_gate;architecture Behavioral of not_gate isbegin	y <= not xin1;end Behavioral;6.58 (B) Verilog - Behavioral Modelmodule Prob_6_58b (output reg[3:0] A_count, output C_out, 		input [3:0] Data_in, input Count, Load, CLK, Clear_b);		wire A3 = A_count [3];		wire A2 = A_count [2];		wire A1 = A_count [1];		wire A0 = A_count [0];		wire Load_bar = !Load;		assign C_out = A3 && A2 && A1 && A0 && (Count && Load_bar);	always @ (posedge CLK, negedge Clear_b)		if (Clear_b == 1'b0) A_count <= 4'b0000;		else if (Load == 1'b1) A_count  <= Data_in; 		else if (Count == 1'b1) A_count <= A_count + 1'b1;endmodule	// Also see HDL Example 6.3)6.58 (B) VHDL - Behavioral Modellibrary IEEE;ise IEEE.Std_Logic_1164.alluse IEEE.Std_Logic_arith.allentity Prob_6_58b_vhdl is	port (A_count: buffer unsigned  (3 downto 0); C_out: out Std_Logic; 			Data_in: in unsigned (3 downto 0); Count, Load, CLK, Clear_b: in bit);end Prob_6_58b_vhdl;architecture Behavioral of Prob_6_58b_vhdl is	signal Load_bar: bit;beginLoad_bar <= not Load;	C_out <= '1' when A_count = 15 and Count = '1' and Load_bar = '1';process (CLK, Clear_b)if (Clear_b = ''0') then A_count <= "0000";elsif CLK'event and CLK = '1' then	if (Load = '1') then A_count  <= Data_in;	elsif (Count = '1') then A_count <= A_count + 1;	else A_count <= A_count;end if;end process;end Behavioral;Also see HDL Example 6.3.
6.59	(a) Verilog		Circuit is modified for gated clock controlled by count.		module Prob_6_59a (out [3:0] STRC, in [3:0] I_par, in Count, Load, CLK, Clear_b);			wire D_A, D_B, D_C, D_E;			wire E_bar = !STRC{0];			mux_2x1 mux_A (D_A, STRC[3], E_bar, count);			D_FF D_FF_A (STRC[3], D_A, clk, clr_bar);			mux_2x1 mux_B (D_B, STRC[2], STRC[3], count);			D_FF D_FF_B (STRC[2], D_B, clk, clr_bar);			mux_2x1 mux_C (D_C, STRC[1], STRC[2], count);			D_FF D_FF_B (STRC[1], D_C, clk, clr_bar);			mux_2x1 mux_C (D_E, STRC[0], STRC[1], count);			D_FF D_FF_B (STRC[0], D_E, clk, clr_bar);		endmodule		module D_FF (output Q, input D, clk, clr_bar);			always @ (posedge clk, negedge clr_bar) 				if clr_bar == 1'b0) Q <= 1'b0;				else Q <= D;		endmodule;		module mux_2x1 (out y, in xin1, xin2, sel);			always @ (xin1, xin2, sel)				if (sel == 1'b0) y = xin1;				else if (sel == 1'b1) y = xin2;		endmodule;		(a) VHDLlibrary IEEE;use IEEE.Std_Logic_1164.all;entity Prob_6_59a_vhdl is	port  (STRC: buffer Std_Logic_vector (3 downto 0); I_par: in Std_Logic_vector (3 downto 0);	Count, Load, CLK, clr_b: in bit);end Prob_6_59a_vhdl;architecture Structural of Prob_6_59a_vhdl is	signal E_bar: Std_Logic; 			component D_FF port (Q: out Std_Logic; D: in Std_Logic; clk, clr_bar: in bit); end component;		begin			E_bar <= not STRC(0);			M_A: D_FF port map (Q => STRC(3), D => E_bar, clk => clk, clr_bar => clr_bar);			M_B: D_FF port map (Q => STRC(2), D => STRC(3), clk => clk, clr_bar => clr_bar);			M_C: D_FF port map (Q => STRC(1), D => STRC(2), clk => clk, clr_bar => clr_bar);			M_E: D_FF port map (Q => STRC(0), D => STRC(1), clk => clk, clr_bar => clr_bar);		end Structural;entity D_FF is	port (Q: out Std_Logic; D: in Std_Logic; clk, clr_bar: in bit);end D_FF;architecture Behavioral of D_FF isbegin	process (clk, clr_bar) begin		if cl_bar = '0' then Q <= '0';		elsif clk'event and clk = '1' then Q <= D;		end if;	end process;end Behavioral;		(b) Verilogmodule Prob_6_59b_ver (output reg [3:0] STRC, input [3:0] I_par, input Count, Load, CLK, Clear_b);  wire E_bar = !STRC[0];   always @ (posedge CLK) if (Clear_b == 1'b0) STRC <= 4'b0; else    if (Load) STRC <= I_par    else if (Count) STRC <= {E_bar, STRC[3:1]};endmodulemodule t_Prob_6_59b_ver ();wire [3:0]  t_STRC;reg t_Load, t_Count, t_CLK, t_Clear_b;reg [3:0] t_I_par;  Prob_6_59b_ver M0 (t_STRC, t_I_par, t_Count, t_Load, t_CLK, t_Clear_b);  initial #400 $finish;  initial begin t_CLK = 0; forever #5 t_CLK = ~t_CLK; end  initial fork    t_I_par = 4'b0101;	// Data for parallel load    t_Clear_b = 0;    #20 t_Clear_b = 1;    t_Count = 0;    #50 t_Count = 1;		// Counting    #150 t_Count = 0;		// Pause    #200 t_Count = 1;		// Resume counting    t_Load = 0;    #250 t_Load = 1;		// Parallel load    #260 t_Load = 0;  joinendmodule		(b) VHDLlibrary IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;entity Prob_6_59b_vhdl is	port  (STRC: buffer Std_Logic_vector (3 downto 0); I_par: in Std_Logic_vector (3 downto 0);	Count, Load, CLK, Clear_b: in bit);end Prob_6_59b_vhdl;architecture Behavioral of Prob_6_59b_vhdl is	signal E_bar <= not STRC(0);begin	process (CLK) begin 		if CLK'event and CLK = '1' then			if (Clear_b = '0') then STRC <= "0000";      			elsif (Load = '1') then STRC <= I_par;    			elsif (Count = '1') STRC <= E_bar & STRC (3 downto 1);			end if;		end if;	end process;end  Behavioral;
