8.7	RTL notation:S0: Initial state: if (start = 1) then (RA ? data_A, RB ? data_B, go to S1).S1: {Carry, RA} ? RA + (2’s complement of RB), go to S2.S2: If (borrow = 0) go to S0. If (borrow = 1) then RA ? (2’s complement of RA), go to S0.      Block diagram and ASMD chart:module Subtractor_P8_7   (output done, output [7:0] result, input [7: 0] data_A, data_B, input  start, clock, reset_b);   Controller_P8_7 M0 (Load_A_B, Subtract, Convert, done, start, borrow, clock, reset_b);  Datapath_P8_7 M1 (result, borrow, data_A, data_B, Load_A_B, Subtract, Convert, clock, reset_b);endmodulemodule Controller_P8_7 (output reg Load_A_B, Subtract, output reg Convert, output done,  input start, borrow, clock, reset_b);  parameter  S0 = 2'b00, S1 = 2'b01, S2 = 2'b10;  reg [1: 0] state, next_state;  assign done = (state == S0);  always @ (posedge clock, negedge reset_b)     if (!reset_b) state <= S0; else state <= next_state;  always @ (state, start, borrow) begin    Load_A_B = 0;    Subtract = 0;    Convert = 0;        case (state)      S0:		if (start) begin Load_A_B = 1; next_state = S1; end      S1:		begin 	Subtract = 1; next_state = S2; end      S2:		 begin next_state = S0; if (borrow) Convert = 1; end      default:	next_state = S0;    endcase  endendmodulemodule Datapath_P8_7 (output [7: 0] result, output borrow, input [7: 0] data_A, data_B,   input Load_A_B, Subtract, Convert, clock, reset_b);  reg		carry;reg [8:0] diff;  reg [7: 0]	RA, RB;  assign 	borrow = carry;  assign	result = RA;  always @ (posedge clock, negedge reset_b)    if (!reset_b) begin carry <= 1'b0; RA <= 8'b0000_0000; RB <= 8'b0000_0000; end    else begin      if (Load_A_B) begin RA <= data_A; RB <= data_B; end      else if (Subtract) {carry, RA} <= RA +  ~RB + 1;      // In the statement above, the math of the LHS is done to the wordlength of the LHS      // The statement below is more explicit about how the math for subtraction is done:      // else if (Subtract) {carry, RA} <= {1'b0, RA} + {1'b1, ~RB } + 9'b0000_0001;      // If the 9-th bit is not considered, the 2s complement operation will generate a carry bit,       //  and borrow must be formed as borrow = ~carry.       else if (Convert) RA <= ~RA + 8'b0000_0001;    endendmodule // Test plan – Verify;// Power-up reset// Subtraction with data_A > data_B// Subtraction with data_A < data_B// Subtraction with data_A = data_B// Reset on-the-fly: left as an exercisemodule t_Subtractor_P8_7;  wire 			done;  wire	[7:0] 	result;  reg 	[7: 0] 	data_A, data_B;  reg  			start, clock, reset_b;  Subtractor_P8_7 M0 (done, result, data_A, data_B, start, clock, reset_b);  initial #200 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork     reset_b = 0;       #2 reset_b = 1;     #90 reset_b = 1;    #92 reset_b = 1;  join  initial fork    #20 start = 1;    #30 start = 0;    #70 start = 1;    #110 start = 1;  join  initial fork    data_A = 8'd50;    data_B = 8'd20;    #50 data_A = 8'd20;    #50 data_B = 8'd50;    #100 data_A = 8'd50;    #100 data_B = 8'd50;  joinendmoduleVHDLentity Datapath_P8_7 is   port (result: out std_logic_vector (7 downto 0);	data_a, data_b: in std_logic_vector (7 downto 0); Load_A_B, Subtract, Convert, clock: in 	std_logic; borrow: out std_logic);end Datapath_P8_7;architecture Behavioral of Datpath_P8_7 isbegin   process (clock, reset_b) begin      if reset_b'event and reset_b = '0' then carry <= 0; Reg_A <= "00000000";         Reg_B <= "00000000";      elsif clock'event and clock = 1 then      if Load_A_B = 1 then Reg_A <= data_A; Reg_B <= data_B;       elsif Subtract = 1 then carry & Reg_A <= Reg_A + (not Reg_b) + 1;      elsif Convert then Reg_A <= (not Reg_A) + "00000001"; end if;end Behavioral;beginentity Controller_P8_7 is   port (Load_A_B, Subtract, Convert, done: out Std_Logic; start, borrow, clock, 	reset_b: in Std_Logic);end  Controller_P8_7;architecture Behavioral of Controller_P8_7 is   constant S0 = "00', S1 = "01", S2 = "10";   signal state, next_state: std_logic_vector (1 downto 0);beginprocess (clock, reset_b) begin   if reset_b'event and reset_b = 0 then state <= S0;   elsif clock'event and clock =1 then state <= next_state; end if;end process;process (state, start, borrow) begin   Load_A_B <= 0;   Subtract <= 0;   Convert <= 0;   case state is      when S0 => if start = 1 then Load_A_B <= 1; next_state <= S1; end if;      when S1 => Subtract <= 1; next_state <= S2;       when S2 => next_state <= S0; if borow = 1 then convert = 1; end if;      when others next_state <= S0;end process;end Behavioral;entity Subtractor_P8_7 is   port (done: out std_logic; result: out std_logic_vector (7 downto 0);	data_a, data_b: in std_logic_vector (7 downto 0); start, clock, reset_b: in std_logic);end Subtractor_P8_7; architecture ASMD is    component Controller_P8_7 is   port (Load_A_B, Subtract, Convert, done: out Std_Logic; start, borrow, clock, 	reset_b: in Std_Logic);   end component;   component Datapath_P8_7 is   port (result: out std_logic_vector (7 downto 0);	data_a, data_b: in std_logic_vector (7 downto 0); Load_A_B, Subtract, Convert, clock: in 	std_logic; borrow: out std_logic);end component;beginM0: Controller_P8_7    port map (Load_A_B, Subtract, Convert, done, start, borrow, clock, reset_b);M1: Datapath_P8_7    port map(result, data_a, data_b, Load_A_B, Subtract, Convert, clock, borrow);end ASMD;
8.8	RTL notation:S0:  if (start = 1) AR ? input data, BR ? input data, go to S1.S1: if (AR [15]) = 1 (sign bit negative) then CR ? AR(shifted right, sign extension).else if (positive non-zero) then (Overflow ? BR([15] ? [14]), CR ? BR(shifted left)else if (AR = 0) then (CR ? 0).module Prob_8_8 (output done, input [15: 0] data_AR, data_BR, input  start, clock, reset_b);   Controller_P8_8 M0 (    Ld_AR_BR, Div_AR_x2_CR, Mul_BR_x2_CR, Clr_CR, done,     start, AR_lt_0, AR_gt_0, AR_eq_0, clock, reset_b  );  Datapath_P8_8 M1 (    Overflow, AR_lt_0, AR_gt_0, AR_eq_0, data_AR, data_BR,     Ld_AR_BR, Div_AR_x2_CR, Mul_BR_x2_CR, Clr_CR, clock, reset_b  );endmodule
module Controller_P8_8 (  output reg Ld_AR_BR, Div_AR_x2_CR, Mul_BR_x2_CR, Clr_CR,   output done, input start, AR_lt_0, AR_gt_0, AR_eq_0, clock, reset_b);  parameter  S0 = 1'b0, S1 = 1'b1;  reg state, next_state;  assign done = (state == S0);  always @ (posedge clock, negedge reset_b)     if (!reset_b) state <= S0; else state <= next_state;  always @ (state, start, AR_lt_0, AR_gt_0, AR_eq_0) begin    Ld_AR_BR = 0;    Div_AR_x2_CR = 0;    Mul_BR_x2_CR = 0;    Clr_CR = 0;        case (state)      S0:		if (start) begin Ld_AR_BR = 1; next_state = S1; end      S1:		begin          		  next_state = S0;			 		   if (AR_lt_0) Div_AR_x2_CR = 1;		  		  else if (AR_gt_0) Mul_BR_x2_CR = 1;		  		  else if (AR_eq_0) Clr_CR = 1;				end      default:	next_state = S0;    endcase  endendmodulemodule Datapath_P8_8 (  output reg Overflow, output AR_lt_0, AR_gt_0, AR_eq_0, input [15: 0] data_AR, data_BR,   input Ld_AR_BR, Div_AR_x2_CR, Mul_BR_x2_CR, Clr_CR, clock, reset_b);  reg [15: 0]	AR, BR, CR;  assign 	AR_lt_0 = AR[15];  assign 	AR_gt_0 = (!AR[15]) && (| AR[14:0]);		// Reduction-OR  assign 	AR_eq_0 = (AR == 16'b0);  always @ (posedge clock, negedge reset_b)    if (!reset_b) begin AR <= 8'b0; BR <= 8'b0; CR <= 16'b0; end    else begin      if (Ld_AR_BR) begin AR <= data_AR; BR <= data_BR; end      else if (Div_AR_x2_CR) CR <= {AR[15], AR[15:1]};   // For compiler without arithmetic right shift      else if (Mul_BR_x2_CR) {Overflow, CR} <= (BR << 1);      else if (Clr_CR) CR <= 16'b0;    end  endmodule // Test plan – Verify;// Power-up reset// If AR < 0 divide AR by 2 and transfer to CR // If AR > 0 multiply AR by 2 and transfer to CR// If AR = 0 clear CR// Reset on-the-fly
module t_Prob_P8_8;  wire 		done;  reg [15: 0] 	data_AR, data_BR;  reg  		start, clock, reset_b;  reg [15: 0]	AR_mag, BR_mag, CR_mag;	// To illustrate 2s complement math  // Probes for displaying magnitude of numbers  always @ (M0.M1.AR)  			// Hierarchical dereferencing    if (M0.M1.AR[15]) AR_mag = ~M0.M1.AR+ 16'd1; else AR_mag = M0.M1.AR;  always @ (M0.M1.BR ) 			     if (M0.M1.BR[15]) BR_mag = ~M0.M1.BR+ 16'd1; else BR_mag = M0.M1.BR;  always @ (M0.M1.CR)  			     if (M0.M1.CR[15]) CR_mag = ~M0.M1.CR + 16'd1; else CR_mag = M0.M1.CR;  Prob_8_8 M0 (done, data_AR, data_BR, start, clock, reset_b);  initial #250 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork           reset_b = 0; 		// Power-up reset      #2 reset_b = 1;     #50 reset_b = 0;	// Reset on-the-fly    #52 reset_b = 1;    #90 reset_b = 1;    #92 reset_b = 1;  join  initial fork    #20 start = 1;    #30 start = 0;    #70 start = 1;    #110 start = 1;  join  initial fork    data_AR = 16'd50;		// AR > 0    data_BR = 16'd20;		// Result should be 40    #50 data_AR = 16'd20;    #50 data_BR = 16'd50;	// Result should be 100    #100 data_AR = 16'd50;    #100 data_BR = 16'd50;    #130 data_AR = 16'd0;	// AR = 0, result should clear CR    #160 data_AR = -16'd20;	// AR < 0, Verilog stores 16-bit 2s complement    #160 data_BR = 16'd50;	// Result should have magnitude10    #190 data_AR = 16'd20;	// AR < 0, Verilog stores 16-bit 2s complement    #190 data_BR = 16'hffff;	// Result should have overflow  joinendmodule 	VHDLentity Datapath_Prob_8_8 is   port (Overflow: out Std_Logic; AR_lt_0, AR_gt_0, AR_eq_0: out Std_Logic; data_AR, 	data_BR: in Std_Logic_Vector (15 downto 0); Ld_AR_BR, Div_AR_x2_CR, 	Mul_BR_x2_CR, Clr_CR, clock, reset_b: in Std_Logic);end Datapath_Prob_8_8;architecture Behavioral of Datapath_Prob_8_8 is   AR_lt_0 <= AR(15);   AR_gt_0 <= (notAR(15) ) and Reduction_OR(AR(14 downto 0);   AR_eq_0 = (AR = "0000000000000000");process (clock, reset_b) begin    if reset_b'event and reset_b = '0' then AR <= "00000000"; BR <= "00000000"; 	CR <= "0000000000000000";    elsif clock'event and clock = '1' then       if Ld_AR_BR = '1' then AR <= data_AR; BR <= dta_BR;      elsif Div_AR_x2_CR = '1' then DR <= AR(15) & AR(15 downto 1);        elsif Mul_BR_x2_C then Overflow & CR <= BR(14 downto 0) & '0';      elsif Clr_CR = '1' then CR <= "0000000000000000";      end if;end process;end Behavioral;entity Controller_Prob_8_8 is   port (Ld_AR_BR, Div_AR_x2_CR, Mul_BR_x2_CR, Clr_CR, done: out Std_Logic; start, AR_lt_0, 	AR_gt_0, AR_eq_0, clock, reset_b: in Std_Logic);end Controller_Prob_8_8;architecture Behavioral of Controller_Prob_8_8 is   constant S0 = '0', S1 = '1';   signal state, next_state: Std_Logic_Vector (1 downto 0);process (clock, reset_b) begin   if reset_b'event and reset_b = 0 then state <= S0;   elsif clock'event and clock = 1 then state <= next_state;end process;process (state, start, AR_lt_0, AR_gt_0, AR_eq_0) begin   Ld_AR_BR <= 0;   Div_AR_x2_CR <= 0;   Mul_BR_x2_CR <= 0;   Clr_CR <= 0;    case state   when S0 => if start = 1 then Ld_AR_BR = 1; next_state <= S1;   when S1 => next_state <= S0; if AR_lt_0 then Div_Ar_x2_CR = 1;      elsif AR_gt_0 then Mul_BR_x2_CR <= 1;      elsif AR_eq_0 then Clr_CR <= 0;      end if;   when others => next_state <= S0;end processend Behavioral;entity Prob_8_8 is   port (done: out Std_Logic; data_AR, data_BR: in Std_Logic_Vector (15 downto 0); 	start, clock, reset_b: in Std_Logic);end Prob_8_8;architecture ASMD of Prob_8_8 iscomponent Datapath_Prob_8_8   port (Overflow, AR_lt_0, AR_gt_0, AR_eq_0, data_AR, data_BR,  Ld_AR_BR, Div_AR_x2_CR, 	Mul_BR_x2_CR, Clr_CR, clock, reset_b);component Controller_Prob_8_8   port (Ld_AR_BR, Div_AR_x2_CR, Mul_BR_x2_CR, Clr_CR, done, start, AR_lt_0, AR_gt_0, 	AR_eq_0, clock, reset_b);beginM0: Controller_Prob_8_8   port map (Ld_AR_BR, Div_AR_x2_CR, Mul_BR_x2_CR, Clr_CR, done, start, AR_lt_0, AR_gt_0, 		AR_eq_0, clock, reset_b);M1: Datapath_Prob_8_8   port map (Overflow, AR_lt_0, AR_gt_0, AR_eq_0, data_AR, data_BR,  Ld_AR_BR, 				Div_AR_x2_CR, Mul_BR_x2_CR, Clr_CR, clock, reset_b);end ASMD;function Reduction_OR (data: std_logic_vector) return std_logic is   constant all_zeros: std_logic_vector(data'range) := (others => '0'); begin   if data = all_zeros then     return '0';   else     return '1';   end if; end Reduction_OR; 
8.9Design equations:DS_idle = S_2 + S_idle Start'DS_1 = S_idle Start + S_1 (A2 A3)'DS_2 = A2 A3 S_1HDL description:Verilogmodule Prob_8_9 (output E, F, output [3: 0] A, output A2, A3,  input 	Start, clock, reset_b); wire set_E, clr_E, set_F, clr_A_F, incr_A; Prob_8_9_Controller M0 (set_E, clr_E, set_F, clr_A_F, incr_A, Start, A2, A3, clock, reset_b); Prob_8_9_Datapath M1 (E, F,  A,  A2, A3, set_E, clr_E, set_F, clr_A_F, incr_A, clock, reset_b);endmodule// Structural version of the controller (one-hot)// Note that the flip-flop for S_idle must have a set input and reset_b is wire to the set// Simulation results match Fig. 8-13module Prob_8_9_Controller (  output   	set_E, clr_E, set_F, clr_A_F, incr_A,   input 	Start, A2, A3, clock, reset_b);  wire 		D_S_idle, D_S_1, D_S_2;  wire 		q_S_idle, q_S_1, q_S_2;  wire 		w0, w1, w2, w3;  wire [2:0] 	state = {q_S_2, q_S_1, q_S_idle};  // Next-State Logic  or (D_S_idle, q_S_2, w0);		// input to D-type flip-flop for q_S_idle  and (w0, q_S_idle, Start_b);  not (Start_b, Start);  or (D_S_1, w1, w2, w3);		// input to D-type flip-flop for q_S_1  and (w1, q_S_idle, Start);  and (w2, q_S_1, A2_b);  not (A2_b, A2);  and (w3, q_S_1, A2, A3_b);  not (A3_b, A3);      and (D_S_2, A2, A3, q_S_1);		// input to D-type flip-flop for q_S_2  D_flop_S M0 (q_S_idle, D_S_idle, clock, reset_b);  D_flop M1 (q_S_1, D_S_1, clock, reset_b);  D_flop M2 (q_S_2, D_S_2, clock, reset_b);  // Output Logic  and (set_E, q_S_1, A2);  and (clr_E,  q_S_1, A2_b);  buf (set_F, q_S_2);  and (clr_A_F, q_S_idle, Start);  buf (incr_A, q_S_1);endmodulemodule D_flop (output reg q, input data, clock, reset_b);  always @ (posedge clock, negedge reset_b)    if (!reset_b) q <= 1'b0; else q <= data;endmodulemodule D_flop_S (output reg q, input data, clock, set_b);  always @ (posedge clock, negedge set_b)    if (!set_b) q <= 1'b1; else q <= data;endmodule/*// RTL Version of the controller// Simulation results match Fig. 8-13module Prob_8_9_Controller (  output reg 	set_E, clr_E, set_F, clr_A_F, incr_A,   input 		Start, A2, A3, clock, reset_b);  parameter  	S_idle = 3'b001, S_1 = 3'b010, S_2 = 3'b100;		// One-hot  reg [2: 0]	state, next_state;  always @ (posedge clock, negedge reset_b)      if (!reset_b) state <= S_idle; else state <= next_state;  always @ (state, Start, A2, A3) begin    set_E 	= 1'b0;    clr_E 	= 1'b0;    set_F	= 1'b0;    clr_A_F 	= 1'b0;    incr_A 	= 1'b0;        case (state)      S_idle: 	if (Start) begin next_state = S_1; clr_A_F = 1; end                          else next_state = S_idle;      S_1: 	begin           incr_A = 1;   if (!A2) begin next_state = S_1; clr_E = 1; end          else begin            set_E = 1;            if (A3) next_state = S_2; else next_state = S_1;          end       end	        S_2:	begin next_state = S_idle; set_F = 1; end      default:	next_state = S_idle;     endcase  endendmodule*/module Prob_8_9_Datapath  output reg E, F, output reg [3: 0] A, output A2, A3,  input set_E, clr_E, set_F, clr_A_F, incr_A, clock, reset_b);  assign A2 = A[2];  assign A3 = A[3];  always @ (posedge clock, negedge reset_b) begin    if (!reset_b) begin E <= 0; F <= 0; A <= 0; end     else begin      if (set_E) 	E <= 1;      if (clr_E) 	E <= 0;      if (set_F)	F <= 1;      if (clr_A_F)	begin A <= 0; F <= 0; end      if (incr_A)	A <= A + 1;    end  endendmodule
// Test Plan - Verify: (1) Power-up reset, (2) match ASMD chart in Fig. 8-9 (d),// (3) recover from reset on-the-flymodule t_Prob_8_9;  wire E, F;  wire [3: 0] A;  wire A2, A3;  reg Start, clock, reset_b;    Prob_8_9 M0 (E, F, A, A2, A3, Start, clock, reset_b);    initial #500 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial begin reset_b = 0; #2 reset_b = 1; end  initial fork    #20 Start = 1;    #40 reset_b = 0;    #62 reset_b = 1;  joinendmoduleVHDLSee Answers to Selected Problems in the text.library IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;entity Prob_8_9_Datapath_vhdl is   port (A2, A3: out Std_Logic; set_E, clr_E, set_F, clr_A_F, incr_A, clock, reset_b: in Std_Logic);end Prob_8_9_Datapath_vhdl;architecture Behavioral of Prob_8_9_Datapapth_vhdl is	signal E, F: out Std_Logic; 	signal A: out Std_Logic_Vector (3 downto 0);begin	A2 <= A(2);	A3 <= A(3);process (clock, reset_b) begin    if reset_b = '0' then E <= '0', F <= '0', A <= "0000";   else      if set_E = '1' then E <= '1'; end if;      if clr_E = '1' then E <= '0'; end if;      if set_F = '1' then F <= '1'; end if;      if clr_a_F = '1' then A = "0000"; F <= '0'; end if;      if incr_A = '1' then A <= A + "0001"; end if;   end if;end process;end Behavioral; 
8.10		Verilogmodule Prob_8_10 (input x, y, clock, reset_b);  reg [ 1: 0] 	state, next_state;  parameter	s0 = 2'b00, s1 = 2'b01, s2 = 2'b10, s3 = 2'b11;  always @ (posedge clock, negedge reset_b)    if (reset_b == 0) state <= s0; else state <= next_state;  always @ (state, x, y) begin    next_state = s0;    case (state)      s0:	if (x == 0) next_state = s0; else next_state = s1;      s1:	if (y == 0) next_state = s2; else next_state = s3;      s2:	if (x == 0) next_state = s0; else if (y == 0) next_state = s2; else next_state = s3;      s3:	if (x == 0) next_state = s0; else if (y == 0) next_state = s2; else next_state = s3;    endcase  endendmodulemodule t_Prob_8_10 ();  reg x, y, clock, reset_b;  Prob_8_10 M0 (x, y, clock, reset_b);  initial #150 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork    reset_b = 0;     #12 reset_b = 1;      x = 0; y = 0;		// Remain in s0    #10 y = 1;			// Remain in s0    #20 x = 1;			// Go to s1 to s3    #40 reset_b = 0;	// Go to s0    #42 reset_b = 1;	// Go to s2 to s3     #60 y = 0;			// Go to s2    #80 y = 1;			// Go to s3    #90	x = 0;			// Go to s0    #100 x = 1;			// Go to s1    #110 y = 0;			// Go to s2    #130	x = 0;		// Go to s0  joinendmodule		VHDLlibrary IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;entity Prob_8_10_vhdl is		port (x, y, clock, reset_b: in Std_Logic);end Prob_8_10_vhdl;architecture Behavioral of Prob_8_10_vhdl is		type State_type is (s0, s1, s2, s3);		signal state, next_state: State_type;begin	process (clock, reset_b) begin		if (reset_b = '0') then state <= s0; 		elsif clock'event and clock = '1' then state <= next_state;		end if;	end process;  process (state, x, y) begin    next_state <= s0;    case (state) is      when s0 =>	if (x = '0') then next_state <= s0; else next_state <= s1; end if;      when s1 =>	if (y = '0') then next_state <= s2; else next_state <= s3; end if;      when s2 =>	if (x = '0') then next_state <= s0; 						elsif (y = '0') then next_state <= s2; 						else next_state <= s3; end if;when s3 =>	if (x = '0') then next_state <= s0; elsif (y = '0') then next_state <= s2; 				else next_state <= s3; end if;    end case;  end process;end Behavioral;
