8.12	For the 4-bit synchronous counter, modify the counter in Fig. 6.12 to add a signal, Clear, to clear the counter synchronously, as shown in the circuit diagram below.			(a) VERILOGmodule Counter_4bit_Synch_Clr (output [3: 0]  A, output next_stage, input Count_enable, Clear, CLK);  wire A0, A1, A2, A3;  assign A[3: 0] = {A3, A2, A1, A0};  JK_FF M0 (A0, J0, K0, CLK);  JK_FF M1 (A1, J1, K1, CLK);  JK_FF M2 (A2, J2, K2, CLK);  JK_FF M3 (A3, J3, K3, CLK);  not (Clear_b, Clear);  and (J0, Count_enable, Clear_b);  and (J1, J0, A0);  and (J2, J1, A1);  and (J3, J2, A2);  or (K0, Clear, J0);  or (K1, Clear, J1);  or (K2, Clear, J2);  or (K3, Clear, J3);  and (next_stage, A3, J3);endmodulemodule JK_FF (output reg Q, input J, K, clock);  always @ (posedge clock)    case ({J,K})      2'b00:	Q <= Q;      2'b01:	Q <= 0;      2'b10:	Q <= 1;      2'b11:	Q <= ~Q;    endcaseendmodulemodule t_Counter_4bit_Synch_Clr ();  wire [3: 0]  A;  wire next_stage;   reg Count_enable, Clear, clock;  Counter_4bit_Synch_Clr M0 (A, next_stage, Count_enable, Clear, clock);  initial #300 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork    Clear = 1;    Count_enable = 0;     #12 Clear = 0;    #20 Count_enable = 1;    #180 Clear = 1;    #190 Clear = 0;    #230 Count_enable = 0;  joinendmodule			Simulation results: synchronous clear.			(a) VHDLentity Prob_8_12a_Counter_4bit_Synch_Clr_vhdl is		port (A: out Std_Logic_vector (3 downto 0); next_stage: out Std_Logic; Count_enable, Clear, CLK: in bit);end Prob_8_12_Counter_4bit_Synch_Clr_vhdl;architecture Structural of Prob_8_12a_Counter_4bit_Synch_Clr_vhdl is  	signal A0, A1, A2, A3: Std_Logic;		component JK_FF port (Q: buffer Std_Logic; J, K, clock: in Std_Logic); end component;		component and2_gate port (y: out Std_Logic; xin1, xin2: in Std_Logic); end component;		component or2_gate port (y: out Std_Logic; xin1, xin2: in Std_Logic); end component;		component not_gate port (y: out Std_Logic; xin: in Std_Logic); end component;begin 	A(3 downto 0) <= A3 & A2 & A1 & A0;  	M0: JK_FF port map (A0, J0, K0, CLK); 	M1: JK_FF port map (A1, J1, K1, CLK); 	M2: JK_FF port map (A2, J2, K2, CLK);  			M3: JK_FF port map (A3, J3, K3, CLK);  	M4: not_gate port map (Clear_b, Clear);  	M6: and port map (J0, Count_enable, Clear_b);  	M7: and port map (J1, J0, A0);  	M8: and port map (J2, J1, A1);  	M9: and port map (J3, J2, A2);  	M10: or port map (K0, Clear, J0);  	M11: or port map (K1, Clear, J1);  	M12: or port map (K2, Clear, J2);  	M13: or port map (K3, Clear, J3);  	M14: and port map (next_stage, A3, J3);end Structural;entity JK_FF is		port (Q: buffer bit;   J, K, clock: in bit);end JK_FF;architecture Behavioral of JK_FF isbegin  process  (clock) begin		if clock'event and clock = '1' then    		case (J & K) is      			when "00":	Q <= Q;      			when "01":	Q <= '0';      			when "10":	Q <= '1';      			when "11":	Q <= not Q;    		end case;		end if;end Behavioral;entity and2_gate is  port (y: out Std_Logic; xin1, xin2: in Std_Logic);end and2_gate;architecture Behavioral of and2_gate isbegin	y <= xin1 and xin2;end Behavioral;entity or2_gate is  port (y: out Std_Logic; xin1, xin2: in Std_Logic);end oro2_gate;architecture Behavioral of or2_gate isbegin	y <= xin1 and xin2;end Behavioral;entity not_gate is  port (y: out Std_Logic; xin: in Std_Logic);end not_gate;architecture Behavioral of not_gate isbegin	y <= not xin;end Behavioral;			(b) Verilogmodule Counter_4bit_Asynch_Clr_b (  output [3: 0]  A, output next_stage, input Count_enable, Clk, Clear_b);  wire A0, A1, A2, A3;  assign A[3: 0] = {A3, A2, A1, A0};  wire J0, K0, J1, K1, J2, K2, J3, K3;  assign K0 = J0;  assign K1 = J1;  assign K2 = J2;  assign K3 = J3;  JK_FF M0 (A0, J0, K0, Clk, Clear_b);  JK_FF M1 (A1, J1, K1, Clk, Clear_b);  JK_FF M2 (A2, J2, K2, Clk, Clear_b);  JK_FF M3 (A3, J3, K3, Clk, Clear_b);  and (J0, Count_enable, Clear_b);  and (J1, J0, A0);  and (J2, J1, A1);  and (J3, J2, A2);  and (next_stage, A3, J3);endmoduleentity JK_FF is		port (Q: buffer bit; J, K, clock, Clear_b: in bit);end JK_FF;architecture Behavioral of JK_FF is  process  (clock, Clear_b) begin    	if (Clear_b = '0') then Q <= '0';    	elsif clock'event and clock = '1' then    		case (J & K) is      			when "00" =>		Q <= Q;      			when "01" =>		Q <= '0';      			when "10" =>		Q <= '1';      			when "11" =>		Q <= not Q;			end case;		end if;end Behavioral;module t_Counter_4bit_Asynch_Clr_b ();  wire [3: 0]  A;  wire next_stage;  reg Count_enable, Clk, Clear_b;  Counter_4bit_Asynch_Clr_b M0 (A, next_stage, Count_enable, Clk, Clear_b);  initial #200 $finish;  initial begin Clk = 0; forever #5 Clk = ~Clk; end  initial fork    Count_enable = 0;    Clear_b = 0;    #30 Count_enable = 1;    #50 Clear_b = 1;    #90 Count_enable = 0;    #110 Count_enable= 1;    #150 Clear_b = 0;    #170 Clear_b = 1;   joinendmodule			(b) VHDLentity Prob_8_12b_Counter_4bit_Asynch_Clr_b_vhdl is				port (A: out bit_vector (3 downto 0); next_stage: out bit; Count_enable, Clk, Clear_b: in bit);end Prob_8_12b_Counter_4bit_Asynch_Clr_b_vhdl;architecture Structural of Prob_8_12b_Counter_4bit_Asynch_Clr_b_vhdl is  signal A0, A1, A2, A3: bit;  signal J0, K0, J1, K1, J2, K2, J3, K3: bit;  component JK_FF port  (Q: buffer bit; J, K, clock, Clear_b: in bit); end component;  component and2_gate 	port (y: out bit; xin1, xin2: in bit); end component;begin   A(3: 0) <=  A3 & A2 & A1 & A0;   K0 <= J0; K1 <= J1; K2 <= J2; K3 <= J3;  M0: JK_FF port map (A0, J0, K0, Clk, Clear_b);  M1: JK_FF port map (A1, J1, K1, Clk, Clear_b);  M2: JK_FF port map (A2, J2, K2, Clk, Clear_b);  M3: JK_FF port map (A3, J3, K3, Clk, Clear_b);  M4: and2_gate port map (J0, Count_enable);  M5: and2_gate port map (J1, J0, A0);  M6: and2_gate port map (J2, J1, A1);  M7: and2_gate port map (J3, J2, A2);  M8: and2_gate port map (next_stage, A3, J3);end Structural;entity JK_FF is		port (Q: buffer bit; J, K, clock, Clear_b: in bit);end JK_FF;architecture Behavioral of JK_FF is 		begin		process (clock, Clear_b) begin    		if (Clear_b = '0') then Q <= '0';    		elsif  clock'event and clock = '1' then     			case (J & K) is      				when "00" =>	Q <= Q;      				when "01" =>	Q <= '0';      				when "10" =>	Q <= '1';      				when "11" =>	Q <= not Q;				end case;			end Behavioral;entity and2_gate			port (y: out bit; xin1, xin2: in bit);   end and2_gate;	architecture Behavioral of and2_gate isbegin	y <= xin1 and xin2;end Behavioral;
8.13// Structural description of design example (Fig. 8-10, 8-12)module Design_Example_STR    ( output 	[3:0] 	A,				     output			E, F,    input			Start, clock, reset_b  );  Controller_STR M0 (clr_A_F, set_E, clr_E, set_F, incr_A, Start, A[2], A[3], clock, reset_b );  Datapath_STR M1 (A, E, F, clr_A_F, set_E, clr_E, set_F, incr_A, clock);endmodulemodule Controller_STR ( output clr_A_F, set_E, clr_E, set_F, incr_A,   input Start, A2, A3, clock, reset_b);    wire		G0, G1;  parameter	S_idle = 2'b00, S_1 = 2'b01, S_2 = 2'b11;  wire 		w1, w2, w3;  not (G0_b, G0);  not (G1_b, G1);  buf (incr_A, w2);  buf (set_F, G1);  not (A2_b, A2);  or (D_G0, w1, w2);  and (w1, Start, G0_b);  and (clr_A_F, G0_b, Start);  and (w2, G0, G1_b);  and (set_E, w2, A2);  and (clr_E, w2, A2_b);  and (D_G1, w3, w2);  and (w3, A2, A3);  D_flip_flop_AR M0 (G0, D_G0, clock, reset_b);  D_flip_flop_AR M1 (G1, D_G1, clock, reset_b);endmodule// datapath unitmodule Datapath_STR ( output [3: 0]	A,  output  	E, F,  input		clr_A_F, set_E, clr_E, set_F, incr_A, clock);  JK_flip_flop_2 M0 (E, E_b, set_E, clr_E, clock);  JK_flip_flop_2 M1 (F, F_b, set_F, clr_A_F, clock);  Counter_4 M2 (A, incr_A, clr_A_F, clock);endmodulemodule Counter_4 (output reg [3: 0] A, input incr, clear, clock);  always @ (posedge clock)      if (clear) 	A <= 0; else if (incr) A <= A + 1;  endmodulemodule D_flip_flop_AR (Q, D, CLK, RST);  output 	Q;  input	D, CLK, RST;  reg 	Q;  always @ (posedge CLK, negedge RST)	    if (RST == 0) Q <= 1'b0;    else Q <= D;	 endmodulemodule JK_flip_flop_2 (Q, Q_not, J, K, CLK);  output 	Q, Q_not;  input	J, K, CLK;  reg 	Q;  assign	Q_not = ~Q;  always @ (posedge CLK)	    case ({J, K})      2'b00:	Q <= Q;      2'b01:	Q <= 1'b0;      2'b10:	Q <= 1'b1;      2'b11:	Q <= ~Q;    endcase endmodulemodule t_Design_Example_STR;  reg 		Start, clock, reset_b;  wire [3: 0] 	A;  wire 		E, F;  wire [1:0] state_STR = {M0.M0.G1, M0.M0.G0};  Design_Example_STR M0 (A, E, F, Start, clock, reset_b);  initial #500 $finish;		   initial    begin      reset_b = 0;      Start = 0;      clock = 0;      #5 reset_b = 1; Start = 1;      repeat (32)        begin          #5 clock = ~ clock;	         end    end  initial  $monitor ("A = %b E = %b F = %b time = %0d", A, E, F, $time);endmodule	The simulation results shown below match Fig. 8.13.8.14	The state code 2'b10 is unused. If the machine enters an unused state, with the controller written with default assignment to next_state, the default assignment forces the state to S_idle, so the machine recovers from the condition.8.15 Modify the test bench to insert a reset event and extend the clock.// RTL description of design example (see Fig.8-11)module Design_Example_RTL (A, E, F, Start, clock, reset_b);  // Specify ports of the top-level module of the design  // See block diagram Fig. 8-10  output [3: 0] 	A;  output 			E, F;  input 			Start, clock, reset_b;  // Instantiate controller and datapath units  Controller_RTL M0 (set_E, clr_E, set_F, clr_A_F, incr_A, A[2], A[3], Start, clock, reset_b );  Datapath_RTL M1 (A, E, F, set_E, clr_E, set_F, clr_A_F, incr_A, clock);endmodulemodule Controller_RTL (set_E, clr_E, set_F, clr_A_F, incr_A, A2, A3, Start, clock, reset_b);  output reg	set_E, clr_E, set_F, clr_A_F, incr_A;  input		Start, A2, A3, clock, reset_b;  reg [1:0] 	state, next_state;	   parameter 	S_idle = 2'b00, S_1 = 2'b01, S_2 = 2'b11;	// State codes  always @ (posedge clock or negedge reset_b)		// State transitions (edge-sensitive)    if (reset_b == 0) state <= S_idle;			     else state <= next_state;			   // Code next state logic directly from ASMD chart (Fig. 8-9d)  always @ (state, Start, A2, A3 ) begin		// Next state logic (level-sensitive)    next_state = S_idle;    case (state)        S_idle:	if (Start) next_state = S_1; else next_state = S_idle;        S_1: 		if (A2 & A3) next_state = S_2; else next_state = S_1;        S_2: 		next_state = S_idle;        default:	next_state = S_idle;    endcase  end  // Code output logic directly from ASMD chart (Fig. 8-9d)  always @ (state, Start, A2) begin     set_E = 0;		// default assignments; assign by exception    clr_E = 0;    set_F = 0;    clr_A_F = 0;    incr_A = 0;    case (state)      S_idle: 		if (Start) clr_A_F = 1;      S_1: 		begin incr_A = 1; if (A2) set_E = 1; else clr_E = 1; end      S_2: 		set_F = 1;    endcase  endendmodulemodule  Datapath_RTL  (A, E, F, set_E, clr_E, set_F, clr_A_F, incr_A, clock);  output reg [3: 0] 	A;			// register for counter  output reg 		E, F;			// flags  input 			set_E, clr_E, set_F, clr_A_F, incr_A, clock;  // Code register transfer operations directly from ASMD chart (Fig. 8-9d)  always @ (posedge clock) begin    if (set_E) 				E <= 1;    if (clr_E) 				E <= 0;    if (set_F) 				F <= 1;    if (clr_A_F)				begin A <= 0; F <= 0; end    if (incr_A) 				A <= A + 1;  endendmodulemodule t_Design_Example_RTL;  reg 			Start, clock, reset_b;  wire [3: 0] 	A;  wire 			E, F;  // Instantiate design example  Design_Example_RTL M0 (A, E, F, Start, clock, reset_b);  // Describe stimulus waveforms  initial #500 $finish;		// Stopwatch  initial fork      #25 reset_b = 0;		// Test for recovery from reset on-the-fly.      #27 reset_b = 1;  join  initial    begin      reset_b = 0;      Start = 0;      clock = 0;      #5 reset_b = 1; Start = 1;      //repeat (32)      repeat (38)				// Modify for test of reset_b on-the-fly        begin          #5 clock = ~ clock;		// Clock generator        end    end  initial    $monitor ("A = %b E = %b F = %b time = %0d", A, E, F, $time);endmodule8.16	RTL notation:  s0: (initial state) If start = 0 go back to state s0, If (start = 1) then BR ? multiplicand, AR ? multiplier, PR ? 0, go to s1.s1: (check AR for Zero) Zero = 1 if AR = 0, if (Zero = 1) then go back to s0 (done) If (Zero = 0) then go to s1,  PR ? PR + BR, AR ? AR – 1.The internal architecture of the datapath consists of a double-width register to hold the product (PR), a register to hold the multiplier (AR), a register to hold the multiplicand (BR), a double-width parallel adder, and single-width parallel adder. The single-width adder is used to implement the operation of decrementing the multiplier unit. Adding a word consisting entirely of 1s to the multiplier accomplishes the 2's complement subtraction of 1 from the  multiplier. Figure 8.16 (a) below shows the ASMD chart, block diagram, and controller of the circuit. Figure 8.16 (b) shows the internal architecture of the datapath. Figure 8.16 (c) shows the results of simulating the circuit.(a) ASMD chart, block diagram, and controller(b) Datapath(c) Simulation results
