module Datapath_Unit # (parameter m_size = 9,  BC_size = 4) (  output reg [m_size -1: 0] A, Q,   output Q0, Zero,   input [m_size -1: 0] Multiplicand, Multiplier,   input Load_regs, Decr_P,  Add_regs, Shift_regs, clock, reset_b);  reg C;  reg [BC_size -1: 0] P;  reg [m_size -1: 0] B;    assign Q0 = Q[0];  assign Zero = (P == 0);  always @ (posedge clock, negedge reset_b)    if (reset_b == 0) begin    B <= 0;C <= 0;    A <= 0;    Q <= 0;    P <= m_size;  end  else begin    if (Load_regs) begin      A <= 0;      C <= 0;      Q <= Multiplier;      B <= Multiplicand;      P <= m_size;    end    if (Decr_P) P <= P -1;    if (Add_regs) {C, A} <= A + B;    if (Shift_regs) {C, A, Q} <= {C, A, Q} >> 1;  endendmodule module Control_Unit (  output Ready, Decr_P, output reg Load_regs, Add_regs, Shift_regs, input Start, Q0, Zero, clock, reset_b);  reg [ 1: 0] 	state, next_state;  parameter	S_idle = 2'b00, S_loaded = 2'b01, S_sum = 2'b10, S_shifted = 2'b11;  assign Ready = (state == S_idle);  assign Decr_P = (state == S_loaded);  always @ (posedge clock, negedge reset_b)    if (reset_b == 0) state <= S_idle; else state <= next_state;  always @ (state, Start, Q0, Zero) begin    next_state = S_idle;     Load_regs = 0;    Add_regs = 0;    Shift_regs = 0;    case (state)      S_idle:	if (Start == 0) next_state = S_idle; else begin next_state = S_loaded; Load_regs = 1; end      S_loaded:	if (Q0) begin next_state = S_sum; Add_regs = 1; end		else begin next_state = S_shifted; Shift_regs = 1; end      S_sum:	begin next_state = S_shifted; Shift_regs = 1; end       S_shifted:	if (Zero) next_state = S_idle; else next_state = S_loaded;    endcase  endendmodule
module t_Prob_8_22 ();  parameter					m_size = 9;			// Width of datapath  wire	[2 * m_size - 1: 0] 	Product;  wire							Ready;  reg 	[m_size - 1: 0] 		Multiplicand, Multiplier;   reg 							Start, clock, reset_b;  integer						Exp_Value;  reg							Error;   Prob_8_22 M0 (Product, Ready, Multiplicand, Multiplier, Start, clock, reset_b);  initial #140000 $finish;  initial begin clock = 0; #5 forever #5 clock = ~clock; end  initial fork    reset_b = 1;    #2 reset_b = 0;    #3 reset_b = 1;  join  initial begin #5 Start = 1; end    always @ (posedge Ready) begin    Exp_Value = Multiplier * Multiplicand;    //Exp_Value = Multiplier * Multiplicand +1;	// Inject error to confirm detection  end  always @ (negedge Ready) begin    Error = (Exp_Value ^ Product) ;  end  initial begin    #5 Multiplicand = 0;    Multiplier = 0;    repeat (64) #10 begin Multiplier = Multiplier + 1;      repeat (64) @ (posedge M0.Ready) #5 Multiplicand = Multiplicand + 1;    end  endendmodule
