 next_state <= S_sum; Add_regs <= '1'; 									else next_state <= S_shifted; Shift_regs <= '1'; end if;      				when S_sum =>	next_state <= S_shifted; Shift_regs <= '1';       			when S_shifted =>	if (Zero = '1') then next_state <= S_idle; 														else next_state <= S_loaded; end if;    		end case;  	end process;end Behavioral;8.23	As shown in Fig. P8.23 the machine asserts Load_regs in state S_load. This will cause the machine to operate incorrectly. Once Load_regs is removed from S_load the machine operates correctly. The state S_load is a wasted state. Its removal leads to the same machine as dhown in Fig. P8.15b.module Prob_8_23 # (parameter m_size = 9)(   output [2*m_size -1: 0] Product,  output Ready,   input [m_size -1: 0] Multiplicand, Multiplier,  input Start, clock, reset_b);  wire [m_size -1: 0] A, Q;  assign Product = {A, Q};   wire Q0, Zero, Load_regs, Decr_P, Add_regs, Shift_regs;  Datapath_Unit M0 (A, Q, Q0, Zero, Multiplicand, Multiplier, Load_regs, Decr_P, Add_regs, Shift_regs, clock, reset_b);Control_Unit M1 (Ready, Decr_P, Shift_regs, Add_regs, Load_regs, Start, Q0, Zero, clock, reset_b);endmodulemodule Datapath_Unit # (parameter m_size = 9,  BC_size = 4) (  output reg [m_size -1: 0] A, Q,   output Q0, Zero,   input [m_size -1: 0] Multiplicand, Multiplier,   input Load_regs, Decr_P,  Add_regs, Shift_regs, clock, reset_b);  reg C;  reg [BC_size -1: 0] P;  reg [m_size -1: 0] B;    assign Q0 = Q[0];  assign Zero = (P == 0);  always @ (posedge clock, negedge reset_b)    if (reset_b == 0) begin    A <= 0;    C <= 0;    Q <= 0;    B <= 0;    P <= m_size;  end  else begin    if (Load_regs) begin      A <= 0;      C <= 0;      Q <= Multiplier;      B <= Multiplicand;      P <= m_size;    end    if (Decr_P) P <= P -1;    if (Add_regs) {C, A} <= A + B;    if (Shift_regs) {C, A, Q} <= {C, A, Q} >> 1;  endendmodule module Control_Unit (  output Ready, Decr_P, Shift_regs, output reg Add_regs, Load_regs, input Start, Q0, Zero, clock, reset_b);  reg [ 1: 0] 	state, next_state;  parameter	S_idle = 2'b00, S_load = 2'b01, S_decr = 2'b10, S_shift = 2'b11;  assign Ready = (state == S_idle);  assign Shift_regs = (state == S_shift);  assign Decr_P = (state == S_decr);  always @ (posedge clock, negedge reset_b)    if (reset_b == 0) state <= S_idle; else state <= next_state;  always @ (state, Start, Q0, Zero) begin    next_state = S_idle;    Load_regs = 0;    Add_regs = 0;    case (state)      S_idle:	if (Start == 0) next_state = S_idle; else begin next_state = S_load; Load_regs = 1; end      S_load:	begin next_state = S_decr; end      S_decr:	begin next_state = S_shift; if (Q0) Add_regs = 1; end      S_shift:	if (Zero) next_state = S_idle; else next_state = S_load;    endcase  endendmodule module t_Prob_8_23 ();  parameter			m_size = 9;			// Width of datapath  wire	[2 * m_size - 1: 0] 	Product;  wire				Ready;  reg 	[m_size - 1: 0] 		Multiplicand, Multiplier;   reg 				Start, clock, reset_b;  integer				Exp_Value;  reg				Error;   Prob_8_23 M0 (Product, Ready, Multiplicand, Multiplier, Start, clock, reset_b);  initial #140000 $finish;  initial begin clock = 0; #5 forever #5 clock = ~clock; end  initial fork    reset_b = 1;    #2 reset_b = 0;    #3 reset_b = 1;  join  initial begin #5 Start = 1; end  always @ (posedge Ready) begin    Exp_Value = Multiplier * Multiplicand;    //Exp_Value = Multiplier * Multiplicand +1;	// Inject error to confirm detection  end  always @ (negedge Ready) begin    Error = (Exp_Value ^ Product) ;  end  initial begin    #5 Multiplicand = 0;    Multiplier = 0;    repeat (64) #10 begin Multiplier = Multiplier + 1;      repeat (64) @ (posedge M0.Ready) #5 Multiplicand = Multiplicand + 1;    end  endendmoduleVHDL			library IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;entity Prob_8_23_vhdl is	generic (m_size: integer := 9);		port (Product: buffer Unsigned (2*m_size -1 downto 0); 			Ready: buffer Std_Logic; 			Multiplicand, Multiplier: in Unsigned (m_size -1 downto 0);			Start, clock, reset_b: in Std_Logic);		end entity Prob_8_23_vhdl;architecture Partitioned of Prob_8_23_vhdl is  	signal A, Q: Unsigned (m_size -1 downto 0);	signal Q0, Zero, Load_regs, Decr_P, Add_regs, Shift_regs: Std_Logic;	component Datapath_Unit 		generic (m_size, BC_size: integer);		port (A, Q: out Unsigned (m_size-1 downto 0); 			Q0, Zero: out Std_Logic;			Multiplicand, Multiplier: in Unsigned (m_size-1 downto 0); 			Load_regs, Decr_P, Add_regs, Shift_regs, clock, reset_b: in Std_Logic); 			end component;		component Control_Unit		generic (m_size, BC_size: integer);			port (Ready, Decr_P, Shift_regs, Add_regs, Load_regs: out Std_Logic;		Start, Q0, Zero, clock, reset_b: in Std_Logic); 	end component;begin	Product <= A & Q; M0: Datapath_Unit generic map (m_size => 9, BC_size => 4) port map (A, Q, Q0, Zero, Multiplicand, Multiplier, Load_regs, Decr_P, Add_regs, Shift_regs, clock, reset_b);M1: Control_Unit generic map (m_size => 9, BC_size => 4) port map (Ready, Decr_P, Shift_regs, Add_regs, Load_regs, Start, Q0, Zero, clock, reset_b);end Partitioned;Library IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;entity Datapath_Unit is		generic (m_size, BC_size: integer);		port (A: buffer Unsigned (m_size -1 downto 0); Q: buffer Unsigned (m_size -1 downto 0);				Q0, Zero: out Std_Logic; 				Multiplicand, Multiplier: in Unsigned (m_size -1 downto 0); 				Load_regs, Decr_P, Add_regs, Shift_regs, clock, reset_b: in Std_Logic);end entity Datapath_Unit;	architecture Behavioral of Datapath_Unit is  signal P: integer;  signal B: Unsigned (m_size -1 downto 0);  signal S: Unsigned (m_size downto 0);  signal C: Std_Logic;begin  Q0 <= Q(0);  Zero <= '1' when P = '0' else '0';  S <= ('0' & A) +('0' & B);  process (clock, reset_b) begin  	if (reset_b = '0') then    		C <= '0';			for k in 0 to m_size-1 loop			B(k) <= '0';			A(k) <= '0';			Q(k) <= '0';		end loop;    elsif clock'event and clock = '1' then		if Load_regs = '1' then			for k in 0 to m_size-1 loop				A(k) <= '0';			end loop;			C <= '0';			Q <= Multiplier;			B <= Multiplicand;			P <= m_size;		end if;		if (Decr_P = '1') then P <= P -1; end if;		if (Add_regs = '1') then 			C <= S(m_size); 			A <= S(m_size-1 downto 0);		end if;		if (Shift_regs = '1') then 			Q <= A(0) & Q(m_size-1 downto 1);			A <= C & Q(m_size-1 downto 1);			C <= '0';		end if;	end if;	   end process;end Behavioral; library IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;Library Synopsys;use Synopsys.attributes.all;entity Control_Unit is	generic (m_size, BC_size: integer);	port (Ready, Decr_P, Shift_regs, Add_regs, Load_regs: out bit; Start, Q0, Zero, clock, reset_b: in bit);end entity Control_Unit;architecture Behavioral of Control_Unit is	type State_type is (S_idle, S_load, S_decr, S_shift);	attribute enum_encoding of State_type : type is "00 01 10 11";	signal state, next_state: State_type;	Ready <= '1' when (state = S_idle) else '0';	Shift_regs <= '1' when (state = S_shift) else '0';	Decr_P <= '1' when (state = S_decr) else '0';	process  (clock, reset_b) begin		if (reset_b = '0') then state <= S_idle; 		elsif clock'event and clock = '1' then state <= next_state;		end if;	end process;	process (state, Start, Q0, Zero) begin		next_state <= S_idle;    		Load_regs <= '0';		Add_regs <= '0';		case (state) is		when S_idle =>	if (Start = '0') then next_state <= S_idle; 							else next_state <= S_load; Load_regs <= '1'; end if;		when S_load =>	next_state <= S_decr; 		when S_decr =>	next_state <= S_shift; if (Q0 = '1') then  Add_regs <= '1'; end if;		when S_shift =>	if (Zero = '1') then next_state <= S_idle; else next_state <= S_load; end if;    		end case;  	end process;end  behavioral;
8.24module Prob_8_24 # (parameter dp_width = 5) (  output 	[2*dp_width - 1: 0] 	Product,  output							Ready,  input 	[dp_width - 1: 0] 		Multiplicand, Multiplier,  input 							Start, clock, reset_b);  wire Load_regs, Decr_P, Add_regs, Shift_regs, Zero, Q0;  Controller M0 (    Ready, Load_regs, Decr_P, Add_regs, Shift_regs, Start, Zero, Q0,     clock, reset_b);Datapath M1(Product, Q0, Zero,Multiplicand, Multiplier,  Start, Load_regs, Decr_P, Add_regs, Shift_regs, clock, reset_b);	endmodulemodule Controller (  output Ready,  output reg Load_regs, Decr_P, Add_regs, Shift_regs,     input Start, Zero, Q0, clock, reset_b);  parameter		S_idle =	3'b001, 		// one-hot code        				S_add = 	3'b010, 		       				S_shift = 	3'b100;  reg	[2: 0]		state, next_state;		// sized for one-hot  assign			Ready = (state == S_idle);	    always @ (posedge clock, negedge reset_b)    if (~reset_b) state <= S_idle; else state <= next_state;  always @ (state, Start, Q0, Zero) begin    next_state = S_idle;    Load_regs = 0;    Decr_P = 0;    Add_regs = 0;    Shift_regs = 0;    case (state)      S_idle:	if (Start) begin next_state = S_add; Load_regs = 1; end      S_add:	begin next_state = S_shift; Decr_P = 1; if (Q0) Add_regs = 1; end      S_shift:	begin 		  Shift_regs = 1; 		  if (Zero) next_state = S_idle; 		  else next_state = S_add;        end      default:	next_state = S_idle;    endcase  endendmodule
module Datapath #(parameter dp_width = 5, BC_size = 3) (  output [2*dp_width - 1: 0] Product, output Q0, output Zero,  input [dp_width - 1: 0] Multiplicand, Multiplier,  input Start, Load_regs, Decr_P, Add_regs, Shift_regs, clock, reset_b);// Default configuration: 5-bit datapath  reg	[dp_width - 1: 0]		A, B, Q;				// Sized for datapath  reg 				C;  reg	[BC_size - 1: 0]		P;				// Bit counter    assign Q0 = Q[0];	  assign	Zero = (P == 0);			// Counter is zero  assign Product = {C, A, Q};  always @ (posedge clock, negedge reset_b)     if (reset_b == 0) begin			// Added to this solution, but      P <= dp_width;					// not really necessary since Load_regs      B <= 0;							// initializes the datapath      C <= 0;      A <= 0;      Q <= 0;    end     else begin    if (Load_regs) begin      P <= dp_width;      A <= 0;      C <= 0;      B <= Multiplicand;      Q <= Multiplier;    end    if (Add_regs) {C, A} <= A + B;    if (Shift_regs) {C, A, Q} <= {C, A, Q} >> 1;    if (Decr_P) P <= P -1;  endendmodule module t_Prob_8_24;  parameter					dp_width = 5;			// Width of datapath  wire	[2 * dp_width - 1: 0] 	Product;  wire							Ready;  reg 	[dp_width - 1: 0] 		Multiplicand, Multiplier;   reg 							Start, clock, reset_b;  integer						Exp_Value;  reg							Error;  Prob_8_24 M0(Product, Ready, Multiplicand, Multiplier, Start, clock, reset_b);  initial #115000 $finish;  initial begin clock = 0; #5 forever #5 clock = ~clock; end  initial fork    reset_b = 1;    #2 reset_b = 0;    #3 reset_b = 1;  join  always @ (negedge Start) begin    Exp_Value = Multiplier * Multiplicand;    //Exp_Value = Multiplier * Multiplicand +1;	// Inject error to confirm detection  end  always @ (posedge Ready) begin    # 1 Error <= (Exp_Value ^ Product) ;  end  initial begin    #5 Multiplicand = 0;    Multiplier = 0;        repeat (32) #10 begin        Start = 1;        #10 Start = 0;        repeat (32) begin          Start = 1;          #10 Start = 0;                    #100 Multiplicand = Multiplicand + 1;        end      Multiplier = Multiplier + 1;    end  endendmoduleVHDLlibrary IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_Arith.all;entity Prob_8_24_vhdl is				generic (dp_width: integer := 5);		port (Product: out Std_Logic_vector(2*dp_width downto 0);				Ready: out Std_Logic;			Multiplicand, Multiplier: in Std_Logic_vector(dp_width -1 downto 0);			Start, clock, reset_b: in Std_Logic);end Prob_8_24_vhdl;architecture Partitioned of Prob_8_24_vhdl is  	signal Load_regs, Decr_P, Add_regs, Shift_regs, Zero, Q0: Std_Logic;		component Controller  		generic (dp_width, BC_width: integer);		port (Ready: out Std_Logic;  				Load_regs, Decr_P, Add_regs, Shift_regs: out Std_Logic;   				Start, Zero, Q0, clock, reset_b: in Std_Logic); 	end component;		component Datapath 			generic (dp_width, BC_width: integer);		port (Product: out Std_Logic_Vector (2*dp_width downto 0); 				Q0, Zero: out Std_Logic;				Multiplicand, Multiplier: in Std_Logic_vector (dp_width-1 downto 0);				Start, Load_regs, Decr_P, Add_regs, Shift_regs, clock, reset_b: in Std_Logic);		end component;beginM0: Controller 	generic map (dp_width => 5, BC_width => 3) 	port map (Ready, Load_regs, Decr_P, Add_regs, Shift_regs, Start, Zero, Q0, clock, reset_b); M1: Datapath 	generic map (dp_width => 5, BC_width => 3) 	port map (Product, Q0, Zero, Multiplicand, Multiplier, Start, Load_regs, Decr_P, Add_regs, Shift_regs, clock, reset_b);end Partitioned;library IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_Arith.all;library Synopsys;use Synopsys.attributes.all;	-- used for one-hot encoding of states entity Controller is	generic (dp_width, BC_width: integer);	port (Ready, Load_regs, Decr_P, Add_regs, Shift_regs: out Std_Logic;  			Start, Zero, Q0, clock, reset_b: in Std_Logic);end Controller;architecture Behavioral of Controller is  type State_type is (S_idle, S_add, s_shift);  attribute enum_encoding of State_type: type is "001 010 100";	-- one-hot  signal state, next_state: State_type;begin  	Ready <= '1' when (state = S_idle) else '0';	    	process  (clock, reset_b) begin    		if (reset_b = '0') then state <= S_idle; else state <= next_state; end if;		end process;  	process  (state, Start, Q0, Zero) begin    		next_state <= S_idle;    		Load_regs <= '0';    		Decr_P <= '0';    		Add_regs <= '0';    		Shift_regs <= '0';    		case (state) is      		when S_idle =>	if (Start = '1') then next_state <= S_add; Load_regs <= '1'; end if;      		when S_add =>	next_state <= S_shift; Decr_P <= '1'; if (Q0 = '1') then Add_regs <= '1'; end if;      		when S_shift =>	Shift_regs <= '1'; if (zero = '1') then next_state <= S_idle; 											else next_state <= S_add; end if;			when others  =>	next_state <= S_idle;			end case;		end process;end Behavioral;library IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_Arith.all;use IEEE.Std_Logic_unsigned.all;entity Datapath is		generic (dp_width, BC_width: integer);  	port (	Product: buffer Std_Logic_vector (2*dp_width downto 0);				Q0: out Std_Logic;				Zero: out Std_Logic;    			Multiplicand, Multiplier: in Std_Logic_vector (dp_width - 1 downto 0);				Start, Load_regs, Decr_P, Add_regs, Shift_regs, clock, reset_b: in Std_Logic); beginend Datapath;architecture Behavioral of Datapath is  	signal 	C: Std_Logic;	  	signal	A, B, Q: Std_Logic_vector (dp_width - 1 downto 0);		-- Sized for datapath	signal 	P: integer; signal S: Std_Logic_vector (dp_width downto 0);begin	   	Q0 <= Q(0);		Product <= C & A & Q;			process(P) begin			-- Check for empty P (Bit counter)		if P = 0 then Zero <= '1'; else Zero <= '0'; end if;	end process;	  	process   (clock, reset_b) begin    	if (reset_b = '0') then	       	C <= '0';      	 		for k in 0 to dp_width-1 loop							      		B(k) <= '0';							      		A(k) <= '0';      		Q(k) <= '0';		end loop;  	elsif clock'event and clock = '1' then 		if (Load_regs = '1') then			P <= dp_width;			C <= '0';							B <= Multiplicand;			Q <= Multiplier;			for k in 0 to dp_width-1 loop										A(k) <= '0';			end loop;		end if; 			if (Add_regs = '1') then 			S <= ('0' & A) + ('0' & B);   			C <= S(dp_width); 			A <= S(dp_width-1 downto 0); 		end if; 		if (Shift_regs = '1') then			Q <= A(0) & Q(dp_width-1 downto 1);			A <= C & A(dp_width -1 downto 1);			C <= '0';		end if;		if (Decr_P = '1') then P <= P -1; end if;	end if;  	end process;end Behavioral;
8.25	(a)	(b)The binary multiplier of Fig. 8.15 is modified to detect whether the multiplier or multiplicand are initially zero, and to detect whether the shifted multiplier becomes zero before the entire multiplier has been applied to the multiplicand. Status signal Empty_data indicates that either Multiplier or Multiplicand are 0, in which case there is no need to load the data or to multiply. Clr_Q_C assures that Q and C are  empty so that CAQ does not mistakenly use residual data and present a bogus value of Product. Zero indicates that the count of bits of Multiplier that remain to be processed is 0. Empty_m indicates that the unprocessed bits of Multiplier are all 0s(early termination).  P indicatees how many bits of the multiplier word in Q remain to be process.  A Mealy-type signal Valid asserts for one cycle during a transition from S_shift to S_idle, and indicates that the value of Product is valid. Product will remain valid until the machine asserts Load_regs. Signal Clr_Q_C is necessary because Empty_data does not imply that Q is empty. In the situation where Empty_data asserts because Multiplicand alone is empty, Clr_Q_C  assures that QAC will be empty, presenting a correct value of Product. 
Verilogmodule Prob_8_25 #(parameter dp_width = 5) (  output 	[2*dp_width - 1: 0] 	Product,  output							Ready,  input 	[dp_width - 1: 0] 		Multiplicand, Multiplier,  input 							Start, clock, reset_b);  wire Load_regs, Clr_Q, Decr_P, Add_regs, Shift_regs, Empty_m, Empty_data, Zero, Q0;  Controller M0 (    Ready, Load_regs, Clr_Q, Decr_P, Add_regs, Shift_regs, Start, Empty_m, Emptpy_data, Zero, Q0,     clock, reset_b);Datapath M1(Product, Q0, Empty_m, Empty_data, Zero, Multiplicand, Multiplier,  Start, Load_regs, Clr_Q, Decr_P, Add_regs, Shift_regs, clock, reset_b);	endmodulemodule Controller (  output Ready,  output reg Load_regs, Clr_Q, Decr_P, Add_regs, Shift_regs,     input Start, Empty, Zero, Q0, clock, reset_b);  parameter 		BC_size = 	3;		// Size of bit counter  parameter		S_idle =	3'b001, 	// one-hot code        				S_add = 	3'b010, 		       				S_shift = 	3'b100;  reg	[2: 0]		state, next_state;		// sized for one-hot  assign			Ready = (state == S_idle);	    always @ (posedge clock, negedge reset_b)    if (reset_b = 1'b0) state <= S_idle; else state <= next_state;  always @ (state, Start, Q0, Empty_m, Empty_data, Zero) begin    next_state = S_idle;    Load_regs = 0;    Clr_Q = 0;    Decr_P = 0;    Add_regs = 0;    Shift_regs = 0;    case (state)      S_idle:		if (Start = 1'b0) begin next_state = S_idle				else if (Empty_data = 1) begin Clr_Q = 1; next_state = S_idle end				else begin Load_regs = 1; next_state = S_add; end      S_add:	if (Empty_m) next_state = S_idle;				else begin next_state = S_shift; Decr_P = 1; 							if (Q0) Add_regs = 1; 				end	S_shift:	begin 		  		  Shift_regs = 1; 		  		  if (Zero) next_state = S_idle; 		  		  else next_state = S_add; end    end      default:	next_state = S_idle;    endcase  endendmodulemodule Datapath #(parameter dp_width = 5, BC_size = 3) (  output reg [2*dp_width : 0] Product, output Q0, output Empty_m, Empty_data, output Zero,  input [dp_width - 1: 0] Multiplicand, Multiplier,  input Start, Load_regs, Clr_Q, Decr_P, Add_regs, Shift_regs, clock, reset_b);// Default configuration: 5-bit datapath  parameter		S_idle =	3'b001, 		// one-hot code        				S_add = 	3'b010, 		       				S_shift = 	3'b100;  reg	[dp_width - 1: 0]		A, B, Q;		// Sized for datapath  reg 							C;  reg	[BC_size - 1: 0]		P;				// Bit counter  wire 	[2*dp_width: 0]		Pre_Product = {C, A, Q};    assign 		Q0 = Q[0];	  assign		Zero = (P == 0);				// Bit counter is zero  always @ (posedge clock, negedge reset_b)     if (reset_b == 0) begin			// Added to this solution, but      P <= dp_width;					// not really necessary since Load_regs      B <= 0;							// initializes the datapath      C <= 0;      A <= 0;      Q <= 0;    end     else begin    if (Clr_Q) Q <= 0;    if (Load_regs) begin      P <= dp_width;      A <= 0;      C <= 0;      B <= Multiplicand;      Q <= Multiplier;    end    if (Add_regs) {C, A} <= A + B;    if (Shift_regs) {C, A, Q} <= {C, A, Q} >> 1;    if (Decr_P) P <= P -1;  end  // Status signals  wire Empty_m = (Q[P: 0] == 0);  wire Empty_data = (Multiplicand == 0) || (Multiplier == 0);  assign Product = Pre_Product [2*dp_width: P];{C, A[dp_width-1: 0], Q[dp_width-1: P]};always @ (P, Internal_Product) begin	// Note: hardwired for dp_width  5    Product = 0;    case (P)		// Examine multiplier bit counter/pointer      0: 	Product = Internal_Product [2*dp_width : 0];      1:	Product = Internal_Product [2*dp_width : 1];      2:	Product = Internal_Product [2*dp_width : 2];      3:	Product = Internal_Product [2*dp_width : 3];      4:	Product = Internal_Product [2*dp_width : 4];      5:	Product = 0	default: Product = 0;    endcase  end  always @ (P, Q) begin				// Note: hardwired for dp_width  5      Empty_m = 0;    case (P)      0:	Empty_m = 1;      1: 	if (Q[1] == 0) 		Empty_multiplier = 1;      2:	if (Q[2: 1] == 0) 	Empty_multiplier = 1;      3:   if (Q[3: 1] == 0) 	Empty_multiplier = 1;      4:	if (Q[4: 1] == 0) 	Empty_multiplier = 1;      5:   if (Q[5: 1] == 0) 	Empty_multiplier = 1;      default: Empty_multiplier = 0;    endcase  endendmodule module t_Prob_8_25;  parameter			dp_width = 5;			// Width of datapath  wire	[2 * dp_width - 1: 0] 	Product;  wire							Ready;  reg 	[dp_width - 1: 0] 		Multiplicand, Multiplier;   reg 							Start, clock, reset_b;  integer						Exp_Value;  reg							Error;  Prob_8_25 M0(Product, Ready, Multiplicand, Multiplier, Start, clock, reset_b);  initial #115000 $finish;  initial begin clock = 0; #5 forever #5 clock = ~clock; end  initial fork    reset_b = 1;    #2 reset_b = 0;    #3 reset_b = 1;  join  always @ (negedge Start) begin    Exp_Value = Multiplier * Multiplicand;    //Exp_Value = Multiplier * Multiplicand +1;	// Inject error to confirm detection  end  always @ (posedge Ready) begin    # 1 Error <= (Exp_Value ^ Product) ;  end  initial begin    #5 Multiplicand = 0;    Multiplier = 0;        repeat (32) #10 begin        Start = 1;        #10 Start = 0;        repeat (32) begin          Start = 1;          #10 Start = 0;                    #100 Multiplicand = Multiplicand + 1;        end      Multiplier = Multiplier + 1;    end  endendmodule(c) Test plan: Exhaustively test all combinations of multiplier and multiplicand, using automatic error checking. Verify that early termination is implemented. Sample of simulation results is shown below. 		VHDLThe width of the datapath in the original counter determines the number of times the multiplier word (Q) is shifted to the right, with bits of the Product being shifted into Q from the left. The modified machine dynamically detects whether the unprocessed portion	of the multiplier word is devoid of 1s. If so, early termination is possible. If early termination occurs no additional copies of the	multiplicand will be added to the partial product. However, if the process terminates before Q has been shifted by the width of the datapath, the LSB of the product will not occupy the LSB position of Q, leading to a misformed value of C & A & Q. Caution is advised because Q contains bits of the multiplier and bits of the product, with the distribution changing with each shift.The solution is to extract the product from the proper segment of CAQ, depending on the number of shifts that have occurred in forming the partial product. P always indicates how many bits of A are associated with the multiplier.The design methodology created separate files for the datapath and controller. Each was verified seprately. Then the integration of the datapath with the controller was verified.library IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;entity Prob_8_25_vhdl  isgeneric dp_width;	port (Product out Std_Logic (2*dp_width downto 0),			Ready, Valid: out Std_Logic; Multiplicand, Multiplier in (dp_width - 1: 0);	 		Start, clock, reset_b: in Std_Logic);							end Prob_8_25_vhdl;architecture Behavioral of Prob_8_25_vhdl is  	signal Load_regs, Clr_Q_C, Decr_P, Add_regs, Shift_regs, 				Empty_data, Empty_m, Zero, Q0: Std_Logic;		component Controller generic dp_width;			port (Ready, Valid, Load_regs, Clr_Q_C, Decr_P, Add_regs, Shift_regs: out Std_Logic;     		Start, Zero, Empty_data, Empty_m, Q0, clock, reset_b: in Std_logic);		component Datapath generic dp_width;			port (Product: out Std_Logic_vector (2*dp_width downto 0); Q0, Empty_data, Empty_m, 			Zero: out Std_Logic;	Empty_data, Empty_m: out Std_Logic; Multiplicand, 			Multiplier: in Std_Logic_vector (dp_width – 1 downto 0); Start, Load_regs, Clr_Q_C, 							Decr_P, Add_regs, Shift_regs, clock, reset_b: in Std_Logic);begin		M0: Controller 			generic map (dp_width = 5, BC_size = 3)			port map (Ready, Valid, Load_regs, Clr_Q_C, Decr_P, Add_regs, Shift_regs, Start, 			Empty_data, Empty_m, Zero, Q0, clock, reset_b);		M1: Datapath 			generic map (dp_width = 5, BC_size = 3)			port map (Product, Q0, Zero, Empty_data, Empty_m, Multiplicand, Multiplier,  				Start, Load_regs, Clr_Q_C, Decr_P, Add_regs, Shift_regs, clock, reset_b);	end Behavioral;-- Control Unitlibrary IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;Library Synopsys;use Synopsys.attributes.all;-- File: Prob_8_25b_Controller_vhdl.vhd entity Prob_8_25b_Controller_vhdl is	generic (dp_width: integer := 5; BC_size: integer := 3); 	port (Ready, Valid, Load_regs, Clr_Q_C, Decr_P, Add_regs, Shift_regs: out Std_Logic;     		   Start, Empty_data, Empty_m, Zero, Q0, clock, reset_b: in Std_Logic);end Prob_8_25b_Controller_vhdl;architecture Behavioral of Prob_8_25b_Controller_vhdl is		-- one-hot	type State_type is (S_idle, S_add, S_shift);	attribute enum_encoding of State_type: type is "001 010 100";	signal state, next_state: State_type;	begin-- State transitions		process  (clock, reset_b) begin    	if (reset_b = '0') then state <= S_idle; 		elsif clock'event and clock = '1' then state <= next_state; end if;	end process;-- Mealy Output	Valid <= '1' when state = S_shift and Zero = '1' else '0';-- Next state logic		process (state, Start, Empty_data, Empty_m, Q0, Zero) begin   		next_state 	<= S_idle;    	Ready 		<= '0';		Load_regs 	<= '0';		Clr_Q_C 		<= '0';    	Decr_P 		<= '0';    	Add_regs 		<= '0';    	Shift_regs 	<= '0';			    	case (state) is      	when S_idle =>	Ready <= '1';							if Start = '0' then next_state <= S_idle; 							elsif Empty_data = '1' then Clr_Q_C <= '1'; next_state <= S_idle; 							else Load_regs <= '1'; next_state <= S_add; 							end if;					      	when S_add =>	Decr_P <= '1';							if Empty_m = '1' then next_state <= S_idle;							elsif Q0 = '1' then Add_regs <= '1'; next_state <= S_shift;							else next_state <= S_shift;							end if;																      	when S_shift =>	Shift_regs <= '1';							if Zero = '1' then next_state <= S_idle;							else next_state <= S_add; 							end if; 											when others =>	next_state <= S_idle;    	end case;	end process;end Behavioral;-- Datapath Unitlibrary IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;use IEEE.Std_Logic_unsigned.all;	entity Prob_8_25b_Datapath_vhdl is	generic (dp_width: integer := 5; BC_size: integer := 3); 	port	(Product: out Std_Logic_vector (2*dp_width downto 0);				Q0, Empty_data, Empty_m: out Std_Logic; Zero: buffer Std_Logic;				Multiplicand, Multiplier: in Std_Logic_vector (dp_width - 1 downto 0);				Start, Load_regs, Clr_Q_C, Decr_P, Add_regs, Shift_regs, clock, reset_b: in Std_Logic);end Prob_8_25b_Datapath_vhdl; architecture Behavioral of Prob_8_25b_Datapath_vhdl is 	signal 	Sum: Std_Logic_vector (dp_width downto 0); 	signal	A, B, Q: Std_Logic_vector (dp_width - 1 downto 0);		-- Sized for datapath	 	signal 	C:     Std_Logic;	  	signal	P: integer;														-- Bit counter	signal 	Q0: Std_Logic; 	signal multiplier_0, multiplicand_0: Std_Logic;	begin  	Q0 <= Q(0);		Sum <= ('0' & A) + ('0' & B);	Zero <= '1' when P = 0 else '0';						-- Counter is zero  	Product <= C & A & Q;	 	Empty_data <= '1' when multiplicand_0 = '1' and multiplier_0  = '1' else '0'; 	 	process (multiplier) begin		-- Detect empty multiplier word 		multiplier_0 <= '1'; 		for k in dp_width-1 downto 0 loop 			if multiplier(k) = '1' then multiplier_0 <= '0'; 			end if; 		end loop; 	end process; 		 	process (multiplicand) begin	-- Detect empty multiplicand word 		multiplicand_0 <= '1'; 		for k in dp_width-1 downto 0 loop 			if multiplicand(k) = '1' then multiplicand_0 <= '0'; 			end if; 		end loop; 	end process;	 	-- Nested loops (below) work around the constraint that that left range bound of a loop must be a constant. 	process (P) begin		-- Detect whether remaining multiplier bits are all 0 		Empty_m <= '1'; 		for k in dp_width to 0 loop	 			for m in P-1 to 0 loop if Q(m) = '1' then Empty_m <= '0'; end if; end loop; 		end loop;	 	end process; 	   	process  (clock, reset_b)  	begin      		if (reset_b = '0') then					        		P <= 0;							        		C <= '0'; 				for k in 0 to dp_width-1 loop  					B(k) <= '0'; A(k) <= '0'; Q(k) <= '0'; 				end loop; 				 			elsif clock'event and clock = '1' then 				if (Load_regs = '1') then       				P <= dp_width; 					C <= '0';       				for k in 0 to dp_width-1 loop A(k) <= '0'; end loop;       				B <= Multiplicand;       				Q <= Multiplier; 				end if;  				if Clr_Q_C = '1' then  					C <= '0'; 					for k in dp_width-1 downto 0 loop Q(k) <= '0'; end loop;  				end if;  				if (Add_regs = '1') then 		 					C <= Sum(dp_width); 					A <= Sum(dp_width-1 downto 0);  				end if; 				     				if (Shift_regs = '1') then 					C <= '0'; 				 	A <= C & A(dp_width-1 downto 1); 					Q <= A(0) & Q(dp_width-1 downto 1); 				end if; 				      				if (Decr_P = '1') then  					P <= P -1;	 				end if;				 			end if; 	end process; 		end Behavioral;
