 reset_b;  integer						Exp_Value;  wire							Error;   Prob_8_26 M0 (Product, Ready, Multiplicand, Multiplier, Start, clock, reset_b);  initial #70000 $finish;  initial begin clock = 0; #5 forever #5 clock = ~clock; end  initial fork    reset_b = 1;    #2 reset_b = 0;    #3 reset_b = 1;  join  initial begin #5 Start = 1; end  always @ (posedge Ready) begin    Exp_Value = Multiplier * Multiplicand;  end   assign Error = Ready & (Exp_Value ^ Product);  initial begin    #5 Multiplicand = 0;    Multiplier = 0;    repeat (32) #10 begin Multiplier = Multiplier + 1;      repeat (32) @ (posedge M0.Ready) #5 Multiplicand = Multiplicand + 1;    end  endendmodule
