// Status signals  assign			Product = {C, A, Q};  wire				Zero = (P == 0);			// counter is zero  wire 				Q0 = Q[0];// One-Hot Control unit (See Fig. 8.18)  DFF_S M0 (G0, D0, clock, Set);  DFF M1 (G1, D1, clock, reset_b);  DFF M2 (G2, G1, clock, reset_b);  or (D0, w1, w2);  and (w1, G0, Start_b);  and (w2, Zero, G2);  not (Start_b, Start);  not (Zero_b, Zero);  or (D1, w3, w4);  and (w3, Start, G0);  and (w4, Zero_b, G2);    and (Load_regs, G0, Start);  and (Add_regs, Q0, G1);  assign Ready = G0;    assign Decr_P = G1;  assign Shift_regs = G2;  not (Set, reset_b);// datapath unit  always @ (posedge clock) begin    if (Load_regs) begin      P <= dp_width;      A <= 0;      C <= 0;      B <= Multiplicand;      Q <= Multiplier;    end    if (Add_regs) {C, A} <= A + B;    if (Shift_regs) {C, A, Q} <= {C, A, Q} >> 1;    if (Decr_P) P <= P -1;  endendmodule module DFF_S (output reg Q, input data, clock, Set);  always @ ( posedge clock, posedge Set)    if (Set) Q <= 1'b1; else Q<= data;endmodulemodule DFF (output reg Q, input data, clock, reset_b);  always @ ( posedge clock, negedge reset_b)    if (reset_b == 0) Q <= 1'b0; else Q<= data;endmodule
