gic; 	signal sel: Std_Logic_vector (1 downto 0);		component mux_4x1_beh 	port (m_out: out Std_Logic; 			in_0, in_1, in_2, in_3: in Std_Logic;			sel: in Std_Logic_vector (1 downto 0));	end component;	component D_flip_flop_AR 		port (Q: out Std_Logic; D, CLK, RST: in Std_Logic);	end component;	component decoder_2x4_df 		port (D: out Std_Logic_vector (3 downto 0); 			A, B, enable: in Std_Logic);	end component;begin	PWR <= '1';	GND <= '0'; 	Zero_b <= not Zero;	E_b <= not E ;	sel <= G1 & G0; 	Ready <= not Decoder_out(0);	Incr_R2 <= not Decoder_out(1); 	Shift_left <= not Decoder_out(2);	Load_regs <= Ready and Start;	Mux_1: mux_4x1_beh 	port map	 (D_in1, GND, Zero_b, PWR, E_b, sel);	Mux_0: mux_4x1_beh 	port map	 (D_in0, Start, GND, PWR, E, sel);	M1: D_flip_flop_AR 		port map	 (G1, D_in1, clock, reset_b); 	M0: D_flip_flop_AR 		port map	 (G0, D_in0, clock, reset_b);	M2: decoder_2x4_df 		port map	 (Decoder_out, G1, G0, GND);end Behavioral;Library IEEE;use IEEE.Std_Logic_1164.all;  entity Datapath_STR is	generic (R1_size: integer := 8; R2_size: integer := 4);	port (count: out Std_Logic_vector (R2_size-1 downto 0); 		E, Zero: out Std_Logic; data: Std_Logic_vector 		(R1_size-1 downto 0);		Load_regs, Shift_left, Incr_R2, clock: in Std_Logic);end Datapath_STR;architecture Structural of Datapath_STR is	signal GND: Std_Logic;	signal PWR: Std_Logic;	signal R1: Std_Logic_vector (R1_size -1 downto 0);	signal w1: Std_Logic;		component Shft_Reg port (R1: out Std_Logic_vector (R1_size-1 downto 0);  			data: in Std_Logic_vector (R1_size-1 downto 0);			SI_0, Shift_left, Load_regs, clock, reset_b: in Std_Logic);	end component; 		component Counter port (R2: out Std_Logic_vector (R2_size -1 downto 0); 							Load_regs, Incr_R2, clock, reset_b: in Std_Logic); 	end component;	component D_flip_flop_AR port (Q: out Std_Logic; 						D, CLK, RST: in Std_Logic);	end component;	component and2_gate port (y: out Std_Logic; xin1, xin2: in Std_Logic);	end component;begin	PWR <= '1';	GND <= '0';	process (R1) begin		-- Detect empty R1		Zero <= '1';		for k in R1_size-1 downto 0 loop if R1(k) = '1' then Zero <= '0'; end if; 			end loop; 	end process;	M_1: 	Shft_Reg port map (R1, data, Gnd, Shift_left, Load_regs, clock, 	PWR);	M_2:   Counter ?port map (R2 => count, Load_regs => Load_regs, 				Incr_R2 => Incr_R2, clock =>clock, reset_b => PWR); 	M_3: 	D_flip_flop_AR port map (E, w1, clock, Pwr);	G_1:	and2_gate port map (w1, R1(R1_size -1), Shift_left);end Structural; Library IEEE;use IEEE.Std_Logic_unsigned.all;		-- Needed for + operator in Incr_R2use IEEE.Std_Logic_1164.all;entity Counter is	generic (R2_size: integer := 4);	port (R2: buffer Std_Logic_vector  (R2_size -1 downto 0);	Load_regs, Incr_R2: in Std_Logic; clock, reset_b: in Std_Logic);end Counter;architecture Behavioral of Counter isbegin		process (clock, reset_b) begin	if reset_b = '0' then for k in 0 to R2_size -1 loop R2(k) <= '0'; 	end loop;	elsif clock'event and clock = '1' then 		if Load_regs = '1' then for k in 0 to R2_size -1 loop 			R2(k) <= '1'; 		end loop;		elsif Incr_R2 = '1' then R2 <= R2 + 1;		end if;	end if;	end if;	end process;end Behavioral; Library IEEE;use IEEE.Std_Logic_1164.all; entity Shft_Reg is	generic (R1_size: integer := 8); 	port (R1: buffer Std_Logic_vector (R1_size-1 downto 0);  			data: in Std_Logic_vector (R1_size-1 downto 0);			SI_0, Shift_left, Load_regs, clock, reset_b: in Std_Logic);end Shft_Reg;architecture Behavioral of Shft_Reg isbegin	process (clock, reset_b) begin    		if (reset_b = '0') then for k in 0 to R1_size-1 loop 			R1(k) <= '0'; 			end loop;    		elsif clock'event and clock = '1' then			if (Load_regs = '1') then R1 <= data;         	elsif (Shift_left = '1') then R1 <= R1(R1_size -2 downto 0) & SI_0; 		end if;		end if;	end process;end Behavioral;Library IEEE;use IEEE.Std_Logic_1164.all;entity D_flip_flop_AR is	port (Q: out Std_Logic; D, CLK, RST: in Std_Logic);end D_flip_flop_AR;architecture Behavioral of D_flip_flop_AR isbegin	process (CLK, RST)	begin    		if (RST = '0') then Q <= '0';    		elsif CLK'event and CLK = '1' then Q <= D;			end if;	end process; end Behavioral;Library IEEE;use IEEE.Std_Logic_1164.all;-- Behavioral description of 4-to-1 line multiplexerentity mux_4x1_beh is	port (m_out: out Std_Logic; 			in_0, in_1, in_2, in_3: in Std_Logic;			sel: in Std_Logic_vector (1 downto 0));end mux_4x1_beh;architecture Behavioral of mux_4x1_beh isbegin	process (in_0, in_1, in_2, in_3, sel)	begin      		case (sel) is       		when "00" =>	m_out <= in_0;       		when "01" =>	m_out <= in_1;       		when "10" =>	m_out <= in_2;       		when "11" =>	m_out <= in_3;			when others => m_out <= in_0;		end case;	end process;  end Behavioral;-- Dataflow description of 2-to-4-line decoder-- See Fig. 4.19. Note: The figure uses symbol E, but the-- VHDL model uses enable to clearly indicate functionality.Library IEEE;use IEEE.Std_Logic_1164.all;entity decoder_2x4_df is	port (D: out Std_Logic_vector (0 to 3); A, B, enable: in Std_Logic);end decoder_2x4_df;architecture Behavioral of decoder_2x4_df isbegin	D(0) <= not ((not A) and (not B) and (not enable));	D(1) <= not ((not A) and B and (not enable));	D(2) <= not (A and (not B) and (not enable)); 	D(3) <= not (A and B and (not enable));   end Behavioral; Library IEEE;use IEEE.Std_Logic_1164.all; entity and2_gate is	port (y: out Std_Logic; xin1, xin2: in Std_Logic);	end and2_gate;	architecture Behavioral of and2_gate isbegin		y <= xin1 and xin2;end Behavioral; -- TestbenchLibrary IEEE;use IEEE.Std_Logic_1164.all;entity t_Count_Ones is  	generic (R1_size: integer := 8; R2_size: integer := 4); end t_Count_ones;architecture Behavioral of t_Count_ones is  	signal	t_R2: Std_Logic_vector (R2_size -1 downto 0);  	signal	t_count: integer;  	signal	t_Ready: Std_Logic;	signal	t_data : Std_Logic_vector (R1_size -1 downto 0);   						signal t_Start, t_clk, t_reset_b: Std_Logic;		 	component Prob_8_35_Count_Ones_STR_STR_vhdl 		generic (R1_size: integer := 8; R2_size: integer := 4);		port  (count: out Std_Logic_vector (R2_size-1 downto 0); 			Ready: out Std_Logic; 			data: in Std_Logic_vector (R1_size-1 downto 0);			Start, clock, reset_b: in Std_Logic);	end component;begin	UUT: Prob_8_35_Count_Ones_STR_STR_vhdl 		generic map (R1_size => 8, R2_size => 4)		port map (t_count, t_Ready, t_data,t_Start, t_clk, t_reset_b);process -- clock for testbenchbegin	t_clk <= '0'; wait for 5 ns;t_clk <= '1';wait for 5 ns;end process;	t_Start <= '0';	t_reset_b <= '1' after 1 ns;	t_reset_b <= '0' after 3 ns;	t_reset_b <= '1' after 4 ns;     	t_data <= "11111111" after 4 ns;    	t_Start <= '1' after 4 ns;     t_Start <= '0' after 300 ns;     t_data <= "00001111" after 310 ns;     t_Start <= '1' after 310 ns;     t_Start <= '0' after 320 ns;     t_data <= "11110000" after 610 ns;     t_Start <= '1' after 610 ns;     t_Start <= '0' after 620 ns;     t_data <= "00000000" after 910 ns;     t_Start <= '1' after 910 ns;     t_Start <= '0' after 920 ns;     t_data <= "10101010" after 1210 ns;     t_Start <= '1' after 1210 ns;     t_Start <= '0' after 1220 ns;     t_data <= "00001010" after 1510 ns;     t_Start <= '1' after 1510 ns;     t_Start <= '0' after 1520 ns;     t_data <= "10100000" after 1810 ns;     t_Start <= '1' after 1810 ns;     t_Start <= '0' after 1820 ns;     t_data <= "01010101" after 2110 ns;     t_Start <= '1' after 2110 ns;     t_Start <= '0' after 2120 ns;     t_data <= "00000101" after 2410 ns;     t_Start <= '1' after 2410 ns;     t_Start <= '0' after 2420 ns;     t_data <= "0101" after 2710 ns;     t_Start <= '1' after 2710ns;     t_Start <= '0' after 2720 ns;     t_data <= "10100101" after 3010 ns;     t_Start <= '1' after 3010 ns;     t_Start <= '0' after 3020 ns;     t_data <= "01011010" after 3310 ns;	t_Start <= '1' after 3310 ns;     t_Start <= '0' after 3320 ns;end Behavioral;
8.36	Note: See Prob.   for a behavioral model of the datapath unit, Prob. 8.36d for a one-hot control unit.(a) T0, T1, T2, T3 be asserted when the state is in S_idle, S_1, S_2, and S_3, respectively. Let D0, D1, D2, and D3 denote the inputs to the one-hot flip-flops.D0 =  T0 Start' + T1 ZeroD1 = T0 Start + T3 ED2 = T1 Zero' + T3 E'D3 = T2(b) Gate-level one-hot controller		Verilogmodule Controller_Gates_1Hot(  output 		Ready,   output 		Load_regs, Incr_R2, Shift_left,   input 		Start, Zero, E, clock, reset_b);  wire w1, w2, w3, w4, w5, w6;  wire T0, T1, T2, T3;  wire set;  assign Ready = T0;  assign Incr_R2 = T1;  assign Shift_left = T2;  and (Load_regs, T0, Start);  not (set, reset_b);  DFF_S M0 (T0, D0, clock, set);		// Note: reset action must initialize S_idle = 4'b0001  DFF M1 (T1, D1, clock, reset_b);  DFF M2 (T2, D2, clock, reset_b);  DFF M3 (T3, D3, clock, reset_b);  not (Start_b, Start);  and (w1, T0, Start_b);  and (w2, T1, Zero);  or (D0, w1, w2);  
  and (w3, T0, Start);  and (w4, T3, E);  or (D1, w3, w4);  not (Zero_b, Zero);  not (E_b, E);  and (w5, T1, Zero_b);  and (w6, T3, E_b);  or (D2, w5, w6);    buf (D3, T2);endmodulemodule DFF (output reg Q, input D, clock, reset_b);  always @ (posedge clock, negedge reset_b)    if (reset_b == 0) Q <= 0;    else Q <= D;endmodulemodule DFF_S (output reg Q, input D, clock, set);  always @ (posedge clock, posedge set)    if (set == 1) Q <= 1;	else Q <= D;endmoduleVHDLLibrary IEEE;use IEEE.Std_Logic_1164.all;entity Prob_8_36b_Controller_Gates_1Hot_vhdl is	port (Ready: out Std_Logic; Load_regs, Incr_R2, Shft_left: out Std_Logic;			Start, Zero, E, clock, reset_b: in Std_Logic);end Prob_8_36b_Controller_Gates_1Hot_vhdl;architecture Structural of Prob_8_36b_Controller_Gates_1Hot_vhdl is 	signal w1, w2, w3, w4, w5, w6: Std_Logic;	signal D0, D1, D2, D3, T0, T1, T2, T3: Std_Logic;	signal Zero_b, E_b,Start_b, set: Std_Logic;	component D_FF_S		port (Q: out Std_Logic; D, clock, set: in Std_Logic);	end component;	component D_FF		port (Q: out Std_Logic; D, clock, reset_b: in Std_Logic);	end component;	component not_gate		port (y: out Std_Logic; xin: in Std_Logic);	end component;	component and2_gate		port (y: out Std_Logic; xin1, xin2: in Std_Logic);	end component;	component or2_gate		port (y: out Std_Logic; xin1, xin2: in Std_Logic);	end component;	component buf_gate		port (y: out Std_Logic; xin: in Std_Logic);	end component;begin	Ready <= T0;	Incr_R2 <= T1; 	Shft_left <= T2;	M0: D_FF_S port map (T0, D0, clock, set);		-- Note: reset action must initialize S_idle = 4'b0001	D_FF_1: D_FF port map (T1, D1, clock, reset_b);	D_FF_2: D_FF port map (T2, D2, clock, reset_b);	D_FF_3: D_FF port map (T3, D3, clock, reset_b);	G_1: not_gate port map (Start_b, Start);	G_2: and2_gate port map (w1, T0, Start_b);	G_3: and2_gate port map (w2, T1, Zero);	G_4: or2_gate port map (D0, w1, w2);	G_5: and2_gate port map (w3, T0, Start);  	G_6: and2_gate port map (w4, T3, E);	G_7: or2_gate port map (D1, w3, w4);	G_8: not_gate port map (Zero_b, Zero);	G_9: not_gate port map (E_b, E);	G_10: and2_gate port map (w5, T1, Zero_b);	G_11: and2_gate port map (w6, T3, E_b);	G_12:	or2_gate port map (D2, w5, w6); 	G_13: buf_gate port map (D3, T2);	G_14: and2_gate port map (Load_regs, T0, Start);	G_15: not_gate port map (set, reset_b);end Structural;entity and2_gate is  port (y: out bit; xin1, xin2: in bit);end and2_gate;architecture Behavioral of and2_gate isbegin	y <= xin1 and xin2;end Behavioral;entity or2_gate is  port (y: out bit; xin1, xin2: in bit);end or2_gate;architecture Behavioral of or2_gate isbegin	y <= xin1 or xin2;end Behavioral;entity not_gate is  port (y: out bit; xin: in bit);end not_gate;architecture Behavioral of not_gate isbegin	y <= not (xin);end Behavioral;entity buf_gate is  port (y: out bit; xin: in bit);end buf_gate;architecture Behavioral of buf_gate isbegin	y <= xin;end Behavioral;Library IEEE;use IEEE.Std_Logic_1164.all;entity D_FF is	port (Q: out Std_Logic; D, clock, reset_b: in Std_Logic);end D_FF;architecture Behavioral of D_FF isbegin   process (clock, reset_b) begin		if (reset_b = '0') then Q <= '0';    elsif clock'event and clock = '1' then  Q <= D;		end if;	end process;end Behavioral;Library IEEE;use IEEE.Std_Logic_1164.all;entity D_FF_S isport (Q: out Std_Logic; D, clock, set: in Std_Logic);end D_FF_S;architecture Behavioral of D_FF_S isbegin	process (clock, set) begin    if (set = '1') then Q <= '1';    elsif clock'event and clock = '1' then Q <= D;	 end if;	end process;end Behavioral;(c)// Test plan for Control Unit // Verify that state enters S_idle with reset_b asserted.// With reset_b de-asserted, verify that state enters S_1 and asserts Load_Regs when // Start is asserted.// Verify that Incr_R2 is asserted in S_1.// Verify that state returns to S_idle from S_1 if Zero is asserted.// Verify that state goes to S_2 if Zero is not asserted.// Verify that Shift_left is asserted in S_2.// Verify that state goes to S_3 from S_2 unconditionally.//  Verify that state returns to S_2 from S_3 id E is not asserted.// Verify that state goes to S_1 from S_3 if E is asserted.// Test bench for One-Hot Control Unitmodule t_Control_Unit ();  wire Ready, Load_regs, Incr_R2, Shift_left;   reg Start, Zero, E, clock, reset_b;  wire [3: 0] state = {M0.T3, M0.T2, M0.T1, M0.T0};		// Observe one-hot state bits  Controller_Gates_1Hot M0 (Ready, Load_regs, Incr_R2, Shift_left, Start, Zero, E, clock, reset_b);  initial #250 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial begin reset_b = 0; #2 reset_b = 1; end  initial fork    Zero = 1;    E = 0;    Start = 0;    #20 Start = 1;	// Cycle from S_idle to S_1    #80 Start = 0;    #70 Zero = 0;		// S_idle to S_1 to S_2 to S_3 and cycle to S_2.    #130 E = 1;		// Cycle to S_3 to S_1 to S_2 to S_3    #150 Zero = 1;	// Return to S_idle  joinendmoduleNote: simulation results match those for Prob. 8.34(d). See Prob.  (c) for annotations.  (d) Datapath unit detail:			Verilog//  Datapath unit – structural modelmodule Datapath_STR #(parameter dp_width = 8, R2_width = 4)(   output [R2_width -1: 0] count, output E, output Zero, input [dp_width -1: 0] data,      input Load_regs, Shift_left, Incr_R2, clock, reset_b);  supply1 pwr;  supply0 gnd;  wire [dp_width -1: 0] R1_Dbus, R1;  wire [R2_width -1: 0] R2_Dbus;  wire DR1_0, DR1_1, DR1_2, DR1_3, DR1_4, DR1_5, DR1_6, DR1_7;  wire R1_0, R1_1, R1_2, R1_3, R1_4, R1_5, R1_6, R1_7;  wire R2_0, R2_1, R2_2, R2_3;     wire [R2_width -1: 0] R2 = {R2_3, R2_2, R2_1, R2_0};  assign count = {R2_3, R2_2, R2_1, R2_0};  assign R1 = { R1_7, R1_6, R1_5, R1_4, R1_3, R1_2, R1_1, R1_0};  assign DR1_0 = R1_Dbus[0];  assign DR1_1 = R1_Dbus[1];  assign DR1_2 = R1_Dbus[2];  assign DR1_3 = R1_Dbus[3];  assign DR1_4 = R1_Dbus[4];  assign DR1_5 = R1_Dbus[5];  assign DR1_6 = R1_Dbus[6];  assign DR1_7 = R1_Dbus[7];  nor (Zero, R1_0, R1_1, R1_2, R1_3, R1_4, R1_5, R1_6, R1_7);  DFF D_E (E, R1_7, clock, pwr);    DFF DF_0 (R1_0, DR1_0, clock, pwr);		// Disable reset  DFF DF_1 (R1_1, DR1_1, clock, pwr);  DFF DF_2 (R1_2, DR1_2, clock, pwr);  DFF DF_3 (R1_3, DR1_3, clock, pwr);  DFF DF_4 (R1_4, DR1_4, clock, pwr);  DFF DF_5 (R1_5, DR1_5, clock, pwr);  DFF DF_6 (R1_6, DR1_6, clock, pwr);  DFF DF_7 (R1_7, DR1_7, clock, pwr);  DFF_S DR_0 (R2_0, DR2_0, clock, Load_regs);	// Load_regs (set) drives R2 to all ones  DFF_S DR_1 (R2_1, DR2_1, clock, Load_regs);  DFF_S DR_2 (R2_2, DR2_2, clock, Load_regs);  DFF_S DR_3 (R2_3, DR2_3, clock, Load_regs);  assign DR2_0 = R2_Dbus[0];  assign DR2_1 = R2_Dbus[1];  assign DR2_2 = R2_Dbus[2];  assign DR2_3 = R2_Dbus[3];  wire [1: 0] sel = {Shift_left, Load_regs};  wire [dp_width -1: 0] R1_shifted = {R1_6, R1_5, R1_4, R1_3, R1_2, R1_1, R1_0, 1'b0};  wire [R2_width -1: 0] sum = R2 + 4'b0001;  Mux8_4_x_1 M0 (R1_Dbus, R1, data, R1_shifted, R1, sel);  Mux4_2_x_1 M1 (R2_Dbus, R2, sum, Incr_R2);endmodulemodule Mux8_4_x_1 #(parameter dp_width = 8) (output reg [dp_width -1: 0] mux_out,   input [dp_width -1: 0] in0, in1, in2, in3, input [1: 0] sel);  always @ (in0, in1, in2, in3, sel)    case (sel)      2'b00:	mux_out = in0;      2'b01:	mux_out = in1;      2'b10:	mux_out = in2;      2'b11:	mux_out = in3;    endcaseendmodulemodule Mux4_2_x_1 #(parameter dp_width = 4) (output [dp_width -1: 0] mux_out,   input [dp_width -1: 0] in0, in1, input  sel);  assign mux_out = sel ? in1: in0;endmodule// Test Plan for Datapath Unit:// Demonstrate action of Load_regs// 	R1 gets data, R2 gets all ones// Demonstrate action of Incr_R2// Demonstrate action of Shift_left and detect E// Test bench for datapathmodule t_Datapath_Unit #(parameter dp_width = 8, R2_width = 4)( );  wire [R2_width -1: 0] 	count;  wire 						E, Zero;  reg [dp_width -1