tes_1Hot(  output 		Ready, Load_regs, Add_shift,  input 		Start, Zero, clock, reset_b);  wire w1, w2, w3, w4;  wire T0, T1;  wire set;  assign Ready = T0;  assign Add_shift = T1;  and (Load_regs, T0, Start);  not (set, reset_b);  DFF_S M0 (T0, D0, clock, set);		// Note: reset action must initialize S_idle = 2'b01  DFF M1 (T1, D1, clock, reset_b);  not (Start_b, Start);  not (Zero_b, Zero);  and (w1, T0, Start_b);  and (w2, T1, Zero);  or (D0, w1, w2);  and (w3, T0, Start);  and (w4, T1, Zero_b);  or (D1, w3, w4);endmodulemodule DFF (output reg Q, input D, clock, reset_b);  always @ (posedge clock, negedge reset_b)    if (reset_b == 0) Q <= 0;    else Q <= D;endmodulemodule DFF_S (output reg Q, input D, clock, set);  always @ (posedge clock, posedge set)    if (set == 1) Q <= 1;    else Q <= D;endmoduleVHDL - Gate-level one-hot controllerLibrary IEEE;use IEEE>Std_Logic_1164.all;entity Prob_8_37d_Controller_2_Gates_1Hot is	port (Ready, Load_regs, Add_shift: out Std_Logic;		Start, Zero, clock, reset_b: in Std_Logic);end Prob_8_37d_Controller_2_Gates_1Hot;architecture Structural of Prob_8_37d_Controller_2_Gates_1Hot is	signal w1, w2, w3, w4: Std_Logic;	signal T0, T1: Std_Logic;	signal set: Std_Logic;	signal D0, D1: Std_Logic;	signal Zero_b, Start_b: Std_Logic;	component D_FF port (Q: out Std_Logic, D, clock, reset_b: in Std_Logic);	end component;	component D_FF_S port (Q: out Std_Logic; D, clock, set: in Std_Logic);	end component;begin	Ready <= T0;  	Add_shift <= T1;	Load_regs <= T0 and Start; 	set <= not reset_b;  	M0:	D_FF_S port map (T0, D0, clock, set);		-- Note: reset action must   	M1:	D_FF port map (T1, D1, clock, reset_b);	-- initialize S_idle = 2'b01 	Start_b <= not Start; 	Zero_b <= not  Zero; 	w1 <=  T0  and Start_b;  	w2 <= T1 and Zero;	D0 <= w1 or w2;	w3 <= T0 and Start;	w4 <= T1 and Zero_b;  	D1  <= w3 or w4;end Structural;entity D_FF is	port (Q: out Std_Logic; D, clock, reset_b