ry IEEE;use IEEE.Std_Logic_1164.all;entity D_FF_S is	port (Q: out Std_Logic; D, clock, set: in Std_Logic);end D_FF_S;architecture Behavioral of D_FF_S isbegin	process (clock, set) begin		if (set = '1') then Q <= '1';    		elsif clock'event and clock = '1' then Q <= D; end if;	end process;end Behavioral;
8.38	Verilog module Prob_8_38 (  output reg [7: 0] 	Sum,   output reg 			Car_Bor,			  input [7: 0] 			Data_A, Data_B);  reg [7: 0]				Reg_A, Reg_B;      always @ (Data_A, Data_B)           case ({Data_A[7], Data_B[7]})		            2'b00, 2'b11:			begin								// ++, --    			 				   {Car_Bor, Sum[6: 0]} = Data_A[6: 0] + Data_B[6: 0];              	  	   Sum[7] = Data_A[7];            		end                    default:				if (Data_A[6: 0] >= Data_B[6: 0]) begin				// +-, -+          {Car_Bor, Sum[6: 0]} = Data_A[6: 0] - Data_B[6: 0];          Sum[7] = Data_A[7];       end       else begin          {Car_Bor, Sum[6: 0]} = Data_B[6: 0] - Data_A[6: 0];          Sum[7] = Data_B[7];       end      endcaseendmodulemodule t_Prob_8_38 ();  wire [7: 0] 	Sum;  wire 			Car_Bor;  reg [7: 0] 	Data_A, Data_B;  wire [6: 0] 	Mag_A, Mag_B;  assign 		Mag_A = M0.Data_A[6: 0];			// Hierarchical dereferencing  assign 		Mag_B = M0.Data_B[6: 0];  wire 			Sign_A = M0.Data_A[7];  wire 			Sign_B = M0.Data_B[7];  wire 			Sign = Sum[7];  wire [7: 0] 	Mag = Sum[6: 0];  Prob_8_38 M0 (Sum, Car_Bor,  Data_A, Data_B);  initial #650 $finish;  
  initial fork      // Addition								//  A        B     #0 begin Data_A = {1'b0, 7'd25}; Data_B = {1'b0, 7'd10}; end			//+25, +10     #40 begin Data_A = {1'b1, 7'd25}; Data_B = {1'b1, 7'd10}; end		// -25, -10	    #80 begin Data_A = {1'b1, 7'd25}; Data_B = {1'b0, 7'd10}; end		// -25, +10    #120 begin Data_A = {1'b0, 7'd25}; Data_B = {1'b1, 7'd10}; end		// 25, -10									//  B        A    #160 begin Data_B = {1'b0, 7'd25}; Data_A = {1'b0, 7'd10}; end		//+25, +10    #200 begin Data_B = {1'b1, 7'd25}; Data_A = {1'b1, 7'd10}; end		// -25, -10    #240 begin Data_B = {1'b1, 7'd25}; Data_A = {1'b0, 7'd10}; end		// -25, +10	      #280 begin Data_B = {1'b0, 7'd25}; Data_A = {1'b1, 7'd10}; end		// +25, -10    // Addition of matching numbers    #320 begin Data_A = {1'b1,7'd0}; Data_B = {1'b1,7'd0}; end			// -0, -0     #360 begin Data_A = {1'b0,7'd0}; Data_B = {1'b0,7'd0}; end			// +0, +0     #400 begin Data_A = {1'b0,7'd0}; Data_B = {1'b1,7'd0}; end			// +0, -0     #440 begin Data_A = {1'b1,7'd0}; Data_B = {1'b0,7'd0}; end			// -0, +0     #480 begin Data_B = {1'b0, 7'd25}; Data_A = {1'b0, 7'd25}; end		// matching +    #520 begin Data_B = {1'b1, 7'd25}; Data_A = {1'b1, 7'd25}; end		// matching –    // Test of carry (negative numbers)    #560 begin Data_A = 8'hf0; Data_B = 8'hf0; end						// carry - -    // Test of carry (positive numbers)    #600 begin Data_A = 8'h70; Data_B = 8'h70; end	 					// carry ++  joinendmoduleVHDL entity Prob_8_38_vhdl is	port (Sum: out Std_Logic_vector (7 downto 0); Car_Bor: out Std_Logic;				Data_A, Data_B: in Std_Logic_vector (7 downto 0 );	end Prob_8_38_vhdl; 	architecture Behavioral of Prob_8_38_vhdl is			signal 	Reg_A, Reg_B: Std_Logic_vector (7 downto 0);;begin      process (Data_A, Data_B)           case (Data_A(7) & Data_B(7))    		--    ++, --          	when "00", "11" =>	    			 				   Car_Bor & Sum(6 downto 0) <= Data_A(6 downto 0] + Data_B(6  0);              	  	   Sum(7) = Data_A(7);   -- 	+-, -+        when others =>		if Data_A(6 downto 0) >= Data_B(6  downto 0)  then				          Car_Bor & Sum(6 downto 0) <= Data_A( downto 0) - Data_B(6 downto 0);          Sum(7)  <= Data_A(7);       else           Car_Bor & Sum(6: 0) <= Data_B(6  downto 0) - Data_A(6 downto 0);          Sum(7) <= Data_B(7);       end if;      end case;end Behavioral;
8.39	Block diagram and ASMD chart:		Verilogmodule Prob_8_39 (  output 	[15: 0] 	PR, output done,   input 		[7: 0] 	data_AR, data_BR, input  start, clock, reset_b);   Controller_P8_39 M0 (done, Ld_regs, Add_decr, start, zero, clock, reset_b); Datapath_P8_39 M1 (PR, zero, data_AR, data_BR, Ld_regs, Add_decr, clock, reset_b);endmodulemodule Controller_P8_16 (output done, output reg Ld_regs, Add_decr, input start, zero, clock, reset_b);  parameter  	s0 = 1'b0, s1 = 1'b1;  reg 		state, next_state;  assign done = (state == s0);  
  always @ (posedge clock, negedge reset_b)     if (!reset_b) state <= s0; else state <= next_state;  always @ (state, start, zero) begin    Ld_regs = 0;    Add_decr = 0;    case (state)      s0:		if (start) begin Ld_regs = 1; next_state = s1; end      s1:		if (zero) next_state = s0; else  begin next_state = s1; Add_decr = 1; end       default:	next_state = s0;    endcase  endendmodulemodule  Datapath_P8_16 (  output reg 	[15: 0] 	PR, output zero,   input 		[7: 0] 	data_AR, data_BR, input Ld_regs, Add_decr, clock, reset_b);  reg 		[7: 0]	AR, BR;  assign 	zero = ~( | AR);  always @ (posedge clock, negedge reset_b)    if (!reset_b) begin AR <= 8'b0; BR <= 8'b0; PR <= 16'b0; end    else begin      if (Ld_regs) begin AR <= data_AR; BR <= data_BR; PR <= 0; end      else if (Add_decr) begin PR <= PR + BR; AR <= AR -1; end    end  endmodule // Test plan – Verify;// Power-up reset// Data is loaded correctly// Control signals assert correctly// Status signals assert correctly// start is ignored while multiplying// Multiplication is correct// Recovery from reset on-the-fly module t_Prob_P8_16;  wire 		done;  wire 	[15: 0] 	PR;  reg 	[7: 0] 	data_AR, data_BR;  reg  		start, clock, reset_b;    Prob_8_16 M0 (PR, done, data_AR, data_BR, start, clock, reset_b);  initial #500 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork     reset_b = 0;       #12 reset_b = 1;     #40 reset_b = 0;    #42 reset_b = 1;    #90 reset_b = 1;    #92 reset_b = 1;  join  
  initial fork    #20 start = 1;    #30 start = 0;    #40 start = 1;    #50 start = 0;    #120 start = 1;    #120 start = 0;  join  initial fork    data_AR = 8'd5;		// AR > 0    data_BR = 8'd20;    #80 data_AR = 8'd3;    #80 data_BR = 8'd9;    #100 data_AR = 8'd4;    #100 data_BR = 8'd9;  joinendmodule VHDLLibrary IEEE;use IEEE.Std_Logic_1164.all;entity Prob_8_39_vhdl is   port (PR: out Std_Logic_vector (16 downto 0); done: out Std_Logic; data_AR, data_BR:              in Std_Logic_Vector (7 downto 0); start, clock, reset_b: in Std_Logic);end Prob_8_39_vhdl; architecture ASMD of Prob_8_39_vhdl is-- Interface signals	signal Ld_regs, Add_decr, zero: Std_Logic;	-- Components	component Controller_P8_39 port (done, Ld_regs, Add_decr: out Std_Logic;				Start, zero, clock, reset_b: in Std_Logic);				end component;	component Datapath_P8_39 port(PR: out Std_Logic_Vector (16 downto 0); 				zero: out Std_Logic; 				data_AR, data_BR: in Std_Logic_Vector (7 downto 0); 				Ld_regs, Add_decr, clock, reset_b: in Std_Logic);	end component;begin-- Instantiations of Components	M0: Controller_P8_39 port map (done, Ld_regs, Add_decr, start, zero, clock, reset_b);	M1: Datapath_P8_39 port map (PR, zero, data_AR, data_BR, Ld_regs, Add_decr, clock, reset_b);end ASMD;Library IEEE;use IEEE.Std_Logic_1164.all;entity Controller_P8_39 is	port (done: out Std_Logic; Ld_regs, Add_decr: out Std_Logic; start, zero, clock, reset_b: in Std_Logic);end Controller_P8_39;architecture Behavioral of Controller_P8_39 is    constant	s0: Std_Logic	:= '0';	constant 	s1: Std_Logic	:= '1';    signal 		state, next_state: Std_Logic;begin     done <= '1' when state = s0 else '0';	process (clock, reset_b) begin 		if reset_b = '0' then state <= s0; 		elsif clock'event and clock = '1' then state <= next_state; end if;	end process;  process (state, start, zero) begin    Ld_regs <= '0';    Add_decr <= '0';	 next_state <= s0;    case state is      when s0 =>	if (start = '1') then Ld_regs <= '1'; next_state <= s1; else next_state <= s0; end if;      when s1 =>	if (zero = '1') then next_state <= s0; else next_state <= s1; Add_decr <= '1';	end if;       when others =>	next_state <= s0;    end case;  end process;end Behavioral;Library IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_Unsigned.all;entity  Datapath_P8_39 isport (PR: buffer Std_Logic_vector (16 downto 0); zero: out Std_Logic; data_AR, data_BR: in Std_Logic_Vector (7 downto 0); Ld_regs, Add_decr, clock, reset_b: in Std_Logic);end Datapath_P8_39;architecture Behavioral of Datapath_P8_39 is	signal Ar, BR: Std_Logic_vector (7 downto 0);begin	-- zero <= not( AR(7) or AR(6) or AR(5) or AR(4) or AR(3) or AR(2) or AR(1) or AR(0));	process (AR) begin		zero <= '1';		for k in 0 to 7 loop			if AR(k) = '1' then Zero <= '0'; end if; 		end loop;	end process;				process (clock, reset_b) begin		if reset_b = '0' then AR <= "00000000"; BR <= "00000000"; PR <= "00000000000000000"; 		elsif clock'event and clock = '1' then  			if Ld_regs = '1' then AR <= data_AR; BR <= data_BR; for k in 0 to 16 loop PR(k) <= '0'; end loop;			elsif Add_decr = '1' then PR <= PR + ('0' & BR); AR <= AR -1; end if;		end if;	end process;end Behavioral;-- Test plan (Operational features to verify) -- Power-up reset -- Data is loaded correctly -- Control signals assert correctly -- Status signals assert correctly -- start is ignored while multiplying -- Multiplication is correct -- Recovery from reset on-the-fly Library IEEE;use IEEE.Std_Logic_1164.all;entity t_Prob_P8_39 isend t_Prob_P8_39;architecture Test_Bench of t_Prob_P8_39 issignal 	t_done: Std_Logic;signal 	t_PR: Std_Logic_Vector (15 downto 0);signal	t_data_AR, t_data_BR: Std_Logic_Vector (7 downto 0);signal  t_start, t_clock, t_reset_b: Std_Logic;component Prob_8_39 port (PR: out Std_Logic_Vector (15 downto 0); done: out Std_Logic; 		data_AR, data_BR: in Std_Logic_Vector (7 downto 0); start, clock, reset_b: in Std_Logic);end component;beginM_UUT: Prob_8_39 port map (PR => t_PR, done => t_done, data_AR => t_data_AR, data_BR => t_data_BR, start => t_start, clock => t_clock, reset_b => t_reset_b);process  begin	t_clock <= '0'; 	wait for 5ns;	t_clock <= '1';	wait for 5ns;end process;    t_reset_b <= '0';     t_reset_b <= '1' after 12 ns;     t_reset_b <= '0' after 40 ns;    t_reset_b <= '1' after 42 ns;    t_reset_b <= '1' after 90 ns;    t_reset_b <= '1' after 92 ns;    t_start <= '1' after 20 ns;    t_start <= '0' after 30 ns;    t_start <= '1' after 40 ns;    t_start <= '0' after 50 ns;    t_start <= '1' after 120 ns;    t_start <= '0' after 120 ns;    t_data_AR <= "00000101";		     t_data_BR <= "00010100";		     t_data_AR <= "00000011" after 80 ns;    t_data_BR <= "00001001" after 80 ns;    t_data_AR <= "00000100" after 100 ns;    t_data_BR <= "00001001" after 100 ns;end Test_Bench;8.40
Verilogmodule Prob_8_40 (  output 	[7: 0]		 Data_out,  output				Ready, Got_Data, Done_Product,  input 	[7: 0] 		Data_in,  input 				Start, Run, Send_Data, clock, reset_b);Controller M0 (    Ready, Shift_in, Got_Data, Done_Product, Decr_P, Add_regs, Shift_regs, Shift_out,    Start, Run, Send_Data, Zero, Q0, clock, reset_b);Datapath M1(Data_out, Q0, Zero, Data_in,  Start, Shift_in, Decr_P, Add_regs, Shift_regs, Shift_out, clock);	endmodulemodule Controller (    output reg Ready, Shift_in, Got_Data, Done_Product, Decr_P, Add_regs,       Shift_regs, Shift_out,    input Start, Run, Send_Data, Zero, Q0, clock, reset_b);  parameter	S_idle =	5'd20, 		 				S_Ld_0 =	5'd0,					S_Ld_1 =	5'd1,				S_Ld_2 =	5'd2, 				S_Ld_3 =	5'd3,					S_Ld_4 =	5'd4,				S_Ld_5 =	5'd5, 				S_Ld_6 =	5'd6,					S_Ld_7 =	5'd7,				S_wait_1 = 5'd8,	// Wait state        			S_add = 	5'd9, 		       			S_Shift = 	5'd10,				S_product = 	5'd11,				S_wait_2 = 	5'd12,	// Wait state				S_Send_0 = 	5'd13,				S_Send_1 =	5'd14, 				S_Send_2 =	5'd15, 				S_Send_3 =	5'd16, 				S_Send_4 = 	5'd17,				S_Send_5 = 	5'd18,				S_Send_6 = 	5'd19;  reg	[4: 0]			state, next_state;  always @ (posedge clock, negedge reset_b)    if (~reset_b) state <= S_idle; else state <= next_state;  always @ (state, Start, Run, Q0, Zero, Send_Data) begin    next_state = S_idle;				// Prevent accidental synthesis of latches    Ready = 0;    Shift_in = 0;    Shift_regs = 0;    Add_regs = 0;    Decr_P = 0;    Shift_out = 0;    Got_Data = 0;    Done_Product = 0;    
    case (state)	// Assign by exception to default values      S_idle:			begin 				  	  Ready = 1; 			       	  if (Start) begin next_state = S_Ld_0; Shift_in = 1; end 					end      S_Ld_0:		begin next_state = S_Ld_1; Shift_in = 1; end			 	      S_Ld_1:		begin next_state = S_Ld_2; Shift_in = 1; end      S_Ld_2:		begin next_state = S_Ld_3; Shift_in = 1; end          S_Ld_3:		begin next_state = S_Ld_4; Shift_in = 1; end  	      S_Ld_4:		begin next_state = S_Ld_5; Shift_in = 1; end       S_Ld_5:		begin next_state = S_Ld_6; Shift_in = 1; end         S_Ld_6:		begin next_state = S_Ld_7; Shift_in = 1; end 	      S_Ld_7:		begin Got_Data = 1;  			  		  if (Run) next_state = S_add; 			  		  else next_state = S_wait_1;					end      S_wait_1:		if (Run) next_state = S_add; else next_state = S_wait_1;      S_add:		begin next_state = S_Shift; Decr_P = 1; if (Q0) Add_regs = 1; end      S_Shift:		begin Shift_regs = 1; if (Zero) next_state = S_product; 					else next_state = S_add; end      S_product:	begin 					  Done_Product = 1; 					  if (Send_Data) begin  next_state = S_Send_0; Shift_out = 1; end					  else next_state = S_wait_2; end      S_wait_2:		if (Send_Data) begin next_state =S_Send_0; Shift_out = 1; end					else next_state = S_wait_2;      S_Send_0:	begin next_state = S_Send_1; Shift_out = 1; end       S_Send_1:	begin next_state = S_Send_2; Shift_out = 1; end       S_Send_2:	begin next_state = S_Send_3; Shift_out = 1; end       S_Send_3:	begin next_state = S_Send_4; Shift_out = 1; end       S_Send_4:	begin next_state = S_Send_5; Shift_out = 1; end       S_Send_5:	begin next_state = S_Send_6; Shift_out = 1; end       S_Send_6:	begin next_state = S_idle; Shift_out = 1; end       default:		next_state = S_idle;    endcase  endendmodulemodule Datapath #(parameter dp_width = 32, P_width = 6) (  output	[7: 0] 		Data_out,   output 				Q0, Zero,   input 	[7: 0] 		Data_in,  input 				Start, Shift_in, Decr_P, Add_regs, Shift_regs, Shift_out, clock);  reg	[dp_width - 1: 0]		A, B, Q;				// Sized for datapath  reg 							C;  reg	[P_width - 1: 0]		P;  assign 						Q0 = Q[0];	  assign						Zero = (P == 0);			// counter is zero  assign 						Data_out = {C, A, Q};  always @ (posedge clock) begin    if (Shift_in) begin      P <= dp_width;      A <= 0;      C <= 0;      B[7: 0] 	<= B[15: 8];		// Treat B and Q registers as a pipeline to load data bytes      B[15: 8] 	<= B[ 23: 16];      B[23: 16] 	<= B[31: 24];      B[31: 24] 	<= Q[7: 0];      Q[7: 0] 	<= Q[15: 8];      Q[15: 8] 	<= Q[ 23: 16];      Q[23: 16]	<= Q[31: 24];      Q[31: 24] 	<= Data_in;    end    if (Add_regs) {C, A} <= A + B;    if (Shift_regs) {C, A, Q} <= {C, A, Q} >> 1;    if (Decr_P) P <= P -1;    if (Shift_out) begin {C, A, Q} <= {C, A, Q} >> 8; end  endendmodule module t_Prob_8_40;  parameter			dp_width = 32;			// Width of datapath  wire 	[7: 0] 			Data_out;  wire					Ready, Got_Data, Done_Product;  reg	 				Start, Run, Send_Data, clock, reset_b;  integer				Exp_Value;  reg					Error;  wire	[7: 0]			Data_in;  reg [dp_width -1: 0] 			Multiplicand, Multiplier;  reg [2*dp_width -1: 0]		Data_register;			// For test patterns  assign						Data_in = Data_register [7:0];  wire [2*dp_width -1: 0]		product;  assign						product = {M0.M1.C, M0.M1.A, M0.M1.Q};  Prob_8_40  M0 (    Data_out,  Ready, Got_Data, Done_Product, Data_in, Start, Run, Send_Data, clock, reset_b);  initial #2000 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork    reset_b = 1;    #2 reset_b = 0;    #3 reset_b = 1;  join  initial fork     Start =0;    Run = 0;    Send_Data = 0;    #10 Start = 1;     #20 Start = 0;    #50 Run= 1;		// Ignored by controller    #60 Run = 0;    #120 Run = 1;    #130 Run = 0;    #830 Send_Data = 1;    #840 Send_Data = 0;  join  // Test patterns for multiplication  initial begin     Multiplicand = 32'h0f_00_00_aa;    Multiplier = 32'h0a_00_00_ff;    Data_register = {Multiplier, Multiplicand};  end	  initial begin			// Synchronize input data bytes   @ (posedge Start)		 	       repeat (15) begin        @ (negedge clock)              Data_register <= Data_register >> 8;      end  endendmoduleSimulation results: Loading multiplicand (0f0000aaH) and multiplier (0a0000ffH), 4 bytes each, in sequence, beginning with the least significant byte of the multiplicand.Note: Product is not valid until Done_Product asserts. The value of Product shown here (25510) reflects the contents of {C, A, Q} after the multiplier has been loaded, prior to multiplication.Note: The machine ignores a premature assertion of Run.Note: Got_Data asserts at the 8th clock after Start asserts, i.e., 8 clocks to load the data.Note: Product, Multiplier, and Multiplicand are formed in the test bench.
