				end      S_wait:	if (!Ld) next_state = S_wait;				else begin		  		  Ld_R0 = 1;		  		  if (En) begin Ld_P1_P0 = 1; next_state = S_1; end		  		  else begin Clr_P1_P0 = 1; next_state = S_idle; end				end      default:	next_state = S_idle;    endcase  endendmodulemodule Datapath_unit (  output reg [15: 0] 	R0,   input [7: 0] 			Data,   input 				Clr_P1_P0,   						Ld_P1_P0,   						Ld_R0,   						clock);   reg [7: 0] 	P1, P0;    always @ (posedge clock) begin    if (Clr_P1_P0) begin P1 <= 0; P0 <= 0; end    if (Ld_P1_P0) begin P1 <= Data; P0 <= P1; end    if (Ld_R0) R0 <= {P1, P0};  endendmodule// Test bench for integrated systemmodule t_Prob_8_41 ();  wire [15: 0] 	R0;  reg [7: 0] 	Data;  reg 			En, Ld, clock, rst;  Prob_8_41 M0 (R0, Data, En, Ld, clock, rst);  initial #200 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial begin rst = 0; #10 rst = 1; #20 rst = 0; end  initial fork        #20 Data = 8'ha5;    #50 Data = 8'hff;      #20 Ld = 0;    #20 En = 0;	    #30 En = 1;	// Drive to S_wait    #70 Ld = 1;	// Return to S_1 to S_full tp S_wait    #80 Ld = 0;     #100 Ld = 1;	// Drive to S_idle    #100 En = 0;    #110 En = 0;    #120 Ld = 0;  joinendmodule
