, Zero, data, Load_regs, Shift_left, Incr_R2, clock, reset_b);endmodule// Test plan for integrated system// Test for data values of 8'haa, 8'h00, 8'hff.// Test bench for integrated systemmodule t_count_Ones_BEH_BEH ();  parameter dp_width = 8, R2_width = 4;  wire [R2_width -1: 0] count;  reg [dp_width -1: 0] data;    reg Start, clock, reset_b;  Count_Ones_BEH_BEH M0 (count, data, Start, clock, reset_b);  initial #700 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial bebgin reset_b = 0; #2 reset_b = 1; enbd  initial fork    data = 8'haa;		// Expect count = 4    Start = 0;    #20 Start = 1;	    #30 Start = 0;    #40 data = 8'b00;	// Expect count = 0    #250 Start = 1;    #260 Start = 0;    #280 data = 8'hff;    #280 Start = 1;    #290 Start = 0;  joinendmodule

VHDLlibrary IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;entity Prob_8_42_Datapath_BEH_vhdl is	generic (dp_width: integer := 8; R2_width: integer := 4);		port (	count: out integer;  				E: out Std_Logic;				Zero: out Std_Logic; 				data: in Std_Logic_vector(dp_width -1 downto 0);				Load_regs, Shft_left, Incr_R2, clock, reset_b: in Std_Logic			);end Prob_8_42_Datapath_BEH_vhdl;architecture Behavioral of Prob_8_42_Datapath_BEH_vhdl is	signal R1: Std_Logic_vector (dp_width -1 downto 0);	signal R2: integer;begin	E <= R1(dp_width -1);	count <= R2;	process (R1) begin		Zero <= '1';		for k in (dp_width -1) downto 0 loop			if R1(k) /= '0' then Zero <= '0'; end if;		end loop;	end process;process  (clock) begin	if clock'event and clock = '1' then	if (Load_regs = '1') then 		R1 <= data; 		R2 <= 0;	end if;			if (Load_regs = '1') then		R1 <= data;		R2 <= 0;	end if;	if (Shft_left = '1') then 		R1 <=  (R1((dp_width-2) downto 0)) & '0'; 	end if;		    	if (Incr_R2 = '1') then 		R2 <= R2 + 1; 					end if;end if;end process;	-- (clock)end Behavioral;library IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;library Synopsys;use Synopsys.attributes.all;entity Controller_BEH is	port (Ready: out Std_Logic; 			Load_regs: out Std_Logic; 			Incr_R2, Shft_left: out Std_Logic; 			Start, Zero, E, clock, reset_b: in Std_Logic);end Controller_BEH;architecture Behavioral of Controller_BEH is	type State_type is (s0, s1, s2, s3);	attribute enum_encoding of State_type: type is "0 1 2 3";	signal state, next_state: State_type;begin	Ready <= '1' when (state = s0) else '0';	Incr_R2 <= '1' when (state = s1) else '0';	Shft_left <= '1' when (state = s2) else '0';	process (clock, reset_b) begin		if (reset_b = '0') then 			state <= s0; 		elsif clock'event and clock = '1' then  			state <= next_state; 		end if;	end process;		process (state, Start, Zero, E) begin    	Load_regs <= '0';    	case (state) is      	when s0 =>	if (Start = '1') then 								Load_regs <= '1'; next_state <= s1;  						else next_state <= s0; end if;      	when s1 =>	if (Zero = '1') then 								next_state <= s0; 						else next_state <= s2; 						end if;	      	when s2 =>	next_state <= s3;		when s3 =>	if (E = '1') then 							next_state <= s1; 						elsif (Zero = '1') then 							next_state <= s0; 						else next_state <= s2; 						end if;		when others =>	next_state <= s0;	end case;	end process;end Behavioral;library IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;-- Integrated systementity Count_Ones_BEH_BEH is	generic (dp_width: integer := 8; R2_width: integer := 4);	port (Ready: out Std_Logic; count: out Std_Logic_vector (R2_width downto 0);	data: in Std_Logic_vector(dp_width -1 downto 0); 		Start, clock, reset_b: in Std_Logic);end Count_Ones_BEH_BEH;architecture Structural of Count_Ones_BEH_BEH is	signal	Load_regs, Incr_R2, Shft_left, Zero, E: Std_Logic;	component Datapath_BEH port (count: out Std_Logic_vector (R2_width-1 downto 0);  E: out Std_Logic;			Zero: out Std_Logic; data: in Std_Logic_vector(dp_width -1 downto 0);			Load_regs, Shft_left, Incr_R2, clock, reset_b: in Std_Logic); 	end component;	component Controller_BEH port (Ready: out Std_Logic; Load_regs: out Std_Logic; 			Incr_R2, Shft_left: out Std_Logic; Start, Zero, E, clock, reset_b: in Std_Logic);	end component;begin	M0: Controller_BEH port map (Ready, Load_regs, Incr_R2, Shft_left, Start, Zero, E, clock, reset_b);	M1: Datapath_BEH port map (count, E, Zero, data, Load_regs, Shft_left, Incr_R2, clock, reset_b);end Structural;8.43 Answer:				SystemVerilogmodule divide_clock_by_4_SV (   input logic clk, rst_b,   output logic y);   typedef enum bit [3:0] {s0 = 4'b0001, s1 = 4'b0010, s2 = 4'b0100, s3 = 4'b1000} state_type_t;   state_type_t [3:0] state, next_state;// Output   assign y_out = (state == s3);// State transitions   always_ff @ (posedge clk, negedge rst_b)       if (!rst_b) state <= s0; else state <= next_state;   always_comb @ ( state)	 // Next state logic      case (state)         s0: next_state = s1;         s1: next_state = s2;         s2: next_state = s3;         s3: next_state = s0;	// case is complete – no default       endcaseendmodule				VHDLlibrary IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;entity Prob_8_43_divide_clock_by_4_SV_vhdl is		port (clk, rst_b: in Std_Logic; y: out Std_Logic);end Prob_8_43_divide_clock_by_4_SV_vhdl;architecture Behavioral of Prob_8_43_divide_clock_by_4_SV_vhdl is	subtype State_type is Std_Logic_vector (3 downto 0);	constant s0: State_type := "0001";	constant s1: State_type := "0010";	constant s2: State_type	:= "0100"; 		constant s3: State_type := "1000";	signal state, next_state: State_type;begin	-- Output	y <= '1' when (state = s3) else '0';	-- State transitions	process (clk, rst_b) begin       	if rst_b = '0' then  state <= s0;       	elsif clk'event and clk = '1' then state <= next_state; end if;	end process;	-- Next state logic	process (state) begin		next_state <= s0;      	case (state) is			when s0 => next_state <= s1;			when s1 => next_state <= s2;			when s2 => next_state <= s3;			when s3 => next_state <= s0;	 		when others => next_state <= s0;      end case;   end process;end Behavioral;
8.44 Answer:8.45 Answer: Nonblocking assignments in the same procedural block are executed concurrently. The order in which the statements are listed does not affect the outcome. There is no difference in the results produced by these two nonblocking assignments.8.46 Answer: (Verilog) Blocking assignment statements are executed immediately and sequentially, in the order in which they are listed. The statements in the two procedural blocks are listed in different order, and will therefore produce different results.8.47 Answer: The possible bit patterns of the case items are not exhausted, and there is no default assignment.8.48 Answer: It is not an acceptable coding practice to assign value to the same signal (q) in multiple procedural blocks. Synthesis tools will reject such a description; SystemVerilog does not allow such code.8.49 Answer: The latch responds to an event of enable. If enable is asserted, q gets the value of data. There is no change in q until a subsequent activating event of enable assigns a different value to q. Meanwhile, events of data are ignored because the sensitivity list does not include data. The behavior does not match that of a transparent latch. To repair the model, include data in the sensitivity list of the procedural block.8.50 Answer:8.51	Answer	typedef enum [2:0] {s0, s1, s2, s3, s4} state_type_t;	state_type_t [2: 0] state, next_state;8.52 Answer:	always_comb begin	   y1 = A + B; 	   y2 = A | B;	end8.53 	module Prob_8_53_sv (		   input logic [7:0] Data_in,		   input logic clk, rst, Load,		   output logic [7:0] Data_out		);		   always_ff (posedge clk, posedge rst) begin		      if (rst) Data_out <= 8'b0;		      else if (Load) Data_out <= Data_in;		   end		endmodule8.54	module Prob_8_54_sv (		   input logic [7:0] Data_in,		   input logic enable,		   output logic [7:0] Data_out		);		always_latch (enable, Data_in) begin		   if (enable) Data_out <= Data_in;		end		endmodule8.55	module decode