1;  always @ (posedge clock, negedge reset_b) if (reset_b == 0) state <= S0; else state <= next_state;  always @ (state, x) begin    y = 0;    case (state)       S0:	if (x) begin next_state = S0; y = 1; end else begin next_state = S1; y = 0; end      S1:	if (x) begin next_state = S3; y = 0; end else begin next_state = S2; y = 1; end      S2:	if (x) begin next_state = S1; y = 0; end else begin next_state = S0; y = 1; end      S3:	if (x) begin next_state = S2; y = 1; end else begin next_state = S3; y = 0; end    endcase  endendmodulemodule t_Figure_9_9a ();  wire y;  reg x, clock, reset_b;  Figure_9_9a M0 (y, x, clock, reset_b);  initial #200 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork    reset_b = 0;    x = 0;			// S0. S1, S2 after release of reset_b    #10 reset_b = 1;    #40 x = 1;		// Stay in S0    #60 x= 0;		// S1, S2    #80 x = 1;		//  s1, S3,     #100  x = 0;	// S3    #130 x = 1;		// S2, S1, S3 cycle  joinendmodule			(b) The solution depends on the particular design.			(c, d) Note: The HDL description of the state diagram produces outputs T0, T1, and T2. Additional logic must form the signals that control the datapath unit (Load_regs, Incr_P, Add_regs, and Shift_regs). An alternative controller that generates the control signals, rather than the states, as the outputs is given below too. It produces identical simulation results.module Supp_9_9cd # (parameter dp_width = 5) (  output 	[2*dp_width - 1: 0] 	Product,  output							Ready,  input 	[dp_width - 1: 0] 		Multiplicand, Multiplier,  input 							Start, clock, reset_b);  wire Load_regs, Incr_P, Add_regs, Shift_regs, Done, Q0;  Controller M0 (    Ready, Load_regs, Incr_P, Add_regs, Shift_regs, Start, Done, Q0,     clock, reset_b);Datapath M1(Product, Q0, Done, Multiplicand, Multiplier,  Start, Load_regs, Incr_P, Add_regs, Shift_regs, clock, reset_b);	endmodule/* // This alternative controller directly  produces the signals needed to control the datapath.module Controller (  output Ready,  output reg Load_regs, Incr_P, Add_regs, Shift_regs,     input Start, Done, Q0, clock, reset_b);  parameter	S_idle =		3'b001, 		// one-hot code        			S_add = 	3'b010, 		       			S_shift = 	3'b100;  reg	[2: 0]		state, next_state;		// sized for one-hot  assign		Ready = (state == S_idle);	    always @ (posedge clock, negedge reset_b)    if (~reset_b) state <= S_idle; else state <= next_state;  always @ (state, Start, Q0, Done) begin    next_state = S_idle;    Load_regs = 0;    Incr_P = 0;    Add_regs = 0;    Shift_regs = 0;    case (state)      S_idle:		if (Start) begin next_state = S_add; Load_regs = 1; end      S_add:	begin next_state = S_shift; Incr_P = 1; if (Q0) Add_regs = 1; end      S_shift:	begin Shift_regs = 1; 		  		  if (Done) next_state = S_idle; 		  		  else next_state = S_add;    end      default:	next_state = S_idle;    endcase  endendmodule*/// This controller has an embedded unit to generate T0, T1, and T2 and additional logic to form // // the signals needed to control the datapath.module Controller (  output Ready, Load_regs, Incr_P, Add_regs, Shift_regs,     input Start, Done, Q0, clock, reset_b);  State_Generator M0 (T0, T1, T2, Start, Done, Q0, clock, reset_b);  assign Ready = T0;  assign Load_regs = T0 && Start;  assign Incr_P = T1;  assign Add_regs = T1 && Q0;  assign Shift_regs = T2;endmodulemodule State_Generator (output T0,T1, T2, input Start, Done, Q0, clock, reset_b);  parameter		S_idle =	3'b001, 		// one-hot code        				S_add = 	3'b010, 		       				S_shift = 	3'b100;  reg	[2: 0]		state, next_state;		// sized for one-hot  assign 	T0 = (state == S_idle);  assign	T1 = (state == S_add);  assign	T2 = (state == S_shift);  always @ (posedge clock, negedge reset_b)    if (~reset_b) state <= S_idle; else state <= next_state;  
  always @ (state, Start, Q0, Done) begin    next_state = S_idle;    case (state)      S_idle:		if (Start) next_state = S_add;       S_add:	next_state = S_shift;       S_shift:	if (Done) next_state = S_idle; else next_state = S_add;       default:	next_state = S_idle;    endcase  endendmodulemodule Datapath #(parameter dp_width = 5, BC_size = 3) (  output [2*dp_width - 1: 0] Product, output Q0, output Done,  input [dp_width - 1: 0] Multiplicand, Multiplier,  input Start, Load_regs, Incr_P, Add_regs, Shift_regs, clock, reset_b);// Default configuration: 5-bit datapath  reg	[dp_width - 1: 0]		A, B, Q;				// Sized for datapath  reg 							C;  reg	[BC_size - 1: 0]		P;				// Bit counter    assign Q0 = Q[0];	  assign	Done = (P == dp_width ); 				// Multiplier is exhausted  assign Product = {C, A, Q};  always @ (posedge clock, negedge reset_b)     if (reset_b == 0) begin			// Added to this solution, but      P <= 0;  							// not really necessary since Load_regs      B <= 0;							// initializes the datapath      C <= 0;      A <= 0;      Q <= 0;    end     else begin    if (Load_regs) begin      P <= 0;       A <= 0;      C <= 0;      B <= Multiplicand;      Q <= Multiplier;    end    if (Add_regs) {C, A} <= A + B;    if (Shift_regs) {C, A, Q} <= {C, A, Q} >> 1;    if (Incr_P) P <= P+1 ;   endendmodule module t_Supp_9_9cd;  parameter					dp_width = 5;			// Width of datapath  wire	[2 * dp_width - 1: 0] 	Product;  wire							Ready;  reg 	[dp_width - 1: 0] 		Multiplicand, Multiplier;   reg 							Start, clock, reset_b;  integer						Exp_Value;  reg							Error;  Supp_9_9cd M0(Product, Ready, Multiplicand, Multiplier, Start, clock, reset_b);  initial #115000 $finish;  initial begin clock = 0; #5 forever #5 clock = ~clock; end 
 initial fork    reset_b = 1;    #2 reset_b = 0;    #3 reset_b = 1;  join  always @ (negedge Start) begin    Exp_Value = Multiplier * Multiplicand;    //Exp_Value = Multiplier * Multiplicand +1;	// Inject error to confirm detection  end  always @ (posedge Ready) begin    # 1 Error <= (Exp_Value ^ Product) ;  end  initial begin    #5 Multiplicand = 0;    Multiplier = 0;        repeat (32) #10 begin        Start = 1;        #10 Start = 0;        repeat (32) begin          Start = 1;          #10 Start = 0;                    #100 Multiplicand = Multiplicand + 1;        end      Multiplier = Multiplier + 1;    end  endendmoduleSupplement to Experiment #10:module Counter_74161 (  output  		QD, QC, QB, QA,		// Data output  output 		COUT,					// Output carry  input	 		D, C, B, A,				// Data input   input 		P, T, 					// Active high to count				L, 						// Active low to load				CK, 					// Positive edge sensitive				CLR					// Active low to clear);    reg [3: 0] A_count;  assign QD = A_count[3];  assign QC = A_count[2];  assign QB = A_count[1];  assign QA = A_count[0];  assign COUT = ((P == 1) && (T == 1) && (L == 1) && (A_count == 4'b1111));  always @ (posedge CK, negedge CLR)    if (CLR == 0) 			A_count <= 4'b0000;    else if (L == 0)			A_count <= {D, C, B, A};    else if ((P == 1) && (T == 1)) 	A_count <= A_count + 1'b1;    else A_count <= A_count;	// redundant statementendmodulemodule t_Counter_74161 ();  wire 			QD, QC, QB, QA;  wire [3: 0] 	Data_outputs = {QD, QC, QB, QA};  wire 			Carry_out;			// Output carry  reg [3:0] 		Data_inputs;		// Data input   reg 			Count, 			// Active high to count				Load, 				// Active low to load				Clock, 				// Positive edge sensitive				Clear;				// Active low to clear Counter_74161 M0 (QD, QC, QB, QA, Carry_out,  Data_inputs[3], Data_inputs[2], Data_inputs[1], Data_inputs[0], Count, Count, Load, Clock, Clear);  initial #200 $finish;  initial begin Clock = 0; forever #5 Clock = ~Clock; end  initial fork    Clear = 0;    Load = 1;    Count = 0;    #20 Clear = 1;    #40 Load = 0;    #50 Load = 1;    #80 Count = 1;    #180 Count = 0;    Data_inputs = 4'ha;		// 10  joinendmoduleSupplement to Experiment #11.			(a)			// Note: J and K_bar are assumed to be connected together.module SReg_74195 (  output reg QA, QB, QC, QD,   output QD_bar,   input A, B, C, D, SH_LD, J, K_bar, CLR_bar, CK);  assign QD_bar = ~QD;  always @ (posedge CK, negedge CLR_bar)    if (!CLR_bar) {QA, QB, QC, QD} <= 4'b0;    else if (!SH_LD) {QA, QB, QC, QD} <= {A, B, C, D};    else case ({J, K_bar})      2'b00: 	{QA, QB, QC, QD} <= {1'b0, QA, QB, QC};      2'b11: 	{QA, QB, QC, QD} <= {1'b1, QA, QB, QC};	      2'b01:	{QA, QB, QC, QD} <= {QA, QA, QB, QC};	// unused      2'b10:	{QA, QB, QC, QD} <= {~QA, QA, QB, QC};	// unused    endcaseendmodulemodule t_SReg_74195 ();  wire QA, QB, QC, QD;   wire QD_bar;  reg A, B, C, D, SH_LD, CLR_bar, CK;  reg	Serial_Input;  wire J = Serial_Input;  wire K_bar = Serial_Input;  wire [3: 0] Data_inputs = {A, B, C, D};  wire [3: 0] Data_outputs = {QA, QB, QC, QD};  SReg_74195 M0 (QA, QB, QC, QD, QD_bar, A, B, C, D, SH_LD, J, K_bar, CLR_bar, CK);  initial #200 $finish;  initial begin CK = 0; forever #5 CK = ~CK; end  initial fork    {A, B, C, D} = 4'ha;    CLR_bar = 0;    Serial_Input = 0;    SH_LD = 0;    #30 CLR_bar = 1;    #60 SH_LD = 1;    #120 Serial_Input = 1;  joinendmodule			
(b)module Mux_74157 (  output reg Y1, Y2, Y3, Y4,   input A1, A2, A3, A4, B1, B2, B3, B4, SEL, STB);  wire [4: 1] In_A = {A1, A2, A3, A4};  wire [4: 1] In_B = {B1, B2, B3, B4};  always @ (In_A, In_B, SEL, STB)    if (STB) {Y1, Y2, Y3, Y4} = 4'b0;    else if (SEL) {Y1, Y2, Y3, Y4} = In_B;    else {Y1, Y2, Y3, Y4} = In_A;endmodule module t_Mux_74157 ();  wire Y1, Y2, Y3, Y4;   reg A1, A2, A3, A4, B1, B2, B3, B4, SEL, STB;  wire [4: 1] In_A = {A1, A2, A3, A4};  wire [4: 1] In_B = {B1, B2, B3, B4};  wire [4: 1] Y = {Y1, Y2, Y3, Y4};  Mux_74157 M0 (Y1, Y2, Y3, Y4, A1, A2, A3, A4, B1, B2, B3, B4, SEL, STB);  initial #200 $finish;  initial fork    {A1, A2, A3, A4} = 4'ha;    {B1, B2, B3, B4} = 4'hb;    STB = 1;    SEL = 1;    #50 STB = 0;    #100 SEL = 0;    #150 STB = 1;  joinendmodule			(c)module Bi_Dir_Shift_Reg (output [1: 4] D_out, input [1: 4] D_in, input SEL, STB, SH_LD, clock, CLR_bar);  wire 			QD_bar;  wire [1: 4] 	Y;  SReg_74195 M0 (D_out[1], D_out[2], D_out[3], D_out[4], QD_bar, Y[1], Y[2], Y[3], Y[4],     SH_LD, D_out[4], D_out[4], CLR_bar, clock  );    Mux_74157 M1 (Y[1], Y[2], Y[3], Y[4], D_in[1], D_in[2], D_in[3], D_in[4], 						     D_out[2], D_out[3], D_out[4], D_out[1], SEL, STB		   );endmodulemodule SReg_74195 (  output reg 	QA, QB, QC, QD,   output 		QD_bar,   input 		A, B, C, D, SH_LD, J, K_bar, CLR_bar, CK);  assign 		QD_bar = ~QD;  always @ (posedge CK, negedge CLR_bar)    if (!CLR_bar) {QA, QB, QC, QD} <= 4'b0;    else if (!SH_LD) {QA, QB, QC, QD} <= {A, B, C, D};    else case ({J, K_bar})      2'b00: 	{QA, QB, QC, QD} <= {1'b0, QA, QB, QC};      2'b11: 	{QA, QB, QC, QD} <= {1'b1, QA, QB, QC};	      2'b01:	{QA, QB, QC, QD} <= {QA, QA, QB, QC};	// unused      2'b10:	{QA, QB, QC, QD} <= {~QA, QA, QB, QC};	// unused    endcaseendmodulemodule Mux_74157 (  output reg Y1, Y2, Y3, Y4,   input A1, A2, A3, A4, B1, B2, B3, B4, SEL, STB);  wire [4: 1] In_A = {A1, A2, A3, A4};  wire [4: 1] In_B = {B1, B2, B3, B4};  always @ (In_A, In_B, SEL, STB)    if (STB) {Y1, Y2, Y3, Y4} = 4'b0;    else if (SEL) {Y1, Y2, Y3, Y4} = In_B;	 // SEL = 1    else {Y1, Y2, Y3, Y4} = In_A;	 			// SEL = 0endmodulemodule t_Bi_Dir_Shift_Reg ();  wire [1: 4] D_out;  reg [1: 4] D_in;  reg SEL, STB, SH_LD, clock, CLR_bar;  Bi_Dir_Shift_Reg M0 (D_out, D_in, SEL, STB, SH_LD, clock, CLR_bar);  initial #200 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork    D_in = 4'h8;		// Data for walking 1 to right    CLR_bar = 0;    STB = 0;    SEL = 0;			// Selects D_in    SH_LD = 0;			// load D_in    #10 CLR_bar = 1;     #20 STB = 1;    #40 STB = 0;    #30 SH_LD = 1;	     #50 SH_LD = 0;	// Interrupt count to load    #60 SH_LD = 1;    #80 SEL = 1;    #100 STB = 1;    #130 STB = 0;    #140 SH_LD = 0;    //#150 SH_LD = 1;  joinendmodule			The behavioral model is listed below. The two models have matching simulation results.module Bi_Dir_Shift_Reg_beh (output reg [1: 4] D_out, input [1: 4] D_in, input SEL, STB, SH_LD, clock, CLR_bar);  always @ (posedge clock, negedge CLR_bar)    if (!CLR_bar) D_out <= 4'b0;    else if (SH_LD ) D_out <= {D_out[4], D_out[1], D_out[2], D_out[3]};   else if (!STB) D_out <= SEL ? {D_out[2: 4], D_out[1]}: D_in;    else D_out <= 4'b0; endmodulemodule t_Bi_Dir_Shift_Reg_beh ();  wire [1: 4] D_out;  reg [1: 4] D_in;  reg SEL, STB, SH_LD, clock, CLR_bar;  Bi_Dir_Shift_Reg_beh M0 (D_out, D_in, SEL, STB, SH_LD, clock, CLR_bar);  initial #200 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork    D_in = 4'h8;		// Data for walking 1 to right    CLR_bar = 0;    STB = 0;    SEL = 0;		// Selects D_in    SH_LD = 0;		// load D_in    #10 CLR_bar = 1;     #20 STB = 1;    #40 STB = 0;    #30 SH_LD = 1;	     #50 SH_LD = 0;	// Interrupt count to load    #60 SH_LD = 1;    #80 SEL = 1;    #100 STB = 1;    #130 STB = 0;    #140 SH_LD = 0;    //#150 SH_LD = 1;  joinendmoduleSupplement to Experiment #13.module RAM_74189 (output S4, S3, S2, S1, input D4, D3, D2, D1, A3, A2, A1, A0, CS, WE);// Note: active-low CS and WE  wire [3: 0] 				address = {A3, A2, A1, A0};   reg [3: 0] 				RAM [0: 15];			// 16 x 4 memory  wire [4: 1] 				Data_in = { D4, D3, D2, D1};	// Input word  tri [4: 1] 					Data;				// Output data word, three-state output  assign S1 = Data[1];			// Output bits  assign S2 = Data[2];  assign S3 = Data[3];  assign S4 = Data[4];  always @ (Data_in, address, CS, WE) if (~CS && ~WE) RAM[address] = Data_in;  assign Data = (~CS && WE) ? ~RAM[address] : 4'bz; endmodulemodule t_RAM_74189 ();  reg [4: 1] Data_in;  reg [3: 0] address;  reg CS, WE;  wire S1, S2, S3, S4;  wire D1, D2, D3, D4;  wire A0, A1, A2, A3;  wire [4: 1] Data_out = {S4, S3, S2, S1};  assign  D1 = Data_in [1];  assign  D2 = Data_in [2];  assign  D3 = Data_in [3];  assign  D4 = Data_in [4];  assign A0 = address[0];  assign A1 = address[1];  assign A2 = address[2];   assign A3 = address[3];   wire [3: 0] RAM_0 = M0.RAM[0];  wire [3: 0] RAM_1 = M0.RAM[1];  wire [3: 0] RAM_2 = M0.RAM[2];  wire [3: 0] RAM_3 = M0.RAM[3];  wire [3: 0] RAM_4 = M0.RAM[4];  wire [3: 0] RAM_5 = M0.RAM[5];  wire [3: 0] RAM_6 = M0.RAM[6];  wire [3: 0] RAM_7 = M0.RAM[7];  wire [3: 0] RAM_8 = M0.RAM[8];  wire [3: 0] RAM_9 = M0.RAM[9];  wire [3: 0] RAM_10 = M0.RAM[10];  wire [3: 0] RAM_11 = M0.RAM[11];  wire [3: 0] RAM_12= M0.RAM[12];  wire [3: 0] RAM_13 = M0.RAM[13];  wire [3: 0] RAM_14 = M0.RAM[14];  wire [3: 0] RAM_15 = M0.RAM[15];  wire [4: 1] word = ~Data_out;  RAM_74189 M0 (S4, S3, S2, S1, D4, D3, D2, D1, A3, A2, A1, A0, CS, WE);  initial #110 $finish;  initial fork    WE = 1;    CS = 1;     address = 0;    Data_in = 3;    #10 CS = 0;    #15 WE = 0;    #20 WE = 1;    #25 address = 14;    #25 Data_in = 1;    #30 WE = 0;    #35 WE = 1;    #40 CS = 1;    #50 address = 0;    #60 CS = 0;    #70 CS = 1