  initial fork    CLR = 0;    {A, B, C, D} = 4'hf;     s1 = 0;    s0 = 0;    SIL = 0;    SIR = 0;    #10 CLR = 1;    #30 begin s1 = 1; s0 = 1; end	// load    #40   s1 = 0;	// shift right    #100   s1 = 1;	// load    #110 begin s1 = 0; s0 = 0; end    #140 s1 = 1;	// shift left    #160 s1 = 0;     // pause    #180 s1 = 1;	// resume   joinendmodule
Supplement to Experiment #16. The HDL behavioral descriptions of the components in the block diagram of Fig. 9.23 are described in the solutions of previous experiments, along with their test benches and simulations results: 74189 is described in Experiment 13(a); 74157 in Experiment 11(b);  74161 in Experiment 10; 7483 in Experiment 7(a); 74194 in Experiment 14; and 7474 in Experiment 8(a). The structural description of the parallel adder instantiates these components to show how they are interconnected (see the solution to the supplement for Experiment 17 for a similar procedure). A test bench and simulation results for the  integrated unit are given below.// LOAD condition for 74194: s1 = 1, s0 = 1// SHIFT condition: s1 = 0, s0 = 1// NO CHANGE condition: s1 = 0, s0 = 0module Supp_9_16 (  output [3: 0] accum_sum,   output carry,   input [3: 0] Data_in, Addr_in,   input SIR, SIL, CS, WE, s1, s0, count, Load, select, STB, clock, preset, clear, VCC, GND);  wire B4 = Data_in[3];	// Data world to memory  wire B3 = Data_in[2];    wire B2 = Data_in[1];    wire B1 = Data_in[0];  wire S4, S3, S2, S1;  wire D4, D3, D2, D1;  wire S4b = ~S4;	// Inverters  wire S3b = ~S3;  wire S2b = ~S2;  wire S1b = ~S1;  wire D = Addr_in[3];	// For parallel load of address counter  wire C = Addr_in[2];  wire B = Addr_in[1];  wire A = Addr_in[0];  wire Ocar, Y1, Y2, Y3, Y4, QA, QB, QC, QD, A3, A2, A1, A0;  assign accum_sum = {D4, D3, D2, D1};   Flip_flop_7474 	M0 (Ocar, carry, clock, preset, clear);   Adder_7483 	M1 (D4, D3, D2, D1, carry, S4b, S3b, S2b, S1b, QD, QC, QB, QA, Ocar, VCC, GND);  Mux_74157 	M2 (Y4, Y3, Y2, Y1, QD, QC, QB, QA, B4, B3, B2, B1, select, STB);  Counter_74161 	M3 (A3, A2, A1, A0, COUT, D, C, B, A, count, count, Load, clock, clear);  RAM_74189 	M4 (S4, S3, S2, S1, Y4, Y3, Y2, Y1, A3, A2, A1, A0, CS, WE);  Reg_74194	M5 (QD, QC, QB, QA, D4, D3, D2, D1, Ocar, SIL, s1, s0, clock, clear);endmodulemodule t_Supp_9_16 ();  wire [3: 0] sum;  wire carry;  reg [3: 0] Data_in, Addr_in;   reg SIR, SIL, CS, WE, s1, s0, count, Load, select, STB, clock, preset, clear;  supply1 VCC;  supply0 GND;  wire [3: 0] RAM_0 = M0.M4.RAM[0];  wire [3: 0] RAM_1 = M0.M4.RAM[1];  wire [3: 0] RAM_2 = M0.M4.RAM[2];  wire [3: 0] RAM_3 = M0.M4.RAM[3];  wire [3: 0] RAM_4 = M0.M4.RAM[4];  wire [3: 0] RAM_5 = M0.M4.RAM[5];  wire [3: 0] RAM_6 = M0.M4.RAM[6];  wire [3: 0] RAM_7 = M0.M4.RAM[7];  wire [3: 0] RAM_8 = M0.M4.RAM[8];  wire [3: 0] RAM_9 = M0.M4.RAM[9];  wire [3: 0] RAM_10 = M0.M4.RAM[10];  wire [3: 0] RAM_11 = M0.M4.RAM[11];  wire [3: 0] RAM_12= M0.M4.RAM[12];  wire [3: 0] RAM_13 = M0.M4.RAM[13];  wire [3: 0] RAM_14 = M0.M4.RAM[14];  wire [3: 0] RAM_15 = M0.M4.RAM[15];  wire [4: 1] word = {M0.S4b, M0.S3b,M0.S2b, M0.S1b}; wire [4: 1] mux_out = { M0.Y4, M0.Y3, M0.Y2, M0.Y1}; wire [4: 1] Reg_Output = {M0.QD, M0.QC, M0.QB, M0.QA}; Supp_9_16 M0 (sum, carry, Data_in, Addr_in, SIR, SIL, CS, WE, s1, s0, count, Load,   select, STB,   clock, preset, clear, VCC, GND);  integer k;  initial #600 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork    #10 begin preset = 1; clear = 0; s1 = 0; s0 = 0; Load = 1; count = 0; CS = 1; WE = 1; STB = 0;  end    // initialize memory    #10 begin k = 0; repeat (16) begin M0.M4.RAM[k] = 4'hf; k = k + 1; end end    #20 begin Data_in = 4'hf; Addr_in  = 0; select = 1; end    #30 begin clear = 1; WE = 0; end      // load memory    #40 begin       count = 1;       CS = 0;      begin         repeat (16) @ (negedge clock) Data_in = Data_in + 1;            count = 0;        @ (negedge clock) CS = 1;      end        end     #200 count = 1;				// Establish address    #240 count = 0;    #250 WE = 1;    #260 CS = 0;					// Read from memory    #280 clear = 0;    #290 clear = 1;    #300 count = 1;				// Establish address     #340 begin s1 = 1; s0 = 1; count = 0; end    #390 CS = 0;    #400 clear = 0;				// Clear the registers    #410 clear = 1;    #420 begin count = 1; CS = 0; end		// Accumulate values    #490 begin count = 0; CS = 1; end  joinendmodulemodule Flip_flop_7474 (output reg Q, input D, CLK, preset, clear); always @ (posedge CLK, negedge preset , negedge clear)if (!preset)     	Q <= 1'b1;else if (!clear) 	Q <= 1'b0;else 	Q <= D;endmodulemodule Adder_7483 (  output S4, S3, S2, S1, C4,  input A4, A3, A2, A1, B4, B3, B2, B1, C0, VCC, GND);// Note: connect VCC and GND to supply1 and supply0 in the test bench  wire [4: 1] sum;  wire [4: 1] A = {A4, A3, A2, A1};  wire [4: 1] B = {B4, B3, B2, B1};  assign S4 = sum[4];  assign S3 = sum[3];  assign S2 = sum[2];  assign S1 = sum[1];  assign {C4, sum} = A + B + C0;endmodulemodule Mux_74157 (  output reg Y1, Y2, Y3, Y4,   input A1, A2, A3, A4, B1, B2, B3, B4, SEL, STB);  wire [4: 1] In_A = {A1, A2, A3, A4};  wire [4: 1] In_B = {B1, B2, B3, B4};  always @ (In_A, In_B, SEL, STB)    if (STB) {Y1, Y2, Y3, Y4} = 4'b0;    else if (SEL) {Y1, Y2, Y3, Y4} = In_B;    else {Y1, Y2, Y3, Y4} = In_A;endmodulemodule Counter_74161 (  output  	QD, QC, QB, QA,		// Data output  output 	COUT,			// Output carry  input	 	D, C, B, A,		// Data input   input 	P, T, 			// Active high to count			L, 			// Active low to load			CK, 			// Positive edge sensitive			CLR			// Active low to clear);reg [3: 0] A_count;assign QD = A_count[3];assign QC = A_count[2];assign QB = A_count[1];assign QA = A_count[0];assign COUT = ((P == 1) && (T == 1) && (L == 1) && (A_count == 4'b1111));
always @ (posedge CK, negedge CLR)if (CLR == 0) 						A_count <= 4'b0000;else if (L == 0)					A_count <= {D, C, B, A};else if ((P == 1) && (T == 1)) 	A_count <= A_count + 1'b1;else 								A_count <= A_count;	// redundant statementendmodulemodule RAM_74189 (output S4, S3, S2, S1, input D4, D3, D2, D1, A3, A2, A1, A0, CS, WE);// Note: active-low CS and WE  wire [3: 0] 	address = {A3, A2, A1, A0};   reg [3: 0] 	RAM [0: 15];			// 16 x 4 memory  wire [4: 1] 	Data_in = { D4, D3, D2, D1};	// Input word  tri [4: 1] 		Data;				// Output data word, three-state output  assign S1 = Data[1];			// Output bits  assign S2 = Data[2];  assign S3 = Data[3];  assign S4 = Data[4];  always @ (Data_in, address, CS, WE) if (~CS && ~WE) RAM[address] = Data_in;  assign Data = (~CS && WE) ? ~RAM[address] : 4'bz; 	// Note complement of data wordendmodulemodule Reg_74194 (  output reg 	QA, QB, QC, QD,  input 		A, B, C, D, SIR, SIL, s1, s0, CK, CLR);  always @ (posedge CK, negedge CLR)    if (!CLR) {QA, QB, QC, QD} <= 4'b0;    else case ({s1, s0})      2'b00:	{QA, QB, QC, QD} <= {QA, QB, QC, QD};      2'b01:	{QA, QB, QC, QD} <= {SIR, QA, QB, QC};      2'b10:	{QA, QB, QC, QD} <= {QB, QC, QD, SIL};      2'b11:	{QA, QB, QC, QD} <= {A, B, C, D};    endcaseendmoduleSimulation results: initializing memory to 4'hf, then writing to memory. Note: the values of the inputs are ambiguous until the clear signal is asserted. Signals Ocar and carry are ambiguous because the output of memory is high-z until memory is read is read.Supplement to Experiment #17.The HDL behavioral descriptions of the components in the block diagram of Fig. 9.23 are described in the solutions of previous experiments, along with their test benches and simulations results: 74161 in Experiment 10; 7483 in Experiment 7(a); 74194 in Experiment 14; and 7474 in Experiment 8(a). The structural description of the parallel adder instantiates these components to show how they are interconnected (see the solution to the supplement for Experiment 17 for a similar procedure). A test bench and simulation results for the  integrated unit are given below.
// Control unit is obtained by modifying the solution to Prob. 8.24.// Datapath is implemented with a structural  HDL model and IC components.// LOAD condition for 74194: s1 = 1, s0 = 1// SHIFT condition: s1 = 0, s0 = 1// NO CHANGE condition: s1 = 0, s0 = 0module Supp_9_17_Par_Mult # (parameter dp_width = 4) (  output 	[2*dp_width - 1: 0] 	Product,  output							Ready,  input 	[dp_width - 1: 0] 			Multiplicand, Multiplier,  input 								Start, clock, reset_b, VCC, GND);  wire Load_regs, Incr_P, Add_regs, Shift_regs, Done, Q0;  Controller M0 (    Ready, Load_regs, Incr_P, Add_regs, Shift_regs, Start, Done, Q0,     clock, reset_b);  Datapath M1(Product, Q0, Done, Multiplicand, Multiplier,  Start, Load_regs, Incr_P, Add_regs, Shift_regs, clock, reset_b, VCC, GND);	endmodulemodule Controller (  output Ready,  output reg Load_regs, Incr_P, Add_regs, Shift_regs,     input Start, Done, Q0, clock, reset_b);  parameter	S_idle =	3'b001, 		// one-hot code        			S_add = 3'b010, 		       			S_shift = 3'b100;  reg	[2: 0]	state, next_state;		// sized for one-hot  assign		Ready = (state == S_idle);	    always @ (posedge clock, negedge reset_b)    if (~reset_b) state <= S_idle; else state <= next_state;  always @ (state, Start, Q0, Done) begin    next_state = S_idle;    Load_regs = 0;    Incr_P = 0;    Add_regs = 0;    Shift_regs = 0;    case (state)      S_idle:	if (Start) begin next_state = S_add; Load_regs = 1; end      S_add:	begin next_state = S_shift; Incr_P = 1; if (Q0) Add_regs = 1; end      S_shift:	begin 		  		  Shift_regs = 1; 		  		  if (Done) next_state = S_idle; 		  		  else next_state = S_add;    end      default:	next_state = S_idle;    endcase  endendmodulemodule Datapath #(parameter dp_width = 4, BC_size = 3) (  output [2*dp_width - 1: 0] Product, output Q0, output Done,  input [dp_width - 1: 0] Multiplicand, Multiplier,  input Start, Load_regs, Incr_P, Add_regs, Shift_regs, clock, clear, VCC, GND);  wire C;  wire Cout, Sum3, Sum2, Sum1, Sum0, P3, P2, P1, P0, A3, A2, A1, A0;  wire Q3, Q2, Q1;  wire [dp_width -1: 0] A = {A3, A2, A1, A0};  wire [dp_width -1: 0] Q = {Q3, Q2, Q1, Q0};  assign Product = {C, A, Q};   wire [ BC_size -1: 0] P = {P3, P2, P1, P0};// Registers must be controlled separately to execute add and shift operations correctly.// LOAD condition for 74194: s1 = 1, s0 = 1// SHIFT condition: s1 = 0, s0 = 1// NO CHANGE condition: s1 = 0, s0 = 0    wire B3 = Multiplicand[3];		// Data word to adder  wire B2 = Multiplicand[2];    wire B1 = Multiplicand[1];    wire B0 = Multiplicand[0];  wire Q3_in = Multiplier[3];  wire Q2_in = Multiplier[2];  wire Q1_in = Multiplier[1];  wire Q0_in = Multiplier[0];  assign Done = ({P3, P2, P1, P0} == dp_width);		// Counts bits of multiplier  wire s1A = Load_regs || Add_regs;			// Controls for A register  wire s0A = Load_regs || Add_regs || Shift_regs;  wire s0Q = Load_regs || Shift_regs;			// Controls for Q register  wire s1Q = Load_regs;   wire Pout;						// Unused  wire clr_P = clear && ~Load_regs;  Flip_flop_7474 	M0_C (C, Cout, clock, VCC, clr_P);   Adder_7483 	M1 (Sum3, Sum2, Sum1, Sum0, Cout, A3, A2, A1, A0, B3, B2, B1, B0, GND, VCC, GND);  Counter_74161 	M3_P (P3, P2, P1, P0, Pout, GND, GND, GND, GND, Incr_P, Incr_P, VCC, clock, clr_P);  Reg_74194	M4_A (A3, A2, A1, A0, Sum3, Sum2, Sum1, Sum0, C, GND, s1A, s0A, clock, clr_P);  Reg_74194	M5_Q (Q3, Q2, Q1, Q0, Q3_in, Q2_in, Q1_in, Q0_in, A0, GND, s1Q, s0Q, clock, clear);endmodulemodule t_Supp_9_17_Par_Mult;  parameter			dp_width = 4;			// Width of datapath  wire	[2 * dp_width - 1: 0] 	Product;  wire				Ready;  reg 	[dp_width - 1: 0] 		Multiplicand, Multiplier;   reg 				Start, clock, reset_b;  integer				Exp_Value;  reg				Error;  supply0			GND;  supply1			VCC;  Supp_11_17_Par_Mult M0 (Product, Ready, Multiplicand, Multiplier, Start, clock, reset_b, VCC, GND);  wire [dp_width -1: 0] sum = {M0.M1.Sum3, M0.M1.Sum2, M0.M1.Sum1, M0.M1.Sum0};  initial #115000 $finish;  initial begin clock = 0; #5 forever #5 clock = ~clock; end  initial fork    reset_b = 1;    #2 reset_b = 0;    #3 reset_b = 1;  join  always @ (negedge Start) begin    Exp_Value = Multiplier * Multiplicand;    //Exp_Value = Multiplier * Multiplicand +1;	// Inject error to confirm detection  end  
always @ (posedge Ready) begin    # 1 Error <= (Exp_Value ^ Product) ;  end  initial begin    #5 Multiplicand = 0;    Multiplier = 0;    repeat (32) #10 begin        Start = 1;        #10 Start = 0;        repeat (32) begin          Start = 1;          #10 Start = 0;                    #100 Multiplicand = Multiplicand + 1;        end      Multiplier = Multiplier + 1;    end  endendmodulemodule Flip_flop_7474 (output reg Q, input D, CLK, preset, clear); always @ (posedge CLK, negedge preset , negedge clear)if (!preset)     	Q <= 1'b1;else if (!clear) 	Q <= 1'b0;else 	Q <= D;endmodulemodule Adder_7483 (  output S4, S3, S2, S1, C4,  input A4, A3, A2, A1, B4, B3, B2, B1, C0, VCC, GND);// Note: connect VCC and GND to supply1 and supply0 in the test bench  wire [4: 1] sum;  wire [4: 1] A = {A4, A3, A2, A1};  wire [4: 1] B = {B4, B3, B2, B1};  assign S4 = sum[4];  assign S3 = sum[3];  assign S2 = sum[2];  assign S1 = sum[1];  assign {C4, sum} = A + B + C0;endmodulemodule Counter_74161 (  output  	QD, QC, QB, QA,		// Data output  output 		COUT,			// Output carry  input	 	D, C, B, A,		// Data input   input 		P, T, 			// Active high to count		L, 			// Active low to load		CK, 			// Positive edge sensitive		CLR			// Active low to clear);reg [3: 0] A_count;assign QD = A_count[3];assign QC = A_count[2];assign QB = A_count[1];assign QA = A_count[0];assign COUT = ((P == 1) && (T == 1) && (L == 1) && (A_count == 4'b1111));always @ (posedge CK, negedge CLR)if (CLR == 0) 			A_count <= 4'b0000;else if (L == 0)			A_count <= {D, C, B, A};else if ((P == 1) && (T == 1)) 	A_count <= A_count + 1'b1;else 				A_count <= A_count;	// redundant statementendmodulemodule Reg_74194 (  output reg QA, QB, QC, QD,  input A, B, C, D, SIR, SIL, s1, s0, CK, CLR);  always @ (posedge CK, negedge CLR)    if (!CLR) {QA, QB, QC, QD} <= 4'b0;    else case ({s1, s0})      2'b00:	{QA, QB, QC, QD} <= {QA, QB, QC, QD};      2'b01:	{QA, QB, QC, QD} <= {SIR, QA, QB, QC};      2'b10:	{QA, QB, QC, QD} <= {QB, QC, QD, SIL};      2'b11:	{QA, QB, QC, QD} <= {A, B, C, D};    endcaseendmodule
